    #[test]
    #[ignore = "requires MC_PROGRESSION_PUBLIC_REPLAY and MC_PROGRESSION_PUBLIC_INPUTS from an actual recorded route"]
    fn public_combat_progression_survives_real_save_and_entry_reset() {
        use crate::game_runtime::{GameRuntime, ReplayOperation};

        let started = std::time::Instant::now();
        // The old save supplies inputs and its actual entry geometry, not a
        // trusted old state receipt or an invented campaign completion.
        let trace_bytes = std::fs::read(std::env::var_os("MC_PROGRESSION_PUBLIC_REPLAY").unwrap()).unwrap();
        let trace: Mc2CampaignReplaySave = serde_json::from_slice(&trace_bytes).unwrap();
        assert!(trace.verify());
        let input: serde_json::Value = serde_json::from_slice(
            &std::fs::read(std::env::var_os("MC_PROGRESSION_PUBLIC_INPUTS").unwrap()).unwrap(),
        ).unwrap();
        assert_eq!(input["replaySha256"].as_str().unwrap(), hex_digest(Sha256::digest(&trace_bytes).into()));
        assert!(trace.global_context_changes.is_empty());
        assert!(trace.dynamic_lighting_changes.is_empty());
        assert!(trace.primary_visibility_changes.is_empty());
        assert_eq!(trace.initial_global_context, GlobalSpecialState::default());
        assert_eq!(trace.initial_dynamic_lighting, default_dynamic_lighting());
        assert!(trace.initial_mission_rewards.is_none());
        assert_eq!(input["startingTick"].as_str().unwrap().parse::<u64>().unwrap(), trace.expected_tick);
        let extra: Vec<GameCommand> = serde_json::from_value(input["commands"].clone()).unwrap();
        let generated = std::env::var_os("MC_PROGRESSION_GENERATED_ROOT")
            .map(PathBuf::from)
            .unwrap_or_else(|| PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../../generated"));
        // These are the exact owner packages and caches used by the public
        // recorder; a similarly named Level 1 package has a different graph.
        let owner = generated.join("settlement-20261105-integration/owner-closed-v6");
        let root = owner.join("level1");
        let cache = owner.join("environment-complete/cache-level1");
        let next_root = generated.join("mc-level2-vault-successor-closure-20261025");
        let next_cache = generated.join("mc-b9s2-cursor-level2-vault-20261029");
        let resolver = Mc2RuntimePackageResolver::load([
            Mc2CampaignInputs::with_owner_cache(&root, &cache),
            Mc2CampaignInputs::with_owner_cache(&next_root, &next_cache),
            Mc2CampaignInputs::with_owner_cache(owner.join("level3"), owner.join("environment-complete/cache-level3")),
            Mc2CampaignInputs::with_owner_cache(
                generated.join("mc-bhq6-ordinary-20261025-zclu5fjj/level4"),
                generated.join("mc-b9s2-cursor-level4-20261029"),
            ),
        ]).unwrap();
        let mut session = GameSession::open(
            &Mc2CampaignAdapter,
            Arc::new(trace.definition.clone()),
            61901,
            Mc2CampaignInputs::with_owner_cache(&root, &cache),
        ).unwrap();
        session.backend_mut().apply_semantic_spell_carry(&trace.semantic_spell_carry).unwrap();
        assert!(trace.voxel_mode_changes.len() <= 1);
        if let Some(change) = trace.voxel_mode_changes.first() {
            assert_eq!(change.before_operation, 0);
            let generation = session.identity().generation;
            session.backend_mut().apply_voxel_mode_change(change.clone(), generation).unwrap();
        }
        let initial = session.backend().semantic_spell_carry().unwrap();
        let initial_fire = session.backend().campaign.simulation().shared_spells().local_player().runtime_spell_experience[0];
        eprintln!("progression: loaded route at {:?}", started.elapsed());
        for (index, operation) in trace.operations.iter().enumerate() {
            let ReplayOperation::Step { command } = operation else {
                panic!("this recorded combat route must contain gameplay inputs only");
            };
            session.advance(guard(&session), command.clone()).unwrap();
            if (index + 1) % 50 == 0 {
                eprintln!("progression: checkpoint input {} at {:?}", index + 1, started.elapsed());
            }
        }
        // The captured checkpoint is the first real hit on source slot 54.
        // Pin its current generation before observing the remaining inputs.
        let simulation = session.backend().campaign.simulation();
        let target = simulation.ordinary().villagers().iter()
            .find(|row| row.entity_index == 54 && row.active).expect("recorded target");
        assert!((0..1_000).contains(&target.life), "checkpoint must include actual damage");
        let raw_target = &simulation.entities()[54];
        assert_eq!((raw_target.class, raw_target.model), (5, 13));
        let target_handle = simulation.source_arena().handle(54).expect("live target generation");
        let mut saw_death = false;
        let mut saw_reclaim = false;
        for (index, command) in extra.into_iter().enumerate() {
            session.advance(guard(&session), command).unwrap();
            if (index + 1) % 50 == 0 {
                eprintln!("progression: combat input {} at {:?}", index + 1, started.elapsed());
            }
            let simulation = session.backend().campaign.simulation();
            if simulation.source_arena().resolve(target_handle).is_some() {
                saw_death |= simulation.ordinary().villagers().iter()
                    .any(|row| row.entity_index == 54 && row.life < 0);
            } else if saw_death {
                saw_reclaim = true;
            }
        }
        assert!(saw_death && saw_reclaim, "the recorded target generation must die and be reclaimed");
        eprintln!("progression: combat complete at {:?}", started.elapsed());
        let live = session.backend().semantic_spell_carry().unwrap();
        let simulation = session.backend().campaign.simulation();
        let player = simulation.shared_spells().local_player();
        let kills = simulation.economy().authored_bee_kill_census(player.entity_index);
        let stats = simulation.completion_statistics();
        // The captured target is a Villager (class 5/model 13). Source
        // PreKillEntity excludes models 12..15 from creature kill credit.
        assert_eq!(kills, 0, "the excluded Villager must not award a kill");
        assert!(player.runtime_spell_experience[0] > initial_fire, "ordinary Fireball combat must earn XP");
        let banked = session.backend().transition_spell_carry().unwrap();
        let mut save = Mc2CampaignReplaySave::new(
            false, session.definition().as_ref().clone(),
            session.backend().initial_semantic_spell_carry().unwrap(), Vec::new(),
            session.backend().replay_operations.clone(), &session.backend().snapshot(),
        );
        save.voxel_mode_changes = session.backend().voxel_mode_changes.clone();
        save.receipt_sha256 = save.compute_receipt_sha256();
        let mut restored = GameRuntime::<Mc2CampaignBackend>::title(61902).unwrap();
        let runtime_guard = restored.identity().guard();
        eprintln!("progression: first replay load starting at {:?}", started.elapsed());
        resolver.load_replay(&mut restored, runtime_guard, 61902, &serde_json::to_vec(&save).unwrap()).unwrap();
        eprintln!("progression: first replay load complete at {:?}", started.elapsed());
        let restored_session = restored.session().unwrap();
        assert_eq!(restored_session.backend().semantic_spell_carry().unwrap(), live);
        assert_eq!(restored_session.backend().campaign.simulation().completion_statistics(), stats);
        assert_eq!(restored_session.backend().transition_spell_carry().unwrap(), banked);
        let saved = resolver.save_replay(&restored).unwrap();
        let mut roundtrip = GameRuntime::<Mc2CampaignBackend>::title(61903).unwrap();
        let runtime_guard = roundtrip.identity().guard();
        eprintln!("progression: roundtrip load starting at {:?}", started.elapsed());
        resolver.load_replay(&mut roundtrip, runtime_guard, 61903, &saved).unwrap();
        eprintln!("progression: roundtrip load complete at {:?}", started.elapsed());
        assert_eq!(roundtrip.session().unwrap().backend().semantic_spell_carry().unwrap(), live);

        session.reset(guard(&session)).unwrap();
        eprintln!("progression: source reset complete at {:?}", started.elapsed());
        assert_eq!(session.backend().semantic_spell_carry().unwrap(), initial);
        let reset = session.backend().campaign.simulation();
        let reset_player = reset.shared_spells().local_player();
        assert_eq!(reset.economy().authored_bee_kill_census(reset_player.entity_index), 0);

        // Exercise the real continuation materializer as a controlled entry;
        // no objective or successful campaign frontier is fabricated here.
        let definition = Arc::new(load_mc2_campaign_with_owner_cache(&next_root, &next_cache, &default_catalog().unwrap()).unwrap());
        let mut next = GameSession::open(&Mc2CampaignAdapter, definition, 61904, Mc2CampaignInputs::with_owner_cache(&next_root, &next_cache)).unwrap();
        next.backend_mut().apply_semantic_spell_carry(&banked).unwrap();
        let entry = next.backend().semantic_spell_carry().unwrap();
        for row in &banked.progression {
            let actual = entry.progression.iter().find(|actual| actual.spell == row.spell).unwrap();
            assert_eq!(actual.persistent_experience, row.persistent_experience);
            assert_eq!(actual.runtime_experience, 0);
        }
        next.reset(guard(&next)).unwrap();
        eprintln!("progression: destination reset complete at {:?}", started.elapsed());
        assert_eq!(next.backend().semantic_spell_carry().unwrap(), entry);
        assert_eq!(next.backend().transition_spell_carry().unwrap(), banked);
    }

    #[test]
    fn learned_spell_carry_survives_grounded_release_reclaim_and_next_entry() {
        use crate::FlightWorld;
        use crate::native_world::player_lifecycle_tests::{
            rival_test_sim as sim, rival_test_sim_mut as sim_mut, rival_test_step as step,
        };
        let generated = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../../generated");
        let source = generated.join("settlement-20261105-integration/owner-closed-v6/level1");
        let owner = generated.join("settlement-20261105-integration/owner-closed-v6/environment-complete/cache-level1");
        let definition = Arc::new(load_mc2_campaign_with_owner_cache(&source, &owner, &default_catalog().unwrap()).unwrap());
        let mut game = GameSession::open(&Mc2CampaignAdapter, definition, 7321,
            Mc2CampaignInputs::with_owner_cache(&source, &owner)).unwrap();
        let player = sim(&game).state.entity_index;
        let original = game.backend().semantic_spell_carry().unwrap();
        let held = [0_u8, 1].map(|family| {
            let row = spells::acquired_holder(sim(&game).shared_spells(), family)
                .expect("normal NightSpire starts with both learned held spells");
            assert_ne!(sim(&game).shared_spells().local_player().spell_enabled_flags[usize::from(family)], 0);
            sim(&game).source_arena().handle(row.index).unwrap()
        });
        assert!(original.acquired.contains(&SpellKind::Fireball));
        assert!(original.acquired.contains(&SpellKind::Possession));
        assert!(!original.acquired.contains(&SpellKind::Shield));
        let attacker = sim(&game).creature_runtime_census()
            .roots_of_kind(crate::level_definition::CreatureKind::Goat)
            .next().expect("an actual source Goat supplies the selected contact owner").handle;
        let mut position = sim(&game).state.position;
        position.z = sim(&game).canonical_terrain().ground_height(position)
            .wrapping_add(sim(&game).profile().ground_clearance);
        sim_mut(&mut game).set_level2_entity_position(player, position).unwrap();
        // Declared arrived damage and a ground pose isolate the real human
        // fall/death/release producer. No life, action, holder or timer is set.
        for _ in 0..512 {
            if sim(&game).canonical_player_life_for_test() >= 0 {
                crate::native_world::area_damage::contact(
                    sim_mut(&mut game).source_arena_mut(), None, player,
                    u16::MAX, attacker.source_slot,
                ).unwrap();
            }
            step(&mut game);
            let state = sim(&game);
            if state.entities()[usize::from(player)].action == 3
                && state.shared_spells().local_player().enabled_spell_holders[1] == 1
            { break; }
        }
        assert!(sim(&game).canonical_player_life_for_test() < 0);
        assert_eq!(sim(&game).entities()[usize::from(player)].action, 3);
        for _ in 0..512 {
            if held.iter().all(|handle| sim(&game).source_arena().resolve(*handle).is_none()) { break; }
            step(&mut game);
        }
        assert!(held.iter().all(|handle| sim(&game).source_arena().resolve(*handle).is_none()),
            "the actual released holders expire and reclaim without shortened timers");
        for family in [0_u8, 1] {
            let shared = sim(&game).shared_spells();
            assert_eq!(shared.local_player().enabled_spell_holders[usize::from(family)], 1);
            assert_ne!(shared.local_player().spell_enabled_flags[usize::from(family)], 0);
            assert!(spells::acquired_holder(shared, family).is_none(),
                "learned knowledge must not make a missing physical holder available");
        }
        let before = game.backend().campaign.state_hash();
        let carried = game.backend().transition_spell_carry()
            .expect("source learned ownership survives a released nonzero A4 sentinel");
        assert_eq!(carried.acquired, original.acquired);
        assert_eq!(carried.selected, None, "a missing hand is not physically selected");
        assert!(!carried.acquired.contains(&SpellKind::Shield), "zero/zero/zero remains absent");
        assert_eq!(game.backend().campaign.state_hash(), before, "carry reads do not revive the source actor or its holders");
        let bytes = serde_json::to_vec(&carried).unwrap();
        let saved: Mc2SemanticSpellCarry = serde_json::from_slice(&bytes).unwrap();
        assert_eq!(saved, carried);
        // This is a declared continuation boundary, not a fabricated victory.
        let destination = generated.join("mc-level2-vault-successor-closure-20261025");
        let destination_owner = generated.join("mc-b9s2-cursor-level2-vault-20261029");
        let definition = Arc::new(load_mc2_campaign_with_owner_cache(&destination, &destination_owner, &default_catalog().unwrap()).unwrap());
        let mut next = GameSession::open(&Mc2CampaignAdapter, definition, 7322,
            Mc2CampaignInputs::with_owner_cache(&destination, &destination_owner)).unwrap();
        next.backend_mut().apply_semantic_spell_carry(&saved).unwrap();
        for family in [0_u8, 1] {
            let shared = sim(&next).shared_spells();
            let row = spells::acquired_holder(shared, family).expect("real destination initialisation recreates a current learned holder");
            assert_eq!(row.source_spell_parent_entity_index(), sim(&next).state.entity_index);
            assert!(sim(&next).source_arena().handle(row.index).is_some());
        }
        let entry = next.backend().semantic_spell_carry().unwrap();
        assert_eq!(entry.acquired, carried.acquired);
        next.reset(next.identity().guard()).unwrap();
        assert_eq!(next.backend().semantic_spell_carry().unwrap(), entry);
    }

    #[test]
    fn spell_carry_repair_preserves_progression_through_two_entries_and_save_payload() {
        let generated = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../../generated");
        let open = |path: &str| {
            let root = generated.join(path);
            let definition =
                Arc::new(load_mc2_campaign(&root, &default_catalog().unwrap()).unwrap());
            GameSession::open(
                &Mc2CampaignAdapter,
                definition,
                1,
                Mc2CampaignInputs::new(root),
            )
            .unwrap()
        };
        let mut simulation = open("level2-day-block32-campaign-v2");
        let learned = vec![
            SpellKind::Fireball,
            SpellKind::Shield,
            SpellKind::Invisibility,
            SpellKind::BeyondSight,
            SpellKind::Morph,
            SpellKind::Meteor,
        ];
        // Controlled progression input tests the real carry consumer; no
        // gameplay, pickup, or earned completion claim is made by this setup.
        let carry = Mc2SemanticSpellCarry {
            acquired: learned.clone(),
            selected: Some(SpellKind::BeyondSight),
            progression: vec![
                Mc2SemanticSpellProgress {
                    spell: SpellKind::Shield,
                    persistent_experience: 17,
                    runtime_experience: 450,
                    unlocked_tier: 1,
                    selected_tier: 1,
                },
                Mc2SemanticSpellProgress {
                    spell: SpellKind::BeyondSight,
                    persistent_experience: 20,
                    runtime_experience: 2000,
                    unlocked_tier: 2,
                    selected_tier: 2,
                },
            ],
        };
        simulation
            .backend_mut()
            .apply_semantic_spell_carry(&carry)
            .unwrap();
        let saved =
            serde_json::to_vec(&simulation.backend().initial_semantic_spell_carry().unwrap())
                .unwrap();
        let saved: Mc2SemanticSpellCarry = serde_json::from_slice(&saved).unwrap();
        let mut restored = open("level2-day-block32-campaign-v2");
        restored
            .backend_mut()
            .apply_semantic_spell_carry(&saved)
            .unwrap();
        assert_eq!(
            restored.backend().campaign.state_hash(),
            simulation.backend().campaign.state_hash()
        );
        let mut carry = simulation.backend().transition_spell_carry().unwrap();
        let resolver = Mc2RuntimePackageResolver::load(
            [
                "mc-bhq8-level1-collision-v5-night",
                "level2-day-block32-campaign-v2",
                "level3-day-block32-campaign-recipe-v2",
                "mc-bhq6-ordinary-20261025-zclu5fjj/level4",
            ]
            .map(|path| Mc2CampaignInputs::new(generated.join(path))),
        )
        .unwrap();
        for path in [
            "level3-day-block32-campaign-recipe-v2",
            "mc-bhq6-ordinary-20261025-zclu5fjj/level4",
        ] {
            let mut next = open(path);
            next.backend_mut()
                .apply_semantic_spell_carry(&carry)
                .unwrap();
            let installed = next.backend().semantic_spell_carry().unwrap();
            assert_eq!(installed.acquired.len(), learned.len());
            assert!(
                installed.acquired.iter().all(|kind| learned.contains(kind)),
                "continuation must not grant the destination's direct-entry StartingSpells"
            );
            let shared = next.backend().campaign.simulation().shared_spells();
            let player = shared.local_player();
            for kind in &learned {
                let family = mc2_spell_family(*kind).unwrap();
                assert!(
                    spells::acquired_holder(shared, family).is_some(),
                    "{kind:?}"
                );
                assert_eq!(player.family_selected_tiers[usize::from(family)], 0);
            }
            assert_eq!(player.persistent_spell_experience[6], 467);
            assert_eq!(player.persistent_spell_experience[12], 1080);
            assert_eq!(
                (
                    player.runtime_spell_experience[6],
                    player.runtime_spell_experience[12]
                ),
                (0, 0)
            );
            assert_eq!(
                (
                    player.spell_unlocked_levels[6],
                    player.spell_unlocked_levels[12]
                ),
                (1, 2)
            );
            let save = Mc2CampaignReplaySave::new(
                false,
                next.definition().as_ref().clone(),
                next.backend().initial_semantic_spell_carry().unwrap(),
                Vec::new(),
                Vec::new(),
                &next.backend().snapshot(),
            );
            let bytes = serde_json::to_vec(&save).unwrap();
            let mut runtime = crate::game_runtime::GameRuntime::title(910).unwrap();
            let title = runtime.identity();
            resolver
                .load_replay(&mut runtime, title.guard(), 911, &bytes)
                .unwrap();
            assert_eq!(
                runtime.session().unwrap().backend().snapshot(),
                next.backend().snapshot()
            );
            let saved_again = resolver.save_replay(&runtime).unwrap();
            let mut restored_runtime = crate::game_runtime::GameRuntime::title(912).unwrap();
            let title = restored_runtime.identity();
            resolver
                .load_replay(&mut restored_runtime, title.guard(), 913, &saved_again)
                .unwrap();
            assert_eq!(
                restored_runtime.session().unwrap().backend().snapshot(),
                next.backend().snapshot()
            );
            carry = next.backend().transition_spell_carry().unwrap();
        }
    }

    /// Connect the paid Level 25 producer to the actual campaign resolver.
    /// The first 24 completions and the encounter's group/carry/pose are
    /// configured boundaries, not an earned campaign. The replay below
    /// reuses a clone of the same real result; it is not a second fight.
    pub(crate) fn assert_final_campaign_return_for_test(
        completed: CampaignSession,
        final_package: &std::path::Path,
        final_cache: &std::path::Path,
    ) {
        use crate::game_runtime::{CampaignMenuCommand, CampaignMenuPhase, CampaignSaveState,
            CompletionDisposition, GameRuntime, RuntimeTransitionError};
        use crate::game_runtime::media::MediaCommand;

        let generated = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../../generated");
        let inputs = if std::env::var_os("MC_COMPLETED_RESULTS_SAVE_OUTPUT").is_some() {
            // The retained artifact is for the normal client, whose complete
            // installed graph includes five secret destinations.
            let resources = std::env::var_os("MC_SECRET_RETURN_RESOURCES")
                .map(PathBuf::from).unwrap_or_else(|| generated.join(
                    "campaign-original-environments/installed-campaign-resources.json"));
            let resources: Vec<BTreeMap<String, String>> = serde_json::from_slice(
                &std::fs::read(resources).expect("normal installed campaign resources"),
            ).unwrap();
            assert_eq!(resources.len(), 30);
            assert_eq!(std::fs::canonicalize(&resources[24]["package"]).unwrap(),
                std::fs::canonicalize(final_package).unwrap());
            assert_eq!(std::fs::canonicalize(&resources[24]["owner"]).unwrap(),
                std::fs::canonicalize(final_cache).unwrap());
            resources.iter().map(|row|
                Mc2CampaignInputs::with_owner_cache(&row["package"], &row["owner"]),
            ).collect::<Vec<_>>()
        } else {
            let ordinary = std::env::var_os("MC_ORDINARY_CAMPAIGN_PACKAGES")
                .map(PathBuf::from).unwrap_or_else(|| generated.join("mc-bhq6-ordinary-20261025-zclu5fjj"));
            let mut inputs = (1..25).map(|level| Mc2CampaignInputs::new(ordinary.join(format!("level{level}"))))
                .collect::<Vec<_>>();
            inputs.push(Mc2CampaignInputs::with_owner_cache(final_package, final_cache));
            inputs
        };
        let resolver = Mc2RuntimePackageResolver::load(inputs).unwrap();
        let entries = resolver.flow().entries();
        assert_eq!(entries.len(), 25);
        let final_level = entries[24].level_id().clone();
        let first_level = entries[0].level_id().clone();
        let first = resolver.package(&first_level).unwrap();
        let final_binding = resolver.package(&final_level).unwrap();
        assert_eq!(final_binding.selection.internal_level, 24);
        let initial_frontier = entries[..24].iter().map(|entry| entry.level_id().clone()).collect();
        let save = CampaignSaveState {
            definition: first.definition.as_ref().clone(),
            phase: CampaignMenuPhase::MissionSelect,
            completed_level_id: None,
            selected_level_id: Some(final_level.clone()),
            completed_levels: initial_frontier,
            level_statistics: Vec::new(),
        };
        let mut runtime = GameRuntime::<Mc2CampaignBackend>::title(61926).unwrap();
        install_owner_return_media(&mut runtime);
        let map = runtime.restore_campaign_resolved(runtime.identity().guard(), save, Default::default(),
            |definition, selected| {
                resolver.exact_package_for_definition(definition)?;
                resolver.package(selected).map(|package| Arc::clone(&package.definition))
                    .ok_or_else(|| RuntimeTransitionError::InvalidRuntimeFlow { message: "missing selected package".into() })
            }).unwrap();
        let loading = resolver.campaign_menu_command(&mut runtime, map.guard(), CampaignMenuCommand::StartMission).unwrap();
        let playing = resolver.open_pending(&mut runtime, loading.guard(), 61926).unwrap();
        assert!(runtime.session().unwrap().backend().initial_final_reward,
            "normal map entry installs source final flag 0x20");
        assert!(matches!(resolver.accept_transition(&mut runtime, playing.guard(), playing.session.as_ref().unwrap().guard()),
            Err(RuntimeTransitionError::CompletionNotReady)));
        let expected_stats = completed.simulation().completion_statistics();
        let player = completed.simulation().shared_spells().local_player();
        let runtime_xp = player.runtime_spell_experience;
        let is_cave = completed.simulation().canonical_terrain().map_type() == crate::native_world::MapType::Cave;
        let replay_result = completed.clone();
        runtime.session_mut().unwrap().backend_mut().campaign = completed;
        let playing = runtime.identity();
        let receipt = resolver.accept_transition(&mut runtime, playing.guard(), playing.session.as_ref().unwrap().guard()).unwrap();
        assert_eq!(receipt.disposition, CompletionDisposition::Results);
        assert_eq!(receipt.completion.statistics, Some(expected_stats.clone()));
        assert_eq!(runtime.played_cutscenes() & 0x20, 0x20);
        assert_eq!(runtime.identity().frontend_media.as_ref().unwrap().campaign_return.as_ref().unwrap().cutscene_id, Some(6));
        let pending = resolver.pending_spell_carries.lock().unwrap()[&61926].carry.clone();
        assert_eq!(pending.acquired.len(), 26);
        for family in 0..26 {
            let thresholds = crate::native_world::Level2SharedSpellResetSession::source_spell_tier_thresholds_for_test(family).unwrap();
            let base = thresholds[2].wrapping_add(1);
            let runtime_xp = if family == 2 { runtime_xp[family].min(7) } else { runtime_xp[family] };
            let total = base.wrapping_add(runtime_xp);
            let tier = thresholds.iter().rposition(|threshold| total >= *threshold).unwrap_or(0) as i8;
            let bank = if family == 25 && !is_cave { base } else { total.min(thresholds[2]) };
            let kind = mc2_spell_kind_for_family(family as u8).unwrap();
            let progress = pending.progression.iter().find(|p| p.spell == kind).unwrap();
            assert_eq!((progress.persistent_experience, progress.runtime_experience, progress.unlocked_tier, progress.selected_tier),
                (bank, 0, tier, 0), "source 6E0D0/6D9C0 family {family}");
        }
        play_owner_return_clip(&mut runtime, "cut6", 259, Some("credits"));
        let view = runtime.identity().frontend_media.unwrap().campaign_return.unwrap();
        assert_eq!(view.credits.unwrap().lines, ["Designed By", "Bullfrog Productions Ltd"]);
        for (elapsed_us, input) in [(320_000, false), (0, true), (160_000, true), (0, true), (0, false)] {
            runtime.frontend_media_command(runtime.identity().guard(), MediaCommand::Frame { elapsed_us, input, escape: false }).unwrap();
            if input {
                assert!(runtime.campaign_return_active(), "credits acknowledgment must drain");
            }
        }
        assert!(!runtime.campaign_return_active());
        assert_eq!(runtime.identity().campaign_menu.as_ref().unwrap().phase, CampaignMenuPhase::Results);
        let saved = resolver.save_replay(&runtime).unwrap();
        let mut restored = GameRuntime::<Mc2CampaignBackend>::title(61927).unwrap();
        let restore_guard = restored.identity().guard();
        resolver.load_replay(&mut restored, restore_guard, 61927, &saved).unwrap();
        assert_eq!(restored.played_cutscenes() & 0x20, 0x20);
        let old_stats = restored.completed_level_statistics().to_vec();
        assert_eq!(old_stats.last().unwrap().statistics, expected_stats);
        let results = restored.identity();
        let map = resolver.campaign_menu_command(&mut restored, results.guard(), CampaignMenuCommand::DismissResults).unwrap();
        let map = resolver.campaign_menu_command(&mut restored, map.guard(), CampaignMenuCommand::SelectMission { level_id: final_level }).unwrap();
        let loading = resolver.campaign_menu_command(&mut restored, map.guard(), CampaignMenuCommand::StartMission).unwrap();
        resolver.open_pending(&mut restored, loading.guard(), 61927).unwrap();
        assert_eq!(restored.session().unwrap().backend().campaign.simulation().mission_rewards(), crate::campaign::rewards::MissionRewards::Suppressed);
        let entry_carry = restored.session().unwrap().backend().initial_semantic_spell_carry().unwrap();
        let mut replay_result = replay_result;
        replay_result.simulation_mut().shared_spells_mut().set_mission_rewards(crate::campaign::rewards::MissionRewards::Suppressed);
        restored.session_mut().unwrap().backend_mut().campaign = replay_result;
        let replay = restored.identity();
        let receipt = resolver.accept_transition(&mut restored, replay.guard(), replay.session.as_ref().unwrap().guard()).unwrap();
        assert_eq!(receipt.disposition, CompletionDisposition::ReplayMap);
        assert_eq!(restored.identity().campaign_menu.as_ref().unwrap().phase, CampaignMenuPhase::MissionSelect);
        assert!(!restored.campaign_return_active());
        assert_eq!(restored.played_cutscenes() & 0x20, 0x20);
        assert_eq!(restored.completed_level_statistics(), old_stats);
        assert_eq!(resolver.pending_spell_carries.lock().unwrap()[&61927].carry, entry_carry);
        let map = restored.identity();
        let map = resolver.campaign_menu_command(&mut restored, map.guard(), CampaignMenuCommand::SelectMission { level_id: first_level }).unwrap();
        let loading = resolver.campaign_menu_command(&mut restored, map.guard(), CampaignMenuCommand::StartMission).unwrap();
        resolver.open_pending(&mut restored, loading.guard(), 61927).unwrap();
        let destination = restored.session().unwrap().backend().semantic_spell_carry().unwrap();
        assert_eq!(destination, entry_carry, "replay entry carry reaches the chosen destination");
        write_controlled_campaign_save("MC_COMPLETED_RESULTS_SAVE_OUTPUT", &saved);
    }

    fn write_controlled_campaign_save(variable: &str, bytes: &[u8]) {
        use std::io::Write;
        if let Some(path) = std::env::var_os(variable) {
            let mut file = std::fs::OpenOptions::new().write(true).create_new(true)
                .open(path).expect("new controlled campaign save output");
            file.write_all(bytes).expect("write controlled campaign save");
            file.sync_all().expect("sync controlled campaign save");
        }
    }

    pub(crate) fn install_owner_return_media(runtime: &mut crate::game_runtime::GameRuntime<Mc2CampaignBackend>) {
        use crate::game_runtime::media::MediaCommand;

        let root = std::env::var_os("MC_ENDING_MEDIA_CACHE")
            .map(PathBuf::from)
            .unwrap_or_else(|| PathBuf::from(env!("CARGO_MANIFEST_DIR"))
                .join("../../../generated/mc2-campaign-media-cache-decoded"));
        let catalog = serde_json::from_reader(std::fs::File::open(root.join("media.json")).unwrap())
            .expect("decoded original campaign media catalog");
        runtime.frontend_media_command(runtime.identity().guard(), MediaCommand::Install {
            catalog, startup: false, audio_available: true,
        }).unwrap();
        runtime.frontend_media_command(runtime.identity().guard(), MediaCommand::Frame {
            elapsed_us: 50_000, input: false, escape: false,
        }).unwrap();
    }

    pub(crate) fn play_owner_return_clip(
        runtime: &mut crate::game_runtime::GameRuntime<Mc2CampaignBackend>,
        clip: &str,
        frame_count: i32,
        stop_at: Option<&str>,
    ) {
        use crate::game_runtime::media::MediaCommand;

        let mut last_frame = -1;
        for _ in 0..2400 {
            runtime.frontend_media_command(runtime.identity().guard(), MediaCommand::Frame {
                elapsed_us: 50_000, input: false, escape: false,
            }).unwrap();
            let media = runtime.identity().frontend_media.expect("installed original media owner");
            assert!(media.error.is_none(), "{:?}", media.error);
            if media.active && media.clip_id == clip && media.frame_index > last_frame {
                assert_eq!(media.frame_index, last_frame + 1, "ordered {clip} frames");
                last_frame = media.frame_index;
            }
            let phase = media.campaign_return.as_ref().map(|state| state.phase);
            if phase == stop_at {
                assert_eq!(last_frame + 1, frame_count, "full {clip} ran before {stop_at:?}");
                return;
            }
        }
        panic!("{clip} did not reach {stop_at:?}");
    }

