    #[test]
    fn actual_v7_secret_parent_volcano_hint_preference_replays_at_source_boundary() {
        use crate::game_runtime::{CampaignMenuCommand, GameRuntime, RuntimeMode};
        use crate::game_session::{SpellAssignment, SpellAssignmentHand};
        use crate::campaign::journal::CampaignEffect;

        let generated = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../../generated");
        let resources = std::env::var_os("MC_SECRET_RETURN_RESOURCES").map(PathBuf::from)
            .unwrap_or_else(|| generated.join("campaign-original-environments/installed-campaign-resources.json"));
        let resources: Vec<BTreeMap<String, String>> = serde_json::from_slice(&fs::read(resources).unwrap()).unwrap();
        let resolver = Mc2RuntimePackageResolver::load(resources.iter().map(|row|
            Mc2CampaignInputs::with_owner_cache(&row["package"], &row["owner"]))).unwrap();
        let path = std::env::var_os("MC_HELP_V7_SAVE").map(PathBuf::from).unwrap_or_else(||
            generated.join("continuity-20261115/installed-parent-hud-5/parent-entry-save.mcs"));
        let old_bytes = fs::read(path).expect("actual retained v7 secret-parent save");
        let old: Mc2CampaignReplaySave = serde_json::from_slice(&old_bytes).unwrap();
        assert_eq!(old.save_contract, PRE_HELP_MC2_CAMPAIGN_REPLAY_SAVE_CONTRACT);
        assert!(old.help_preference_changes.is_empty() && old.verify());
        assert_eq!(old.expected_tick, 21);
        let map_path = generated.join("continuity-20261115/controlled-secret-map.mcs");
        let map_bytes = fs::read(map_path).expect("actual retained completed-secret map save");
        let open_parent = |id| {
            let mut runtime = GameRuntime::<Mc2CampaignBackend>::title(id).unwrap();
            let title = runtime.identity();
            let map = resolver.load_replay(&mut runtime, title.guard(), id, &map_bytes).unwrap();
            let loading = resolver.campaign_menu_command(
                &mut runtime, map.guard(), CampaignMenuCommand::StartMission,
            ).unwrap();
            let playing = resolver.open_pending(&mut runtime, loading.guard(), id).unwrap();
            assert_eq!(playing.mode, RuntimeMode::Playing);
            assert_eq!(runtime.session().unwrap().backend().campaign.definition().identity,
                CampaignSelection::ordinary(20).unwrap());
            runtime
        };
        let live = open_parent(8838);
        let live_identity = live.identity();
        let live_before = resolver.save_replay(&live).unwrap();
        let mut invalid_v7 = old.clone();
        invalid_v7.help_preference_changes.push(Mc2HelpPreferenceChange { before_operation: 0, enabled: true });
        invalid_v7.receipt_sha256 = invalid_v7.compute_receipt_sha256();
        let mut rejected = GameRuntime::<Mc2CampaignBackend>::title(8839).unwrap();
        let before = rejected.identity();
        assert!(resolver.load_replay(&mut rejected, before.guard(), 8839,
            &serde_json::to_vec(&invalid_v7).unwrap()).is_err());
        assert_eq!(rejected.identity(), before);
        let error = resolver.load_replay(&mut rejected, before.guard(), 8839, &old_bytes)
            .expect_err("the authentic late-level v7 packet must reject its old clock receipt");
        assert!(error.to_string().contains("replayed campaign state does not match the saved receipts"),
            "the old packet must reach receipt verification: {error}");
        assert_eq!(rejected.identity(), before);
        assert_eq!(live.identity(), live_identity);
        assert_eq!(resolver.save_replay(&live).unwrap(), live_before);

        for enabled in [false, true] {
            let id = if enabled { 8842 } else { 8841 };
            let mut runtime = open_parent(id);
            runtime.session_mut().unwrap().backend_mut().hydrate_fresh_help_preference(enabled);
            let session = runtime.session_mut().unwrap();
            let features = session.backend().campaign.simulation().mission().authored_features();
            assert_eq!((features[25].kind, features[25].subtype, features[25].activation_group), (11, 31, 8));
            assert!(features.iter().filter(|row| row.kind == 11 && row.subtype == 31)
                .all(|row| row.activation_group != 0));
            for _ in 0..10 {
                assert!(session.backend().campaign.simulation().economy().authored_switch_producers()
                    .iter().all(|row| !row.active || row.model != 31),
                    "no secret-announcement switch is present during source20 opening admission");
                session.step(guard(session), GameCommand::default()).unwrap();
            }
            let assignment_cursor = session.backend().campaign.effect_cursor();
            session.step(guard(session), GameCommand {
                assign_spell: Some(SpellAssignment {
                    spell_id: SemanticId::parse("spell.volcano").unwrap(),
                    tier: 0, hand: SpellAssignmentHand::Left, holder_actor: None,
                }), ..GameCommand::default()
            }).unwrap();
            let assignment = session.backend().campaign.effects_after(assignment_cursor, usize::MAX).unwrap();
            let close = assignment.records.iter().position(|record| matches!(record.effect,
                CampaignEffect::Flight(FlightEvent::CloseHelpPopup)));
            let assignment_sound = assignment.records.iter().position(|record| matches!(record.effect,
                CampaignEffect::Flight(FlightEvent::PrepareSound { sound_id: 14, .. })));
            assert_eq!(close.is_some(), enabled);
            assert!(assignment_sound.is_some());
            if let Some(close) = close { assert!(assignment_sound.unwrap() < close); }
            let hud = session.backend().campaign.simulation().day_hud_for(
                CampaignSelection::ordinary(20).unwrap()).unwrap();
            assert_eq!(hud.left.model, 18);
            assert!(hud.left.caster_mana < hud.left.max_mana && hud.left.help_unavailable);
            let cursor = session.backend().campaign.effect_cursor();
            session.step(guard(session), GameCommand { cast_left: true, ..GameCommand::default() }).unwrap();
            let page = session.backend().campaign.effects_after(cursor, usize::MAX).unwrap();
            let hint = page.records.iter().position(|record| matches!(record.effect,
                CampaignEffect::Flight(FlightEvent::ShowHelpHint { hint_index: 41, state: 6 })));
            let sound = page.records.iter().position(|record| matches!(record.effect,
                CampaignEffect::Flight(FlightEvent::PrepareSound { sound_id: 29, .. })));
            assert_eq!(hint.is_some(), enabled);
            assert!(sound.is_some());
            if let Some(hint) = hint { assert!(hint < sound.unwrap()); }
            let backend = session.backend_mut();
            backend.set_help_enabled(!enabled);
            backend.set_help_enabled(enabled);
            let expected = backend.snapshot();
            let saved = resolver.save_replay(&runtime).unwrap();
            let packet: Mc2CampaignReplaySave = serde_json::from_slice(&saved).unwrap();
            assert_eq!(packet.save_contract, MC2_CAMPAIGN_REPLAY_SAVE_CONTRACT);
            let mut invalid = packet.clone();
            invalid.help_preference_changes.last_mut().unwrap().before_operation = invalid.operations.len() + 1;
            invalid.receipt_sha256 = invalid.compute_receipt_sha256();
            let before = rejected.identity();
            assert!(resolver.load_replay(&mut rejected, before.guard(), 8839,
                &serde_json::to_vec(&invalid).unwrap()).is_err());
            assert_eq!(rejected.identity(), before);
            assert_eq!(live.identity(), live_identity);
            assert_eq!(resolver.save_replay(&live).unwrap(), live_before);
            let mut cold = GameRuntime::<Mc2CampaignBackend>::title(id + 10).unwrap();
            let title = cold.identity();
            resolver.load_replay(&mut cold, title.guard(), id + 10, &saved).unwrap();
            assert_eq!(cold.session().unwrap().backend().snapshot(), expected);
            assert_eq!(cold.session().unwrap().backend().help_enabled(), enabled);
            assert_eq!(resolver.save_replay(&cold).unwrap(), saved);
        }
    }

    #[test]
    fn source_top_status_admission_replays_current_frames_after_verified_v9_prefix() {
        use crate::game_runtime::GameRuntime;
        let resolver = Mc2RuntimePackageResolver::load([
            Mc2CampaignInputs::new(level_one_descriptor_fixture_path()),
            Mc2CampaignInputs::new(descriptor_fixture_path()),
            Mc2CampaignInputs::new(level_three_descriptor_fixture_path()),
        ]).unwrap();
        let mut runtime = GameRuntime::<Mc2CampaignBackend>::title(8917).unwrap();
        let title = runtime.identity();
        let loading = resolver.new_game(&mut runtime, title.guard()).unwrap();
        resolver.open_pending(&mut runtime, loading.guard(), 8917).unwrap();
        runtime.advance_player_with_preferences(runtime.session().unwrap().identity().guard(), GameCommand::default()).unwrap();
        let identity = runtime.identity();
        let nested = runtime.session().unwrap().identity().guard();
        let saved = resolver.save_replay(&runtime).unwrap();
        let packet: Mc2CampaignReplaySave = serde_json::from_slice(&saved).unwrap();
        assert_eq!(packet.hud_admission_changes, vec![Mc2HudAdmissionChange { before_operation: 0, top_bar: true }]);
        for _ in 0..3 {
            let backend = runtime.session().unwrap().backend();
            assert_eq!(backend.snapshot().source_top_status, backend.render_observation().source_top_status);
        }
        assert_eq!(resolver.save_replay(&runtime).unwrap(), saved);
        assert_eq!(runtime.identity(), identity);
        let mut stale = nested;
        stale.generation += 1;
        assert!(runtime.advance_player_with_preferences(stale, GameCommand::default()).is_err());
        assert_eq!(resolver.save_replay(&runtime).unwrap(), saved,
            "rejected input cannot prepare or publish a HUD policy boundary");
        runtime.toggle_icons_and_map(identity.guard(), nested).unwrap();
        runtime.advance_player_with_preferences(nested, GameCommand::default()).unwrap();
        let paused = runtime.pause(runtime.identity().guard()).unwrap();
        let nested = runtime.session().unwrap().identity().guard();
        runtime.paused_frame(paused.guard(), nested).unwrap();
        let saved = resolver.save_replay(&runtime).unwrap();
        let packet: Mc2CampaignReplaySave = serde_json::from_slice(&saved).unwrap();
        assert_eq!(packet.hud_admission_changes.iter().map(|row| row.top_bar).collect::<Vec<_>>(), [true, false]);
        let mut cold = GameRuntime::<Mc2CampaignBackend>::title(8918).unwrap();
        let title = cold.identity();
        resolver.load_replay(&mut cold, title.guard(), 8918, &saved).unwrap();
        assert_eq!(cold.session().unwrap().backend().snapshot(), runtime.session().unwrap().backend().snapshot());
        assert_eq!(resolver.save_replay(&cold).unwrap(), saved);
        for invalid in [
            Mc2HudAdmissionChange { before_operation: packet.operations.len(), top_bar: true },
            Mc2HudAdmissionChange { before_operation: 0, top_bar: false },
        ] {
            let mut bad = packet.clone();
            bad.hud_admission_changes.push(invalid);
            bad.receipt_sha256 = bad.compute_receipt_sha256();
            let before = cold.identity();
            assert!(resolver.load_replay(&mut cold, before.guard(), 8918, &serde_json::to_vec(&bad).unwrap()).is_err());
            assert_eq!(cold.identity(), before);
            assert_eq!(resolver.save_replay(&cold).unwrap(), saved);
        }

        // Authentic released875c writer: unchanged actual fresh-Pav v8 input,
        // one real paused frame, then a v9 save. No retagged fixture/history.
        let generated = std::env::var_os("MC_CAPI_FIXTURE_PRIVATE_ROOT").map_or_else(
            || PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../.."), PathBuf::from,
        ).join("generated");
        let resources = std::env::var_os("MC_SECRET_RETURN_RESOURCES").map(PathBuf::from)
            .unwrap_or_else(|| generated.join("campaign-original-environments/installed-campaign-resources.json"));
        let resources: Vec<BTreeMap<String, String>> = serde_json::from_slice(&fs::read(resources).unwrap()).unwrap();
        let full = Mc2RuntimePackageResolver::load(resources.iter().map(|row|
            Mc2CampaignInputs::with_owner_cache(&row["package"], &row["owner"]))).unwrap();
        let path = std::env::var_os("MC_TOP_STATUS_V9_SAVE").map(PathBuf::from)
            .unwrap_or_else(|| generated.join("top-status-20261116/released-v9-after-paused-frame.mcs"));
        let old_bytes = fs::read(path).expect("genuine released v9 receipt");
        let old: Mc2CampaignReplaySave = serde_json::from_slice(&old_bytes).unwrap();
        assert_eq!(old.save_contract, MC2_CAMPAIGN_REPLAY_SAVE_CONTRACT);
        assert!(old.hud_admission_changes.is_empty() && old.verify());
        let mut migrated = GameRuntime::<Mc2CampaignBackend>::title(8919).unwrap();
        let title = migrated.identity();
        full.load_replay(&mut migrated, title.guard(), 8919, &old_bytes).unwrap();
        let initial = migrated.session().unwrap().backend().snapshot();
        let unchanged = full.save_replay(&migrated).unwrap();
        let verified: Mc2CampaignReplaySave = serde_json::from_slice(&unchanged).unwrap();
        assert_eq!(verified.expected_state_hash, old.expected_state_hash);
        assert_eq!(verified.expected_tick, old.expected_tick);
        assert_eq!(verified.expected_terrain_hash, old.expected_terrain_hash);
        assert_eq!(verified.expected_effect_head, old.expected_effect_head);
        assert_eq!(verified.expected_effect_journal_sha256, old.expected_effect_journal_sha256);
        assert!(verified.hud_admission_changes.is_empty());
        let outer = migrated.identity();
        let nested = migrated.session().unwrap().identity().guard();
        migrated.paused_frame(outer.guard(), nested).unwrap();
        let updated = full.save_replay(&migrated).unwrap();
        let packet: Mc2CampaignReplaySave = serde_json::from_slice(&updated).unwrap();
        assert_eq!(packet.hud_admission_changes,
            vec![Mc2HudAdmissionChange { before_operation: old.operations.len(), top_bar: outer.display_settings.top_bar }]);
        assert_eq!(migrated.session().unwrap().backend().snapshot().tick, initial.tick);
        let mut replay = GameRuntime::<Mc2CampaignBackend>::title(8920).unwrap();
        let title = replay.identity();
        full.load_replay(&mut replay, title.guard(), 8920, &updated).unwrap();
        assert_eq!(replay.session().unwrap().backend().snapshot(), migrated.session().unwrap().backend().snapshot());
        assert_eq!(full.save_replay(&replay).unwrap(), updated,
            "old prefix stays historical; only the recorded accepted boundary uses source HUD admission");
    }

    #[test]
    fn runtime_hand_selection_flash_follows_source_passes_and_replays_global_lifetime() {
        use crate::game_runtime::{CampaignMenuCommand, GameRuntime};
        use crate::game_session::{SpellAssignment, SpellAssignmentHand, SpellMark, SpellMarkHand};
        fn assignment(hand: SpellAssignmentHand) -> GameCommand {
            GameCommand { assign_spell: Some(SpellAssignment {
                spell_id: SemanticId::parse("spell.fireball").unwrap(), tier: 0,
                hand, holder_actor: None,
            }), ..Default::default() }
        }
        fn step(runtime: &mut GameRuntime<Mc2CampaignBackend>, command: GameCommand) {
            let session = runtime.session_mut().unwrap();
            session.step(guard(session), command).unwrap();
        }
        fn ticks(runtime: &GameRuntime<Mc2CampaignBackend>) -> [u8; 2] {
            let backend = runtime.session().unwrap().backend();
            let full = backend.snapshot();
            let render = backend.render_observation();
            assert_eq!(full.player_hand_selection_flash_ticks, render.player_hand_selection_flash_ticks);
            assert_eq!(serde_json::to_value(render).unwrap()["player_hand_selection_flash_ticks"],
                serde_json::json!(full.player_hand_selection_flash_ticks));
            full.player_hand_selection_flash_ticks
        }
        let resolver = Mc2RuntimePackageResolver::load([
            Mc2CampaignInputs::new(level_one_descriptor_fixture_path()),
            Mc2CampaignInputs::new(descriptor_fixture_path()),
            Mc2CampaignInputs::new(level_three_descriptor_fixture_path()),
        ]).unwrap();
        let mut runtime = GameRuntime::<Mc2CampaignBackend>::title(8897).unwrap();
        let title = runtime.identity();
        let loading = resolver.new_game(&mut runtime, title.guard()).unwrap();
        resolver.open_pending(&mut runtime, loading.guard(), 8897).unwrap();
        assert_eq!(ticks(&runtime), [0, 0]);
        assert!(runtime.session().unwrap().backend().snapshot().player_spells.iter()
            .any(|row| row.id.as_str() == "spell.fireball" && row.acquired));
        step(&mut runtime, assignment(SpellAssignmentHand::Left));
        assert_eq!(ticks(&runtime), [8, 0], "assignment follows this pass's decrement");
        step(&mut runtime, GameCommand::default());
        assert_eq!(ticks(&runtime), [7, 0]);
        step(&mut runtime, assignment(SpellAssignmentHand::Left));
        assert_eq!(ticks(&runtime), [8, 0], "accepted same-value assignment retriggers");
        step(&mut runtime, assignment(SpellAssignmentHand::Right));
        assert_eq!(ticks(&runtime), [7, 8]);
        step(&mut runtime, GameCommand { select_spell: Some(SemanticId::parse("spell.fireball").unwrap()), ..Default::default() });
        assert_eq!(ticks(&runtime), [6, 7], "selection preview does not assign a hand");
        step(&mut runtime, GameCommand { mark_spell: Some(SpellMark {
            spell_id: SemanticId::parse("spell.fireball").unwrap(), hand: SpellMarkHand::Left, holder_actor: None,
        }), ..Default::default() });
        assert_eq!(ticks(&runtime), [5, 6], "mark sound14 does not retrigger");
        let before = resolver.save_replay(&runtime).unwrap();
        let session = runtime.session_mut().unwrap();
        let mut invalid = assignment(SpellAssignmentHand::Left);
        invalid.assign_spell.as_mut().unwrap().spell_id = SemanticId::parse("spell.volcano").unwrap();
        assert!(session.step(guard(session), invalid).is_err());
        assert_eq!(resolver.save_replay(&runtime).unwrap(), before, "rejected assignment is atomic");
        for _ in 0..3 { assert_eq!(ticks(&runtime), [5, 6]); }
        assert_eq!(resolver.save_replay(&runtime).unwrap(), before, "queries do not clock source globals");
        let mut cold = GameRuntime::<Mc2CampaignBackend>::title(8898).unwrap();
        let title = cold.identity();
        resolver.load_replay(&mut cold, title.guard(), 8898, &before).unwrap();
        assert_eq!(ticks(&cold), [5, 6]);
        assert_eq!(resolver.save_replay(&cold).unwrap(), before);
        let paused = cold.pause(cold.identity().guard()).unwrap();
        let nested = cold.session().unwrap().identity().guard();
        for pass in 1u8..=8 {
            cold.paused_frame(paused.guard(), nested).unwrap();
            assert_eq!(ticks(&cold), [5u8.saturating_sub(pass), 6u8.saturating_sub(pass)]);
            assert_eq!(cold.identity(), paused, "paused PlayerEvents does not advance flight tick");
        }
        cold.resume(cold.identity().guard()).unwrap();
        step(&mut cold, assignment(SpellAssignmentHand::Left));
        for remaining in (0..8).rev() {
            step(&mut cold, GameCommand::default());
            assert_eq!(ticks(&cold), [remaining, 0]);
        }
        step(&mut cold, assignment(SpellAssignmentHand::Right));
        let session = cold.session_mut().unwrap();
        session.reset(session.identity().guard()).unwrap();
        assert_eq!(ticks(&cold), [0, 8], "retry retains source process globals");
        let reset_bytes = resolver.save_replay(&cold).unwrap();
        let mut reset_cold = GameRuntime::<Mc2CampaignBackend>::title(8899).unwrap();
        let title = reset_cold.identity();
        resolver.load_replay(&mut reset_cold, title.guard(), 8899, &reset_bytes).unwrap();
        assert_eq!(ticks(&reset_cold), [0, 8]);
        assert_eq!(resolver.save_replay(&reset_cold).unwrap(), reset_bytes);
        let outer = cold.identity().guard();
        let nested = cold.session().unwrap().identity().guard();
        resolver.close_to_title(&mut cold, outer, nested).unwrap();
        let map_bytes = resolver.save_replay(&cold).unwrap();
        let receiver = cold.identity();
        let shared = resolver.source_process_context(&cold).unwrap();
        let mut bad: Mc2CampaignReplaySave = serde_json::from_slice(&before).unwrap();
        bad.expected_state_hash ^= 1;
        bad.receipt_sha256 = bad.compute_receipt_sha256();
        assert!(resolver.load_replay_with_source_context(&mut cold, receiver.guard(), 8898,
            &serde_json::to_vec(&bad).unwrap(), shared).is_err());
        assert_eq!(cold.identity(), receiver);
        assert_eq!(resolver.save_replay(&cold).unwrap(), map_bytes,
            "failed saved receipt cannot replace warm receiver globals");
        resolver.load_replay_with_source_context(&mut cold, receiver.guard(), 8898, &before, shared).unwrap();
        assert_eq!(ticks(&cold), [0, 8], "warm SLEV retains receiver pair after verifying saved[5,6]");
        let warm_bytes = resolver.save_replay(&cold).unwrap();
        let warm: Mc2CampaignReplaySave = serde_json::from_slice(&warm_bytes).unwrap();
        assert_eq!(warm.global_context_changes.last().unwrap().hand_selection_flash_ticks, Some([0, 8]));
        let mut warm_cold = GameRuntime::<Mc2CampaignBackend>::title(8901).unwrap();
        let title = warm_cold.identity();
        resolver.load_replay(&mut warm_cold, title.guard(), 8901, &warm_bytes).unwrap();
        assert_eq!(ticks(&warm_cold), [0, 8]);
        assert_eq!(resolver.save_replay(&warm_cold).unwrap(), warm_bytes,
            "the accepted warm change is replayed at its actual operation boundary");
        let mut map_cold = GameRuntime::<Mc2CampaignBackend>::title(8900).unwrap();
        let title = map_cold.identity();
        let map = resolver.load_replay(&mut map_cold, title.guard(), 8900, &map_bytes).unwrap();
        assert_eq!(resolver.save_replay(&map_cold).unwrap(), map_bytes);
        let loading = resolver.campaign_menu_command(&mut map_cold, map.guard(), CampaignMenuCommand::StartMission).unwrap();
        resolver.open_pending(&mut map_cold, loading.guard(), 8900).unwrap();
        assert_eq!(ticks(&map_cold), [0, 8], "new mission owner retains process globals");
        step(&mut map_cold, GameCommand::default());
        assert_eq!(ticks(&map_cold), [0, 7]);

        // Explicit historical-engine control, not a captured old save: run
        // real assignments with the published v8 producer policy, then encode
        // its unchanged receipt. Migration cannot reinterpret those commands.
        let mut historical = GameRuntime::<Mc2CampaignBackend>::title(8902).unwrap();
        let title = historical.identity();
        let loading = resolver.new_game(&mut historical, title.guard()).unwrap();
        resolver.open_pending(&mut historical, loading.guard(), 8902).unwrap();
        historical.session_mut().unwrap().backend_mut().campaign.simulation_mut()
            .set_historical_hand_selection_flash(true);
        historical.session_mut().unwrap().backend_mut().hud_admission = None;
        step(&mut historical, assignment(SpellAssignmentHand::Left));
        step(&mut historical, GameCommand::default());
        assert_eq!(ticks(&historical), [0, 0]);
        let mut old: Mc2CampaignReplaySave = serde_json::from_slice(&resolver.save_replay(&historical).unwrap()).unwrap();
        old.save_contract = PRE_HAND_FLASH_MC2_CAMPAIGN_REPLAY_SAVE_CONTRACT.to_owned();
        old.receipt_sha256 = old.compute_receipt_sha256();
        assert!(old.verify());
        let old_bytes = serde_json::to_vec(&old).unwrap();
        let mut injected = old.clone();
        injected.global_context_changes.push(Mc2GlobalContextChange {
            before_operation: injected.operations.len(), context: GlobalSpecialState::default(),
            hand_selection_flash_ticks: Some([8, 0]),
            source_speed_index: None,
            speed_action: None,
        });
        injected.receipt_sha256 = injected.compute_receipt_sha256();
        assert!(!injected.verify(), "a rehashed v8 envelope cannot invent a new hand-flash history");
        let mut migrated = GameRuntime::<Mc2CampaignBackend>::title(8903).unwrap();
        let title = migrated.identity();
        resolver.load_replay(&mut migrated, title.guard(), 8903, &old_bytes).unwrap();
        assert_eq!(migrated.session().unwrap().backend().snapshot(), historical.session().unwrap().backend().snapshot());
        let migrated_bytes = resolver.save_replay(&migrated).unwrap();
        let packet: Mc2CampaignReplaySave = serde_json::from_slice(&migrated_bytes).unwrap();
        assert_eq!(packet.save_contract, MC2_CAMPAIGN_REPLAY_SAVE_CONTRACT);
        assert_eq!(packet.operations, old.operations);
        assert_eq!(packet.expected_state_hash, old.expected_state_hash);
        assert_eq!(packet.hand_selection_flash_start_operation, Some(old.operations.len()));
        step(&mut migrated, assignment(SpellAssignmentHand::Left));
        assert_eq!(ticks(&migrated), [8, 0], "only new accepted input activates new source behavior");
        let current = resolver.save_replay(&migrated).unwrap();
        let mut replay = GameRuntime::<Mc2CampaignBackend>::title(8904).unwrap();
        let title = replay.identity();
        resolver.load_replay(&mut replay, title.guard(), 8904, &current).unwrap();
        assert_eq!(ticks(&replay), [8, 0]);
        assert_eq!(resolver.save_replay(&replay).unwrap(), current);
        let mut bad: Mc2CampaignReplaySave = serde_json::from_slice(&current).unwrap();
        bad.hand_selection_flash_start_operation = Some(bad.operations.len() + 1);
        bad.receipt_sha256 = bad.compute_receipt_sha256();
        let mut refused = GameRuntime::<Mc2CampaignBackend>::title(8905).unwrap();
        let title = refused.identity();
        assert!(resolver.load_replay(&mut refused, title.guard(), 8905, &serde_json::to_vec(&bad).unwrap()).is_err());
        assert_eq!(refused.identity(), title);

        // Authentic pre-feature v8 input, retained byte-for-byte from the
        // real controlled Jaleen constructor/return path (not earned gameplay).
        let generated = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../../generated");
        let resources = std::env::var_os("MC_SECRET_RETURN_RESOURCES").map(PathBuf::from)
            .unwrap_or_else(|| generated.join("campaign-original-environments/installed-campaign-resources.json"));
        let resources: Vec<BTreeMap<String, String>> = serde_json::from_slice(&fs::read(resources).unwrap()).unwrap();
        let full_resolver = Mc2RuntimePackageResolver::load(resources.iter().map(|row|
            Mc2CampaignInputs::with_owner_cache(&row["package"], &row["owner"]))).unwrap();
        let path = std::env::var_os("MC_HAND_FLASH_V8_SAVE").map(PathBuf::from)
            .unwrap_or_else(|| generated.join("secret-announcement-20261115/fresh-pav-3.mcs"));
        let actual_bytes = fs::read(&path).unwrap();
        let actual: Mc2CampaignReplaySave = serde_json::from_slice(&actual_bytes).unwrap();
        assert_eq!(actual.save_contract, PRE_HAND_FLASH_MC2_CAMPAIGN_REPLAY_SAVE_CONTRACT);
        assert!(actual.verify());
        let mut actual_cold = GameRuntime::<Mc2CampaignBackend>::title(8906).unwrap();
        let title = actual_cold.identity();
        full_resolver.load_replay(&mut actual_cold, title.guard(), 8906, &actual_bytes).unwrap();
        let snapshot = actual_cold.session().unwrap().backend().snapshot();
        assert_eq!((snapshot.tick, snapshot.state_hash, snapshot.terrain_hash, snapshot.effect_head,
            &snapshot.effect_journal_sha256), (actual.expected_tick, actual.expected_state_hash,
            actual.expected_terrain_hash, actual.expected_effect_head, &actual.expected_effect_journal_sha256));
        assert_eq!(ticks(&actual_cold), [0, 0]);
        assert_eq!(fs::read(path).unwrap(), actual_bytes, "historical input is never rewritten");
    }

    #[test]
    fn source_graphics_game_authority_notices_and_lifetime_roundtrip() {
        use crate::game_runtime::{GameRuntime,SourceGraphicsAction,DisplaySettings,RuntimeGuard,preferences::PreferencesCommand};
        let resolver=Mc2RuntimePackageResolver::load([
            Mc2CampaignInputs::new(level_one_descriptor_fixture_path()),Mc2CampaignInputs::new(descriptor_fixture_path()),
            Mc2CampaignInputs::new(level_three_descriptor_fixture_path())]).unwrap();
        let profile=std::env::temp_dir().join(format!("mc-game-graphics-{}-{}",std::process::id(),
            SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos()));
        let mut runtime=GameRuntime::<Mc2CampaignBackend>::title(8980).unwrap();
        runtime.preferences_command(runtime.identity().guard(),PreferencesCommand::Install {
            profile_dir:profile.to_string_lossy().into_owned()}).unwrap();
        let mut preferences=runtime.identity().player_preferences.preferences;preferences.player_name="OLIVER".into();
        runtime.preferences_command(runtime.identity().guard(),PreferencesCommand::Apply {preferences}).unwrap();
        let bytes=fs::read(profile.join("player-preferences.json")).unwrap();
        let title=runtime.identity();let invalid=sim_session::SessionGuard {session_id:8980,generation:0,expected_tick:0};
        assert!(runtime.source_graphics(title.guard(),invalid,SourceGraphicsAction::Sky).is_err());assert_eq!(runtime.identity(),title);
        let loading=resolver.new_game(&mut runtime,title.guard()).unwrap();
        resolver.open_pending(&mut runtime,loading.guard(),8980).unwrap();
        let before=runtime.identity();let nested=runtime.session().unwrap().identity().guard();let original=resolver.save_replay(&runtime).unwrap();
        for (outer,inner) in [(RuntimeGuard {generation:before.generation+1,..before.guard()},nested),
            (before.guard(),sim_session::SessionGuard {generation:nested.generation+1,..nested}),
            (before.guard(),sim_session::SessionGuard {expected_tick:nested.expected_tick+1,..nested})] {
            assert!(runtime.source_graphics(outer,inner,SourceGraphicsAction::Reflections).is_err());
            assert_eq!(runtime.identity(),before);assert_eq!(resolver.save_replay(&runtime).unwrap(),original);
        }
        assert!(runtime.preferences_command(before.guard(),PreferencesCommand::Apply {
            preferences:before.player_preferences.preferences.clone()}).is_err());
        for (action,name) in [(SourceGraphicsAction::Reflections,"participant.reflections_off"),
            (SourceGraphicsAction::Shadows,"participant.shadows_off"),(SourceGraphicsAction::Sky,"participant.sky_off"),
            (SourceGraphicsAction::DynamicLighting,"participant.dynamic_lighting_off")] {
            assert!(runtime.source_graphics(before.guard(),nested,action).unwrap());
            assert_eq!(runtime.identity().session,before.session);
            assert_eq!(runtime.identity().player_preferences,before.player_preferences);
            assert_eq!(fs::read(profile.join("player-preferences.json")).unwrap(),bytes);
            let notices=runtime.session().unwrap().backend().participant_notifications();
            assert_eq!(notices.len(),1);assert_eq!((notices[0].kind.as_str(),notices[0].remaining_frames),(name,50));
        }
        let off=DisplaySettings {reflections:false,shadows:false,sky:false,dynamic_lighting:false,..before.display_settings};
        assert_eq!(runtime.identity().display_settings,off);assert!(!runtime.session().unwrap().backend().dynamic_lighting_enabled());
        let saved=resolver.save_replay(&runtime).unwrap();let packet:Mc2CampaignReplaySave=serde_json::from_slice(&saved).unwrap();
        assert!(packet.initial_display_settings.dynamic_lighting.is_none());
        assert_eq!(packet.initial_display_settings.reflections,Some(false));
        let mut cold=GameRuntime::<Mc2CampaignBackend>::title(8981).unwrap();let title=cold.identity();
        resolver.load_replay(&mut cold,title.guard(),8981,&saved).unwrap();
        assert_eq!(cold.identity().display_settings,off);assert_eq!(resolver.save_replay(&cold).unwrap(),saved);
        let mut duplicate=packet.clone();duplicate.initial_display_settings.dynamic_lighting=Some(false);
        duplicate.receipt_sha256=duplicate.compute_receipt_sha256();
        let mut rejected=GameRuntime::<Mc2CampaignBackend>::title(8982).unwrap();let title=rejected.identity();
        assert!(resolver.load_replay(&mut rejected,title.guard(),8982,&serde_json::to_vec(&duplicate).unwrap()).is_err());assert_eq!(rejected.identity(),title);
        let paused=runtime.pause(before.guard()).unwrap();let nested=runtime.session().unwrap().identity().guard();
        runtime.paused_campaign_frame_timed(paused.guard(),nested,0,false).unwrap();
        assert_eq!(runtime.identity().display_settings,off);assert!(!runtime.session().unwrap().backend().dynamic_lighting_enabled());
        runtime.resume(paused.guard()).unwrap();let session=runtime.session_mut().unwrap();session.reset(session.identity().guard()).unwrap();
        assert_eq!(runtime.identity().display_settings,off);assert!(!runtime.session().unwrap().backend().dynamic_lighting_enabled());
        let nested=runtime.session().unwrap().identity().guard();
        runtime.close(runtime.identity().guard(),nested).unwrap();let title=runtime.identity();
        assert_eq!(title.display_settings,off,"same-process Title retains all four GAME flags");
        let loading=resolver.new_game(&mut runtime,title.guard()).unwrap();resolver.open_pending(&mut runtime,loading.guard(),8980).unwrap();
        assert_eq!(runtime.identity().display_settings,off);assert!(!runtime.session().unwrap().backend().dynamic_lighting_enabled());
        let current=runtime.identity();let nested=runtime.session().unwrap().identity().guard();
        resolver.close_to_title(&mut runtime,current.guard(),nested).unwrap();
        let map=resolver.save_replay(&runtime).unwrap();let json:serde_json::Value=serde_json::from_slice(&map).unwrap();
        assert_eq!(json["display_settings"]["dynamic_lighting"],false);
        let mut map_cold=GameRuntime::<Mc2CampaignBackend>::title(8983).unwrap();let title=map_cold.identity();
        resolver.load_replay(&mut map_cold,title.guard(),8983,&map).unwrap();assert_eq!(map_cold.identity().display_settings,off);
        assert_eq!(resolver.save_replay(&map_cold).unwrap(),map);
        let title=map_cold.identity();let loading=resolver.campaign_menu_command(&mut map_cold,title.guard(),crate::game_runtime::CampaignMenuCommand::StartMission).unwrap();
        resolver.open_pending(&mut map_cold,loading.guard(),8983).unwrap();assert_eq!(map_cold.identity().display_settings,off);
        assert!(!map_cold.session().unwrap().backend().dynamic_lighting_enabled());
        assert_eq!(GameRuntime::<Mc2CampaignBackend>::title(8984).unwrap().identity().display_settings,DisplaySettings::default());
        if let Some(path)=std::env::var_os("MC_GRAPHICS_OLD_ACTIVE_SAVE") {
            let old_bytes=fs::read(&path).unwrap();let old:Mc2CampaignReplaySave=serde_json::from_slice(&old_bytes).unwrap();
            assert_eq!(old.save_contract,MC2_CAMPAIGN_REPLAY_SAVE_CONTRACT);assert!(old.verify());
            assert!(old.initial_display_settings.dynamic_lighting.is_none());
            // The immutable released writer bootstrapped the first three
            // installed resources WITH their authoritative owner caches.
            // Generic no-owner fixtures are a different animation/hash role.
            #[derive(Deserialize)]
            struct RecordedResource {package_dir:PathBuf,owner_cache_path:Option<PathBuf>}
            let resource_path=std::env::var_os("MC_CAMPAIGN_SAVE_RESOURCES")
                .expect("old writer proof requires its installed resource catalog");
            let rows:Vec<RecordedResource>=serde_json::from_slice(&fs::read(resource_path).unwrap()).unwrap();
            assert!(rows.len()>=3);
            assert_eq!(old.definition.runtime_flow().unwrap().entries().len(),3);
            let old_resolver=Mc2RuntimePackageResolver::load(rows.iter().take(3).map(|row|
                row.owner_cache_path.as_ref().map_or_else(||Mc2CampaignInputs::new(&row.package_dir),
                    |owner|Mc2CampaignInputs::with_owner_cache(&row.package_dir,owner)))).unwrap();
            let mut receiver=GameRuntime::<Mc2CampaignBackend>::title(8985).unwrap();let title=receiver.identity();
            old_resolver.load_replay(&mut receiver,title.guard(),8985,&old_bytes).unwrap();
            assert!(!receiver.identity().display_settings.dynamic_lighting);assert!(!receiver.session().unwrap().backend().dynamic_lighting_enabled());
            assert!(receiver.identity().display_settings.reflections&&receiver.identity().display_settings.shadows&&receiver.identity().display_settings.sky);
            assert_eq!(old_resolver.save_replay(&receiver).unwrap(),old_bytes,"verified old false policy adds no redundant header");
            assert_eq!(fs::read(path).unwrap(),old_bytes);
        }
        fs::remove_dir_all(profile).unwrap();
    }

    #[test]
    fn source_graphics_light_toggle_gates_real_fireball_admission_without_retirement() {
        use crate::game_runtime::{GameRuntime,SourceGraphicsAction};
        let night=std::env::var_os("MC_FLIGHT_ASSISTANCE_PACKAGE").map(PathBuf::from).unwrap_or_else(||
            PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../../generated/mc-bhq8-level1-collision-v5-night"));
        let resolver=Mc2RuntimePackageResolver::load([Mc2CampaignInputs::new(&night),Mc2CampaignInputs::new(descriptor_fixture_path()),
            Mc2CampaignInputs::new(level_three_descriptor_fixture_path())]).unwrap();
        for enabled in [false,true] {
            let mut runtime=GameRuntime::<Mc2CampaignBackend>::title(8986+u64::from(enabled)).unwrap();let title=runtime.identity();
            let loading=resolver.new_game(&mut runtime,title.guard()).unwrap();resolver.open_pending(&mut runtime,loading.guard(),8986+u64::from(enabled)).unwrap();
            let outer=runtime.identity().guard();let nested=runtime.session().unwrap().identity().guard();
            runtime.source_graphics(outer,nested,SourceGraphicsAction::DynamicLighting).unwrap();
            if enabled {runtime.source_graphics(outer,nested,SourceGraphicsAction::DynamicLighting).unwrap();}
            runtime.advance_player_with_preferences(nested,GameCommand {cast_left:true,..GameCommand::default()}).unwrap();
            let session=runtime.session().unwrap();assert!(player_spell_projectile_count(session)>0);
            let count=session.backend().campaign.simulation().source_arena().dynamic_lighting.active_count();
            assert_eq!(count>0,enabled,"actual ordinary Fireball constructor obeys accepted source GAME policy");
            if enabled {
                let nested=session.identity().guard();let projectile_count=player_spell_projectile_count(session);
                runtime.source_graphics(outer,nested,SourceGraphicsAction::DynamicLighting).unwrap();
                assert_eq!(runtime.session().unwrap().backend().campaign.simulation().source_arena().dynamic_lighting.active_count(),count);
                assert_eq!(player_spell_projectile_count(runtime.session().unwrap()),projectile_count);
            }
        }
    }

    #[test]
    fn source_help_mode_commits_policy_notice_and_immediate_cold_replay() {
        use crate::game_runtime::{GameRuntime,RuntimeGuard,preferences::PreferencesCommand};
        let resolver=Mc2RuntimePackageResolver::load([
            Mc2CampaignInputs::new(level_one_descriptor_fixture_path()),
            Mc2CampaignInputs::new(descriptor_fixture_path()),
            Mc2CampaignInputs::new(level_three_descriptor_fixture_path()),
        ]).unwrap();
        let profile=std::env::temp_dir().join(format!("mc-help-mode-runtime-{}-{}",std::process::id(),
            std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));
        let install=||PreferencesCommand::Install { profile_dir:profile.to_string_lossy().into_owned() };
        let mut runtime=GameRuntime::<Mc2CampaignBackend>::title(8970).unwrap();
        runtime.preferences_command(runtime.identity().guard(),install()).unwrap();
        let title=runtime.identity();
        let invalid=sim_session::SessionGuard {session_id:8970,generation:0,expected_tick:0};
        assert!(runtime.source_help_mode_preferences(title.guard(),invalid).is_err());
        assert_eq!(runtime.identity(),title);
        let loading=resolver.new_game(&mut runtime,title.guard()).unwrap();
        assert!(runtime.source_help_mode_preferences(loading.guard(),invalid).is_err());
        assert_eq!(runtime.identity(),loading);
        resolver.open_pending(&mut runtime,loading.guard(),8970).unwrap();
        let before=runtime.identity(); let nested=runtime.session().unwrap().identity().guard();
        let saved_before=resolver.save_replay(&runtime).unwrap();
        for (outer,inner) in [(RuntimeGuard {generation:before.generation+1,..before.guard()},nested),
            (before.guard(),sim_session::SessionGuard {generation:nested.generation+1,..nested}),
            (before.guard(),sim_session::SessionGuard {expected_tick:nested.expected_tick+1,..nested})] {
            assert!(runtime.source_help_mode_preferences(outer,inner).is_err());
            assert_eq!(runtime.identity(),before);
            assert_eq!(resolver.save_replay(&runtime).unwrap(),saved_before);
            assert!(!profile.join("player-preferences.json").exists());
        }
        assert!(runtime.preferences_command(before.guard(),PreferencesCommand::Apply {
            preferences:before.player_preferences.preferences.clone() }).is_err());
        let snapshot_before=runtime.session().unwrap().backend().snapshot();
        let (reset_before,conformance_before)={
            let simulation=runtime.session().unwrap().backend().campaign.simulation();
            let core=&simulation.session.state.live.core;
            (ResetReceipt::from_state(&ResetState::from_simulation(simulation)).digest(),
                crate::conformance_hash_v2(&core.state,&core.context))
        };
        assert!(runtime.session().unwrap().backend().help_enabled());
        let accepted=runtime.source_help_mode_preferences(before.guard(),nested).unwrap();
        assert_eq!(accepted.source_help_mode_admitted,Some(true));
        assert!(!accepted.preferences.show_help);
        let after=runtime.identity();
        let mut expected_preferences=before.player_preferences.preferences.clone(); expected_preferences.show_help=false;
        assert_eq!(after.player_preferences.preferences,expected_preferences);
        assert_eq!(after.session,before.session); assert_eq!(after.display_settings,before.display_settings);
        let backend=runtime.session().unwrap().backend(); assert!(!backend.help_enabled());
        let snapshot=backend.snapshot();
        assert_eq!(snapshot.state_hash,snapshot_before.state_hash,
            "the public campaign hash excludes the source HELP policy and notice domains");
        let simulation=backend.campaign.simulation(); let core=&simulation.session.state.live.core;
        assert_ne!(ResetReceipt::from_state(&ResetState::from_simulation(simulation)).digest(),reset_before,
            "the full native receipt includes actual help policy and local notice");
        assert_ne!(crate::conformance_hash_v2(&core.state,&core.context),conformance_before,
            "HELP changes the flight-context conformance hash independently of the separate notice owner");
        let notice=backend.participant_notifications();
        assert_eq!(notice.len(),1);
        assert_eq!((notice[0].kind.as_str(),notice[0].remaining_frames),("participant.help_mode_off",50));
        let mut expected_snapshot=snapshot_before;
        expected_snapshot.participant_notifications=notice.clone();
        assert_eq!(snapshot,expected_snapshot,"only the independently checked local notice changes the public observation");
        let disabled=resolver.save_replay(&runtime).unwrap();
        let packet:Mc2CampaignReplaySave=serde_json::from_slice(&disabled).unwrap();
        assert!(matches!(packet.operations.last(),Some(crate::game_runtime::ReplayOperation::HelpModeNotice {enabled:false})));
        assert_eq!(packet.help_preference_changes.last().unwrap().before_operation,packet.operations.len()-1);
        assert!(!packet.help_preference_changes.last().unwrap().enabled);
        let mut cold=GameRuntime::<Mc2CampaignBackend>::title(8971).unwrap();
        cold.preferences_command(cold.identity().guard(),install()).unwrap(); let title=cold.identity();
        resolver.load_replay(&mut cold,title.guard(),8971,&disabled).unwrap();
        assert!(!cold.identity().player_preferences.preferences.show_help);
        assert!(!cold.session().unwrap().backend().help_enabled());
        assert_eq!(cold.session().unwrap().backend().snapshot(),snapshot);
        assert_eq!(resolver.save_replay(&cold).unwrap(),disabled);
        let bytes=fs::read(profile.join("player-preferences.json")).unwrap();
        let path=profile.join("player-preferences.json"); let retained=profile.join("retained.json");
        fs::rename(&path,&retained).unwrap(); fs::create_dir(&path).unwrap();
        assert!(runtime.source_help_mode_preferences(after.guard(),nested).is_err());
        assert_eq!(runtime.identity(),after); assert_eq!(resolver.save_replay(&runtime).unwrap(),disabled);
        assert_eq!(fs::read(&retained).unwrap(),bytes);
        fs::remove_dir(&path).unwrap(); fs::rename(&retained,&path).unwrap();
        let paused=runtime.pause(after.guard()).unwrap(); let nested=runtime.session().unwrap().identity().guard();
        runtime.preferences_command(paused.guard(),PreferencesCommand::PreviewAudio {
            sound_enabled:false,music_enabled:false,speech_enabled:false,sound_volume:0,music_volume:0 }).unwrap();
        let preview=runtime.identity(); let preview_save=resolver.save_replay(&runtime).unwrap();
        assert_eq!(runtime.source_help_mode_preferences(paused.guard(),nested).unwrap().source_help_mode_admitted,Some(false));
        assert_eq!(runtime.identity(),preview); assert_eq!(resolver.save_replay(&runtime).unwrap(),preview_save);
        assert_eq!(fs::read(&path).unwrap(),bytes);
        runtime.preferences_command(paused.guard(),PreferencesCommand::Cancel).unwrap();
        let enabled=runtime.source_help_mode_preferences(paused.guard(),nested).unwrap();
        assert!(enabled.preferences.show_help); assert!(runtime.session().unwrap().backend().help_enabled());
        assert_eq!(runtime.session().unwrap().backend().participant_notifications()[0].kind.as_str(),"participant.help_mode_on");
        let enabled_save=resolver.save_replay(&runtime).unwrap();
        let mut enabled_cold=GameRuntime::<Mc2CampaignBackend>::title(8972).unwrap();
        enabled_cold.preferences_command(enabled_cold.identity().guard(),install()).unwrap(); let title=enabled_cold.identity();
        resolver.load_replay(&mut enabled_cold,title.guard(),8972,&enabled_save).unwrap();
        assert!(enabled_cold.session().unwrap().backend().help_enabled());
        assert_eq!(resolver.save_replay(&enabled_cold).unwrap(),enabled_save);
        runtime.presentation_frame(paused.guard(),nested,false).unwrap();
        assert_eq!(runtime.session().unwrap().backend().participant_notifications()[0].remaining_frames,50);
        for remaining in (0..50).rev() {
            runtime.presentation_frame(paused.guard(),nested,true).unwrap();
            assert_eq!(runtime.session().unwrap().backend().participant_notifications()[0].remaining_frames,remaining);
        }
        runtime.presentation_frame(paused.guard(),nested,true).unwrap();
        assert!(runtime.session().unwrap().backend().participant_notifications().is_empty());
        runtime.resume(paused.guard()).unwrap(); let session=runtime.session_mut().unwrap();
        session.reset(session.identity().guard()).unwrap();
        assert!(runtime.identity().player_preferences.preferences.show_help);
        assert!(runtime.session().unwrap().backend().help_enabled());
        assert!(runtime.session().unwrap().backend().participant_notifications().is_empty());
        fs::remove_dir_all(profile).unwrap();
    }

    #[test]
    fn source_flight_assistance_commits_notice_profile_and_exact_replay() {
        use crate::game_runtime::{GameRuntime, RuntimeGuard, RuntimeMode,
            preferences::{PreferenceStore, PreferencesCommand}};
        let resolver = Mc2RuntimePackageResolver::load([
            Mc2CampaignInputs::new(level_one_descriptor_fixture_path()),
            Mc2CampaignInputs::new(descriptor_fixture_path()),
            Mc2CampaignInputs::new(level_three_descriptor_fixture_path()),
        ]).unwrap();
        let profile = std::env::temp_dir().join(format!("mc-flight-assist-runtime-{}-{}", std::process::id(),
            std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));
        let install = || PreferencesCommand::Install { profile_dir: profile.to_string_lossy().into_owned() };
        let mut runtime = GameRuntime::<Mc2CampaignBackend>::title(8960).unwrap();
        runtime.preferences_command(runtime.identity().guard(), install()).unwrap();
        let title = runtime.identity();
        let invalid = sim_session::SessionGuard { session_id:8960,generation:0,expected_tick:0 };
        assert!(runtime.source_flight_assistance_preferences(title.guard(), invalid).is_err());
        assert_eq!(runtime.identity(), title);
        let loading = resolver.new_game(&mut runtime, title.guard()).unwrap();
        assert!(runtime.source_flight_assistance_preferences(loading.guard(), invalid).is_err());
        assert_eq!(runtime.identity(), loading);
        resolver.open_pending(&mut runtime, loading.guard(), 8960).unwrap();
        let before = runtime.identity();
        let nested = runtime.session().unwrap().identity().guard();
        let original_save = resolver.save_replay(&runtime).unwrap();
        for (outer, inner) in [
            (RuntimeGuard { generation:before.generation+1,..before.guard() }, nested),
            (before.guard(),sim_session::SessionGuard {generation:nested.generation+1,..nested}),
            (before.guard(),sim_session::SessionGuard {expected_tick:nested.expected_tick+1,..nested}),
        ] {
            assert!(runtime.source_flight_assistance_preferences(outer, inner).is_err());
            assert_eq!(runtime.identity(), before);
            assert_eq!(resolver.save_replay(&runtime).unwrap(), original_save);
            assert!(!profile.join("player-preferences.json").exists());
        }
        assert!(runtime.preferences_command(before.guard(), PreferencesCommand::Apply {
            preferences: before.player_preferences.preferences.clone(),
        }).is_err(), "generic Playing preference edits remain refused");
        let before_snapshot = runtime.session().unwrap().backend().snapshot();
        let before_reset = ResetReceipt::from_state(&ResetState::from_simulation(
            runtime.session().unwrap().backend().campaign.simulation()));
        let accepted = runtime.source_flight_assistance_preferences(before.guard(), nested).unwrap();
        assert_eq!(accepted.source_flight_assistance_admitted, Some(true));
        assert!(accepted.preferences.flight_assistance);
        let after = runtime.identity();
        assert_eq!(after.session, before.session);
        assert_eq!(after.display_settings, before.display_settings);
        assert_ne!(ResetReceipt::from_state(&ResetState::from_simulation(
            runtime.session().unwrap().backend().campaign.simulation())).digest(), before_reset.digest());
        let notice = runtime.session().unwrap().backend().participant_notifications();
        assert_eq!(notice.len(), 1);
        assert_eq!((notice[0].kind.as_str(),notice[0].remaining_frames),
            ("participant.flight_assistance_on",50));
        let mut expected_snapshot = before_snapshot;
        expected_snapshot.participant_notifications = notice.clone();
        assert_eq!(runtime.session().unwrap().backend().snapshot(), expected_snapshot,
            "the only full observation change is the independently checked local notice");
        assert!(runtime.session().unwrap().backend().campaign.simulation().session.state.live
            .player_lifecycle_notifications.entries().iter().any(|entry| entry.state == 3
                && entry.kind == Some(crate::native_world::creatures::player_lifecycle::notifications::PlayerLifeNoticeKind::FlightAssistanceOn)));
        let saved = resolver.save_replay(&runtime).unwrap();
        let packet: Mc2CampaignReplaySave = serde_json::from_slice(&saved).unwrap();
        assert!(matches!(packet.operations.last(), Some(crate::game_runtime::ReplayOperation::FlightAssistanceNotice { enabled:true })));
        let mut cold = GameRuntime::<Mc2CampaignBackend>::title(8961).unwrap();
        cold.preferences_command(cold.identity().guard(), install()).unwrap();
        assert!(cold.identity().player_preferences.preferences.flight_assistance);
        let title = cold.identity();
        resolver.load_replay(&mut cold, title.guard(), 8961, &saved).unwrap();
        assert_eq!(cold.session().unwrap().backend().participant_notifications(), notice);
        assert_eq!(resolver.save_replay(&cold).unwrap(), saved, "immediate save replays the same notice at the same boundary");
        let profile_bytes = fs::read(profile.join("player-preferences.json")).unwrap();
        let profile_path = profile.join("player-preferences.json");
        let retained_path = profile.join("retained-preferences.json");
        fs::rename(&profile_path, &retained_path).unwrap();
        fs::create_dir(&profile_path).unwrap();
        assert!(runtime.source_flight_assistance_preferences(after.guard(), nested).is_err(),
            "an actual profile publication failure cannot commit the prepared notice");
        assert_eq!(runtime.identity(), after);
        assert_eq!(runtime.session().unwrap().backend().participant_notifications(), notice);
        assert_eq!(resolver.save_replay(&runtime).unwrap(), saved);
        assert_eq!(fs::read(&retained_path).unwrap(), profile_bytes);
        fs::remove_dir(&profile_path).unwrap();
        fs::rename(&retained_path, &profile_path).unwrap();
        for _ in 0..3 {
            assert_eq!(runtime.identity(), after);
            assert_eq!(resolver.save_replay(&runtime).unwrap(), saved);
        }
        let paused = runtime.pause(after.guard()).unwrap();
        let nested = runtime.session().unwrap().identity().guard();
        runtime.preferences_command(paused.guard(), PreferencesCommand::PreviewAudio {
            sound_enabled:false,music_enabled:false,speech_enabled:false,sound_volume:0,music_volume:0,
        }).unwrap();
        let preview = runtime.identity();
        let preview_save = resolver.save_replay(&runtime).unwrap();
        assert_eq!(runtime.source_flight_assistance_preferences(paused.guard(), nested).unwrap()
            .source_flight_assistance_admitted, Some(false));
        assert_eq!(runtime.identity(), preview);
        assert_eq!(resolver.save_replay(&runtime).unwrap(), preview_save);
        assert_eq!(fs::read(profile.join("player-preferences.json")).unwrap(), profile_bytes);
        runtime.preferences_command(paused.guard(), PreferencesCommand::Cancel).unwrap();
        let disabled = runtime.source_flight_assistance_preferences(paused.guard(), nested).unwrap();
        assert!(!disabled.preferences.flight_assistance);
        assert_eq!(runtime.identity().mode, RuntimeMode::Paused);
        assert_eq!(runtime.session().unwrap().backend().participant_notifications()[0].kind.as_str(),
            "participant.flight_assistance_off");
        runtime.presentation_frame(paused.guard(), nested, false).unwrap();
        assert_eq!(runtime.session().unwrap().backend().participant_notifications()[0].remaining_frames, 50);
        for remaining in (0..50).rev() {
            runtime.presentation_frame(paused.guard(), nested, true).unwrap();
            assert_eq!(runtime.session().unwrap().backend().participant_notifications()[0].remaining_frames, remaining);
        }
        runtime.presentation_frame(paused.guard(), nested, true).unwrap();
        assert!(runtime.session().unwrap().backend().participant_notifications().is_empty());
        let expired = resolver.save_replay(&runtime).unwrap();
        let mut replay = GameRuntime::<Mc2CampaignBackend>::title(8962).unwrap();
        replay.preferences_command(replay.identity().guard(), install()).unwrap();
        assert!(!replay.identity().player_preferences.preferences.flight_assistance);
        let title = replay.identity();
        resolver.load_replay(&mut replay, title.guard(), 8962, &expired).unwrap();
        assert_eq!(resolver.save_replay(&replay).unwrap(), expired);
        let mut profile_cold = PreferenceStore::default();
        assert!(!profile_cold.command(install()).unwrap().preferences.flight_assistance);
        runtime.resume(paused.guard()).unwrap();
        let session = runtime.session_mut().unwrap();
        session.reset(session.identity().guard()).unwrap();
        assert!(!runtime.identity().player_preferences.preferences.flight_assistance);
        assert!(runtime.session().unwrap().backend().participant_notifications().is_empty());
        let outer = runtime.identity().guard();
        let nested = runtime.session().unwrap().identity().guard();
        runtime.source_flight_assistance_preferences(outer,nested).unwrap();
        let precise = sim_session::SteeringObservation::try_from([0.45_f32.to_bits(),0]).unwrap();
        for index in 0..100 {
            let guard = runtime.session().unwrap().identity().guard();
            runtime.advance_player_with_preferences(guard,GameCommand {
                steering_observation:Some(if index%2==0 { sim_session::SteeringObservation::default() } else { precise }),
                ..GameCommand::default()
            }).unwrap();
            assert_eq!(runtime.identity().player_preferences.assistance_sequence,0,
                "real sub-axis activity never qualifies as49 unchanged source samples");
        }
        for index in 0..49 {
            let guard = runtime.session().unwrap().identity().guard();
            runtime.advance_player_with_preferences(guard,GameCommand {
                steering_observation:Some(precise), ..GameCommand::default()
            }).unwrap();
            assert_eq!(runtime.identity().player_preferences.assistance_sequence,if index==48 {1} else {0});
        }
        let observed = runtime.session().unwrap().backend();
        let commands: Vec<_> = observed.replay_operations.iter().filter_map(|operation| match operation {
            crate::game_runtime::ReplayOperation::Step { command } => Some(command), _ => None,
        }).collect();
        assert_eq!(commands.len(),149);
        assert!(commands.iter().all(|command|command.steering_observation.is_none()));
        assert!(commands[..148].iter().all(|command|!command.recenter));
        assert!(commands[148].recenter,"only the actual49th stationary sample becomes recorded recenter");
        let derived = resolver.save_replay(&runtime).unwrap();
        assert!(!String::from_utf8(derived.clone()).unwrap().contains("steering_observation"));
        let mut derived_cold = GameRuntime::<Mc2CampaignBackend>::title(8963).unwrap();
        derived_cold.preferences_command(derived_cold.identity().guard(),install()).unwrap();
        let title = derived_cold.identity();
        resolver.load_replay(&mut derived_cold,title.guard(),8963,&derived).unwrap();
        assert_eq!(derived_cold.session().unwrap().backend().snapshot(),observed.snapshot());
        assert_eq!(resolver.save_replay(&derived_cold).unwrap(),derived);
        assert_eq!(derived_cold.identity().player_preferences.assistance_sequence,0);
        fs::remove_dir_all(profile).unwrap();
    }

    #[test]
    fn player_names_notice_replays_but_visibility_keeps_source_process_lifetime() {
        use crate::game_runtime::{CampaignMenuCommand, GameRuntime, RuntimeGuard, RuntimeMode};
        let resolver = Mc2RuntimePackageResolver::load([
            Mc2CampaignInputs::new(level_one_descriptor_fixture_path()),
            Mc2CampaignInputs::new(descriptor_fixture_path()),
            Mc2CampaignInputs::new(level_three_descriptor_fixture_path()),
        ]).unwrap();
        let mut runtime = GameRuntime::<Mc2CampaignBackend>::title(8950).unwrap();
        let title = runtime.identity();
        assert!(title.source_player_names_visible);
        let invalid = sim_session::SessionGuard { session_id: 8950, generation: 0, expected_tick: 0 };
        assert!(runtime.toggle_player_names(title.guard(), invalid).is_err());
        assert_eq!(runtime.identity(), title);
        let loading = resolver.new_game(&mut runtime, title.guard()).unwrap();
        assert!(runtime.toggle_player_names(loading.guard(), invalid).is_err());
        assert_eq!(runtime.identity(), loading);
        resolver.open_pending(&mut runtime, loading.guard(), 8950).unwrap();
        let guard = runtime.session().unwrap().identity().guard();
        runtime.advance_player_with_preferences(guard, GameCommand::default()).unwrap();
        let before = runtime.identity();
        let flight = runtime.session().unwrap().backend().campaign.simulation().state;
        let snapshot = runtime.session().unwrap().backend().snapshot();
        let source_context = runtime.session().unwrap().backend().campaign.source_global_context();
        let nested = runtime.session().unwrap().identity().guard();
        let read_bytes = resolver.save_replay(&runtime).unwrap();
        let sim = runtime.session().unwrap().backend().campaign.simulation();
        let label = sim.campaign_player_label(flight.entity_index).unwrap().unwrap();
        assert_eq!(label.player_color_index, flight.player_color_index);
        assert_eq!(&label.name_bytes[..usize::from(label.name_len)], b"PLAYER");
        assert_eq!(label.life, sim.session.state.live.player_life);
        assert_eq!(label.max_life, sim.entities()[usize::from(flight.entity_index)].max_life);
        let rows = sim.campaign_entity_presentations(flight.yaw).unwrap();
        let before_notice_receipt = ResetReceipt::from_state(&ResetState::from_simulation(sim));
        for _ in 0..3 {
            assert_eq!(sim.campaign_player_label(flight.entity_index).unwrap(), Some(label));
            assert_eq!(sim.campaign_entity_presentations(flight.yaw).unwrap(), rows);
        }
        assert_eq!(resolver.save_replay(&runtime).unwrap(), read_bytes, "name/actor queries never clock or mutate");
        for (outer, inner) in [
            (RuntimeGuard { generation: before.generation + 1, ..before.guard() }, nested),
            (before.guard(), sim_session::SessionGuard { generation: nested.generation + 1, ..nested }),
            (before.guard(), sim_session::SessionGuard { expected_tick: nested.expected_tick + 1, ..nested }),
        ] {
            assert!(runtime.toggle_player_names(outer, inner).is_err());
            assert_eq!(runtime.identity(), before);
            assert_eq!(resolver.save_replay(&runtime).unwrap(), read_bytes);
        }
        assert!(runtime.toggle_player_names(before.guard(), nested).unwrap());
        assert!(!runtime.identity().source_player_names_visible);
        assert_eq!(runtime.identity().session, before.session);
        assert_eq!(runtime.identity().display_settings, before.display_settings);
        assert_eq!(runtime.identity().player_preferences, before.player_preferences);
        let backend = runtime.session().unwrap().backend();
        assert_eq!(backend.campaign.simulation().state, flight);
        assert_eq!(backend.campaign.source_global_context(), source_context);
        let after = backend.snapshot();
        assert_eq!((after.tick, after.terrain_hash, after.effect_head, &after.effect_journal_sha256),
            (snapshot.tick, snapshot.terrain_hash, snapshot.effect_head, &snapshot.effect_journal_sha256));
        assert_eq!(after.state_hash, snapshot.state_hash,
            "the historical public campaign hash excludes the presentation notice domain");
        let after_notice_receipt = ResetReceipt::from_state(
            &ResetState::from_simulation(backend.campaign.simulation()));
        assert_ne!(after_notice_receipt.digest(), before_notice_receipt.digest(),
            "the canonical reset receipt hashes the actual source notice payload and lifetime");
        let notice = backend.participant_notifications();
        assert_eq!(notice.len(), 1);
        assert_eq!(notice[0].kind.as_str(), "participant.player_names_off");
        assert_eq!(notice[0].remaining_frames, 50);
        let paused = runtime.pause(runtime.identity().guard()).unwrap();
        let saved = resolver.save_replay(&runtime).unwrap();
        assert!(!String::from_utf8(saved.clone()).unwrap().contains("source_player_names_visible"),
            "auxiliary byte207 is never a saved GAME/header value");
        let mut cold = GameRuntime::<Mc2CampaignBackend>::title(8951).unwrap();
        let title = cold.identity();
        resolver.load_replay(&mut cold, title.guard(), 8951, &saved).unwrap();
        assert_eq!(cold.identity().mode, RuntimeMode::Paused);
        assert!(cold.identity().source_player_names_visible, "cold defaults visible after verifying the notice history");
        assert_eq!(cold.session().unwrap().backend().participant_notifications(), notice);
        assert_eq!(resolver.save_replay(&cold).unwrap(), saved);
        let receiver = resolver.source_process_context(&runtime).unwrap();
        assert!(!receiver.source_player_names_visible);
        let mut warm = GameRuntime::<Mc2CampaignBackend>::title(8952).unwrap();
        let title = warm.identity();
        let mut bad: Mc2CampaignReplaySave = serde_json::from_slice(&saved).unwrap();
        bad.expected_state_hash ^= 1;
        bad.receipt_sha256 = bad.compute_receipt_sha256();
        assert!(resolver.load_replay_with_source_context(&mut warm, title.guard(), 8952,
            &serde_json::to_vec(&bad).unwrap(), receiver).is_err());
        assert_eq!(warm.identity(), title, "a failed receipt never installs receiver visibility");
        resolver.load_replay_with_source_context(&mut warm, title.guard(), 8952, &saved, receiver).unwrap();
        assert!(!warm.identity().source_player_names_visible);
        assert_eq!(resolver.save_replay(&warm).unwrap(), saved);
        let nested = runtime.session().unwrap().identity().guard();
        runtime.toggle_player_names(paused.guard(), nested).unwrap();
        assert!(runtime.identity().source_player_names_visible);
        assert_eq!(runtime.session().unwrap().backend().participant_notifications()[0].kind.as_str(), "participant.player_names_on");
        runtime.toggle_player_names(paused.guard(), nested).unwrap();
        assert!(!runtime.identity().source_player_names_visible);
        let hidden = resolver.save_replay(&runtime).unwrap();
        runtime.presentation_frame(paused.guard(), nested, false).unwrap();
        assert_eq!(runtime.session().unwrap().backend().participant_notifications()[0].remaining_frames, 50);
        for remaining in (0..50).rev() {
            runtime.presentation_frame(paused.guard(), nested, true).unwrap();
            assert_eq!(runtime.session().unwrap().backend().participant_notifications()[0].remaining_frames, remaining);
        }
        runtime.presentation_frame(paused.guard(), nested, true).unwrap();
        assert!(runtime.session().unwrap().backend().participant_notifications().is_empty());
        assert!(!runtime.identity().source_player_names_visible, "notice expiry never changes the process setting");
        assert_eq!(runtime.session().unwrap().backend().campaign.simulation().state, flight);
        assert_ne!(resolver.save_replay(&runtime).unwrap(), hidden, "only real presentation operations clock the notice");
        let id = warm.identity(); warm.resume(id.guard()).unwrap();
        let session = warm.session_mut().unwrap(); session.reset(session.identity().guard()).unwrap();
        warm.reset_panel_transparency_to_level_default();
        assert!(!warm.identity().source_player_names_visible, "retry retains byte207");
        let reset = resolver.save_replay(&warm).unwrap();
        let mut reset_cold = GameRuntime::<Mc2CampaignBackend>::title(8953).unwrap();
        let title = reset_cold.identity();
        resolver.load_replay(&mut reset_cold, title.guard(), 8953, &reset).unwrap();
        assert!(reset_cold.identity().source_player_names_visible);
        let id = warm.identity(); let nested = warm.session().unwrap().identity().guard();
        resolver.close_to_title(&mut warm, id.guard(), nested).unwrap();
        let map = warm.identity();
        let receiver = resolver.source_process_context(&warm).unwrap();
        assert!(!receiver.source_player_names_visible, "detached campaign context uses the actual process flag");
        let map_bytes = resolver.save_replay(&warm).unwrap();
        assert!(warm.toggle_player_names(map.guard(), invalid).is_err());
        assert_eq!(warm.identity(), map);
        assert_eq!(resolver.save_replay(&warm).unwrap(), map_bytes);
        let mut map_warm = GameRuntime::<Mc2CampaignBackend>::title(8954).unwrap();
        let title = map_warm.identity();
        resolver.load_replay_with_source_context(&mut map_warm, title.guard(), 8954, &map_bytes, receiver).unwrap();
        assert!(!map_warm.identity().source_player_names_visible);
        let mut map_cold = GameRuntime::<Mc2CampaignBackend>::title(8955).unwrap();
        let title = map_cold.identity();
        resolver.load_replay(&mut map_cold, title.guard(), 8955, &map_bytes).unwrap();
        assert!(map_cold.identity().source_player_names_visible);
        assert_eq!(resolver.save_replay(&map_cold).unwrap(), map_bytes);
        let id = map_warm.identity();
        let loading = resolver.campaign_menu_command(&mut map_warm, id.guard(), CampaignMenuCommand::StartMission).unwrap();
        resolver.open_pending(&mut map_warm, loading.guard(), 8954).unwrap();
        assert!(!map_warm.identity().source_player_names_visible, "ordinary mission entry retains byte207");
        if let Some(output) = std::env::var_os("MC_PLAYER_NAMES_NYPHUR_REPLAY_OUTPUT") {
            export_public_nyphur_label_replay_for_test(PathBuf::from(output));
        }
    }

    fn export_public_nyphur_label_replay_for_test(output: PathBuf) {
        use crate::game_runtime::{CampaignMenuCommand, CampaignMenuPhase, CampaignSaveState, GameRuntime};
        use crate::goat_sprite_raster::{Mode20SpriteCamera, Mode20SpriteDefinition, Mode20SpriteEntity,
            project_fixed_sprite_with_depth_adjustment};
        use crate::day_indexed_frame::{DayIndexedFrameAssets, DayIndexedFrameState};
        use std::io::Write;
        let generated = std::env::var_os("MC_CAPI_FIXTURE_PRIVATE_ROOT").map_or_else(
            || PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../.."), PathBuf::from,
        ).join("generated");
        let resource_path = std::env::var_os("MC_SECRET_RETURN_RESOURCES").map(PathBuf::from)
            .unwrap_or_else(|| generated.join("continuity-20261115/installed-full-resources.json"));
        let resource_bytes = fs::read(&resource_path).unwrap();
        let resources: Vec<BTreeMap<String, String>> = serde_json::from_slice(&resource_bytes).unwrap();
        assert_eq!(resources.len(), 30);
        let inputs = resources.iter().map(|row| Mc2CampaignInputs::with_owner_cache(&row["package_dir"], &row["owner_cache_path"])).collect::<Vec<_>>();
        let resolver = Mc2RuntimePackageResolver::load(inputs).unwrap();
        let entries = resolver.flow().entries();
        let level2 = entries[1].level_id().clone();
        let first = resolver.package(resolver.flow().entry_level_id()).unwrap();
        let package = resolver.package(&level2).unwrap();
        assert_eq!(package.selection, CampaignSelection::LEVEL2);
        let mut runtime = GameRuntime::<Mc2CampaignBackend>::title(8956).unwrap();
        let title = runtime.identity();
        // Declared completed Level1 frontier only. No incoming inventory,
        // pose, actor, holder or encounter state is staged.
        let map = runtime.restore_campaign_resolved(title.guard(), CampaignSaveState {
            definition: first.definition.as_ref().clone(), phase: CampaignMenuPhase::MissionSelect,
            completed_level_id: None, selected_level_id: Some(level2.clone()),
            completed_levels: vec![resolver.flow().entry_level_id().clone()], level_statistics: Vec::new(),
        }, Default::default(), |definition, selected| {
            resolver.exact_package_for_definition(definition)?;
            Ok(Arc::clone(&resolver.package(selected).unwrap().definition))
        }).unwrap();
        let loading = resolver.campaign_menu_command(&mut runtime, map.guard(), CampaignMenuCommand::StartMission).unwrap();
        resolver.open_pending(&mut runtime, loading.guard(), 8956).unwrap();
        let entry = runtime.session().unwrap().backend().campaign.simulation().state;
        let initial_target = runtime.session().unwrap().backend().campaign.simulation().entities()[112].clone();
        assert!(initial_target.active && (initial_target.class, initial_target.model) == (3, 1));
        let target_handle = runtime.session().unwrap().backend().campaign.simulation().source_arena().handle(112).unwrap();
        let mut public_commands = Vec::new();
        // Reuse the existing public flight helper; its Fireball-specific
        // approach/cast predicate is intentionally not used by this route.
        for _ in 0..1_280 {
            let session = runtime.session().unwrap();
            let sim = session.backend().campaign.simulation();
            let target = &sim.entities()[112];
            assert!(target.active && (target.class, target.model) == (3, 1));
            assert_eq!(sim.source_arena().handle(112), Some(target_handle));
            assert!(sim.session.state.live.player_life >= 0);
            if crate::distance_3d_wrapped(sim.state.position, target.position) <= 4_000 { break; }
            let command = source_public_creature_pursuit_command_for_test(session, target.position);
            assert!(command.select_spell.is_none() && !command.cast_selected && !command.cast_left && !command.cast_right);
            let guard = session.identity().guard();
            public_commands.push(command.clone());
            runtime.advance_player_with_preferences(guard, command).unwrap();
        }
        let sim = runtime.session().unwrap().backend().campaign.simulation();
        assert!(crate::distance_3d_wrapped(sim.state.position, sim.entities()[112].position) <= 4_000,
            "bounded public approach did not reach the real source sprite range");
        // Match RuntimeRecord's real world-frame role. The separate
        // presentation cache supplies audio/UI, not source terrain authority.
        let assets = DayIndexedFrameAssets::load(&resources[1]["owner_cache_path"]).unwrap();
        let mut admitted = None;
        // Fixed public look controls, after real approach. The yaw offset
        // places the rival on the left, as required by literal lowres labels.
        for look_pitch in [32_i16, 64, 96, 0, -32] {
            let session = runtime.session().unwrap();
            let sim = session.backend().campaign.simulation();
            let target = &sim.entities()[112];
            let look_yaw = (crate::heading_for_positions(sim.state.position, target.position) as i16)
                .wrapping_add(64).wrapping_sub(sim.state.yaw);
            let command = GameCommand { full_stop: true,
                look_yaw, look_pitch, ..GameCommand::default() };
            let guard = session.identity().guard();
            public_commands.push(command.clone());
            runtime.advance_player_with_preferences(guard, command).unwrap();
            let session = runtime.session().unwrap();
            let sim = session.backend().campaign.simulation();
            assert_eq!(sim.source_arena().handle(112), Some(target_handle));
            let view = sim.source_camera_pose();
            let row = sim.campaign_entity_presentations(view.yaw).unwrap().into_iter()
                .find(|row| row.entity_index == 112).expect("current real Nyphur source draw row");
            let label = row.player_label.expect("real class3/model1 A4 label");
            assert_eq!(&label.name_bytes[..usize::from(label.name_len)], b"Nyphur");
            let frame = assets.environment_resources().source_tmaps().unwrap().frame(row.selected_tmap).unwrap();
            let camera = crate::terrain_frame::Level1TerrainFrameCamera { render_x: view.x, render_y: view.y,
                eye_z: i32::from(view.z), yaw: view.yaw, pitch: view.pitch, roll: view.roll,
                fov: 128, source_turn: sim.shared_spells().local_player().turn, reflections: true };
            let placement = project_fixed_sprite_with_depth_adjustment(
                Mode20SpriteDefinition { base_selector: row.selected_tmap, logical_height: i32::from(row.logical_height) },
                matches!(row.render_mode, 11 | 36).then_some(0), matches!(row.render_mode, 21 | 36),
                Mode20SpriteCamera { render_x: view.x, render_y: view.y, eye_z: i32::from(view.z), yaw: view.yaw,
                    projection: crate::terrain_frame::level1_projection(camera) },
                Mode20SpriteEntity { x: row.position.x, y: row.position.y, z: row.position.z, yaw: row.yaw },
                frame.width, frame.height, row.primary_depth_adjustment,
            ).expect("actual current primary projection is admitted");
            if placement.quarter_sum_anchor { continue; }
            let sin = crate::SIN_16_16[usize::from(view.roll as u16 & 2047)];
            let cos = crate::SIN_16_16[512 + usize::from(view.roll as u16 & 2047)];
            let top_y = placement.bottom_y - ((cos.wrapping_mul(placement.projected_height)
                - (sin.wrapping_mul(placement.projected_width) >> 1)) >> 16);
            let top_x = placement.bottom_x - (((cos.wrapping_mul(placement.projected_width) >> 1)
                + sin.wrapping_mul(placement.projected_height)) >> 16);
            let label_x = ((top_x + (placement.projected_width >> 1)) as i16).wrapping_mul(2);
            let label_y = top_y.wrapping_mul(2) - 20;
            if label_x >= 0 && i32::from(label_x) + 52 <= 316 && (0..178).contains(&label_y) {
                admitted = Some((row, placement, label_x, label_y, look_yaw, look_pitch));
                break;
            }
        }
        let (row, placement, label_x, label_y, look_yaw, look_pitch) = admitted.expect("fixed public look controls must admit the real full Nyphur label");
        let paused = runtime.pause(runtime.identity().guard()).unwrap();
        let save = resolver.save_replay(&runtime).unwrap();
        let mut cold = GameRuntime::<Mc2CampaignBackend>::title(8957).unwrap();
        let title = cold.identity();
        resolver.load_replay(&mut cold, title.guard(), 8957, &save).unwrap();
        assert_eq!(cold.session().unwrap().snapshot().value, runtime.session().unwrap().snapshot().value);
        assert_eq!(resolver.save_replay(&cold).unwrap(), save, "all real receipt fields and input history cold-replay exactly");
        let locale = crate::game_runtime::preferences::installed_locale::InstalledLanguages::load(
            PathBuf::from(std::env::var_os("MC_LANGUAGE_CACHE").expect("actual selected source locale cache")))
            .unwrap().binding(None).unwrap();
        let session = cold.session().unwrap();
        let sim = session.backend().campaign.simulation();
        let generation = session.identity().generation;
        let mut off = DayIndexedFrameState::new(generation);
        off.bind_player_names(false, None, "PLAYER").unwrap();
        let base = off.render_current(session.backend().campaign.inspection(), sim, &assets, generation).unwrap();
        let mut on = DayIndexedFrameState::new(generation);
        on.bind_player_names(true, Some(locale.clone()), "PLAYER").unwrap();
        let named = on.render_current(session.backend().campaign.inspection(), sim, &assets, generation).unwrap();
        let changed = base.scene_indices.iter().zip(&named.scene_indices).filter(|(a,b)| a != b).count();
        assert!(changed > 0, "actual selected FONT1/current-frame label changes real native indexed pixels");
        assert_eq!(resolver.save_replay(&cold).unwrap(), save, "actual font/world renders are pure");
        let target = &sim.entities()[112];
        let metadata = serde_json::json!({ "proof_boundary": "declared Level2 entry; public approach and look only; no inventory/cast/pose staging",
            "resources": resources, "resource_list": resource_path, "locale": locale.identity,
            "source_package": resources[1]["package_dir"], "source_owner": resources[1]["owner_cache_path"],
            "source_presentation": resources[1]["presentation_cache_path"],
            "entry_player": {"x": entry.position.x,"y": entry.position.y,"z": entry.position.z,"yaw":entry.yaw,"pitch":entry.pitch_accumulator},
            "entry_target": {"x": initial_target.position.x,"y": initial_target.position.y,"z": initial_target.position.z},
            "tick": session.identity().tick, "runtime_mode": paused.mode.as_str(),
            "target": {"slot":112,"class":target.class,"model":target.model,"life":target.life,"max_life":target.max_life,
                "a4":format!("{:?}",target.special_relation),"color":row.player_label.unwrap().player_color_index},
            "public_look": {"yaw":look_yaw,"pitch":look_pitch},
            "public_commands": public_commands,
            "primary": {"x":placement.bottom_x,"y":placement.bottom_y,"width":placement.projected_width,"height":placement.projected_height,
                "selector":row.selected_tmap,"logical_height":row.logical_height,"render_mode":row.render_mode},
            "label": {"x":label_x,"y":label_y,"changed_pixels":changed},
            "state_hash":session.backend().snapshot().state_hash,"terrain_hash":session.backend().snapshot().terrain_hash });
        let mut metadata_file = fs::OpenOptions::new().write(true).create_new(true).open(output.with_extension("json")).unwrap();
        metadata_file.write_all(&serde_json::to_vec_pretty(&metadata).unwrap()).unwrap();
        let mut file = fs::OpenOptions::new().write(true).create_new(true).open(output).unwrap();
        file.write_all(&save).unwrap();
    }

    #[test]
    fn source_viewport_preserves_game_header_across_cold_warm_retry_and_mission_entry() {
        use crate::game_runtime::{CampaignMenuCommand, DisplaySettings, GameRuntime, RuntimeGuard,
            RuntimeMode, SourceViewportAction, preferences::PreferencesCommand};
        let resolver = Mc2RuntimePackageResolver::load([
            Mc2CampaignInputs::new(level_one_descriptor_fixture_path()),
            Mc2CampaignInputs::new(descriptor_fixture_path()),
            Mc2CampaignInputs::new(level_three_descriptor_fixture_path()),
        ]).unwrap();
        let mut runtime = GameRuntime::<Mc2CampaignBackend>::title(8980).unwrap();
        let title = runtime.identity();
        let invalid = sim_session::SessionGuard { session_id: 8980, generation: 0, expected_tick: 0 };
        assert_eq!(title.display_settings.viewport_size, 40);
        assert!(runtime.source_viewport(title.guard(), invalid, SourceViewportAction::MenuDecrease).is_err());
        assert_eq!(runtime.identity(), title);
        let loading = resolver.new_game(&mut runtime, title.guard()).unwrap();
        assert!(runtime.source_viewport(loading.guard(), invalid, SourceViewportAction::MenuDecrease).is_err());
        assert_eq!(runtime.identity(), loading);
        resolver.open_pending(&mut runtime, loading.guard(), 8980).unwrap();
        let request = |runtime: &mut GameRuntime<Mc2CampaignBackend>, action, expected| {
            let before = runtime.identity();
            let snapshot = runtime.session().unwrap().snapshot();
            let operations = runtime.session().unwrap().backend().replay_operation_count();
            let notices = runtime.session().unwrap().backend().participant_notifications();
            let guard = runtime.session().unwrap().identity().guard();
            assert!(runtime.source_viewport(before.guard(), guard, action).unwrap());
            assert_eq!(runtime.identity().display_settings,
                DisplaySettings { viewport_size: expected, ..before.display_settings });
            assert_eq!(runtime.identity().session, before.session);
            assert_eq!(runtime.identity().generation, before.generation);
            assert_eq!(runtime.identity().player_preferences, before.player_preferences);
            assert_eq!(runtime.session().unwrap().snapshot(), snapshot,
                "viewport does not dispatch gameplay, RNG, objective or presentation clocks");
            assert_eq!(runtime.session().unwrap().backend().replay_operation_count(), operations);
            assert_eq!(runtime.session().unwrap().backend().participant_notifications(), notices,
                "source case8 has no notification");
        };
        let original = resolver.save_replay(&runtime).unwrap();
        let original_json: serde_json::Value = serde_json::from_slice(&original).unwrap();
        assert!(original_json["initial_display_settings"].get("viewport_size").is_none(),
            "the historical default40 field remains omitted");
        let mut old_cold = GameRuntime::<Mc2CampaignBackend>::title(8981).unwrap();
        let title = old_cold.identity();
        resolver.load_replay(&mut old_cold, title.guard(), 8981, &original).unwrap();
        assert_eq!(old_cold.identity().display_settings.viewport_size, 40);
        assert_eq!(resolver.save_replay(&old_cold).unwrap(), original,
            "an omitted viewport preserves every original receipt byte");
        request(&mut runtime, SourceViewportAction::KeyboardEnlarge, 40);
        request(&mut runtime, SourceViewportAction::MenuIncrease, 40);
        assert_eq!(resolver.save_replay(&runtime).unwrap(), original);
        request(&mut runtime, SourceViewportAction::MenuDecrease, 39);
        let paused = runtime.pause(runtime.identity().guard()).unwrap();
        let nested = runtime.session().unwrap().identity().guard();
        let saved = resolver.save_replay(&runtime).unwrap();
        let packet: Mc2CampaignReplaySave = serde_json::from_slice(&saved).unwrap();
        assert!(packet.verify());
        assert_eq!(packet.initial_display_settings.viewport_size, Some(39));
        for (outer, inner) in [
            (RuntimeGuard { generation: paused.generation + 1, ..paused.guard() }, nested),
            (paused.guard(), sim_session::SessionGuard { generation: nested.generation + 1, ..nested }),
            (paused.guard(), sim_session::SessionGuard { expected_tick: nested.expected_tick + 1, ..nested }),
        ] {
            assert!(runtime.source_viewport(outer, inner, SourceViewportAction::MenuDecrease).is_err());
            assert_eq!(runtime.identity(), paused);
            assert_eq!(resolver.save_replay(&runtime).unwrap(), saved);
        }
        // No ordinary or paused frame occurs between the setting and save.
        let mut cold = GameRuntime::<Mc2CampaignBackend>::title(8982).unwrap();
        let title = cold.identity();
        resolver.load_replay(&mut cold, title.guard(), 8982, &saved).unwrap();
        assert_eq!(cold.identity().mode, RuntimeMode::Paused);
        assert_eq!(cold.identity().display_settings, paused.display_settings);
        assert_eq!(resolver.save_replay(&cold).unwrap(), saved);
        for bad_size in [0, 15, 41, 255] {
            let mut bad = packet.clone();
            bad.initial_display_settings.viewport_size = Some(bad_size);
            bad.receipt_sha256 = bad.compute_receipt_sha256();
            let mut rejected = GameRuntime::<Mc2CampaignBackend>::title(9100 + u64::from(bad_size)).unwrap();
            let title = rejected.identity();
            assert!(resolver.load_replay(&mut rejected, title.guard(), title.runtime_id,
                &serde_json::to_vec(&bad).unwrap()).is_err(), "a rehashed invalid GAME size is refused");
            assert_eq!(rejected.identity(), title);
        }
        for size in (16..39).rev() {
            request(&mut runtime, SourceViewportAction::MenuDecrease, size);
        }
        let smallest = resolver.save_replay(&runtime).unwrap();
        request(&mut runtime, SourceViewportAction::MenuDecrease, 16);
        request(&mut runtime, SourceViewportAction::KeyboardShrink, 16);
        assert_eq!(resolver.save_replay(&runtime).unwrap(), smallest);
        request(&mut runtime, SourceViewportAction::MenuIncrease, 17);
        let keyboard_limit = resolver.save_replay(&runtime).unwrap();
        request(&mut runtime, SourceViewportAction::KeyboardShrink, 17);
        assert_eq!(resolver.save_replay(&runtime).unwrap(), keyboard_limit);
        request(&mut runtime, SourceViewportAction::MenuIncrease, 18);
        request(&mut runtime, SourceViewportAction::KeyboardShrink, 17);
        request(&mut runtime, SourceViewportAction::KeyboardEnlarge, 18);
        for size in 19..=40 { request(&mut runtime, SourceViewportAction::MenuIncrease, size); }
        request(&mut runtime, SourceViewportAction::MenuDecrease, 39);
        request(&mut runtime, SourceViewportAction::MenuIncrease, 40);
        assert_eq!(resolver.save_replay(&runtime).unwrap(), {
            let mut full = packet.clone();
            full.initial_display_settings.viewport_size = None;
            full.receipt_sha256 = full.compute_receipt_sha256();
            serde_json::to_vec(&full).unwrap()
        }, "returning to40 removes only the optional renderer header field");
        // Receiver globals are real current source inputs, but GAME viewport
        // belongs to the loaded file, unlike the nonserialized Speed value.
        request(&mut runtime, SourceViewportAction::MenuDecrease, 39);
        request(&mut runtime, SourceViewportAction::MenuDecrease, 38);
        let receiver = resolver.source_process_context(&runtime).unwrap();
        let mut warm = GameRuntime::<Mc2CampaignBackend>::title(8983).unwrap();
        let title = warm.identity();
        resolver.load_replay_with_source_context(&mut warm, title.guard(), 8983, &saved, receiver).unwrap();
        assert_eq!(warm.identity().display_settings.viewport_size, 39, "warm restore uses saved GAME size, not receiver38");
        assert_eq!(resolver.save_replay(&warm).unwrap(), saved);
        let id = warm.identity(); warm.resume(id.guard()).unwrap();
        let session = warm.session_mut().unwrap();
        session.reset(session.identity().guard()).unwrap();
        warm.reset_panel_transparency_to_level_default();
        assert_eq!(warm.identity().display_settings.viewport_size, 39, "retry retains viewport GAME byte");
        let reset_bytes = resolver.save_replay(&warm).unwrap();
        let mut reset_cold = GameRuntime::<Mc2CampaignBackend>::title(8984).unwrap();
        let title = reset_cold.identity();
        resolver.load_replay(&mut reset_cold, title.guard(), 8984, &reset_bytes).unwrap();
        assert_eq!(reset_cold.identity().display_settings.viewport_size, 39);
        assert_eq!(resolver.save_replay(&reset_cold).unwrap(), reset_bytes);
        assert!(warm.preferences_command(warm.identity().guard(), PreferencesCommand::Cancel).is_err(),
            "viewport control does not relax generic Playing preference gates");
        let id = warm.identity(); let nested = warm.session().unwrap().identity().guard();
        resolver.close_to_title(&mut warm, id.guard(), nested).unwrap();
        let map_bytes = resolver.save_replay(&warm).unwrap();
        let mut map_cold = GameRuntime::<Mc2CampaignBackend>::title(8985).unwrap();
        let title = map_cold.identity();
        resolver.load_replay(&mut map_cold, title.guard(), 8985, &map_bytes).unwrap();
        assert_eq!(map_cold.identity().display_settings.viewport_size, 39);
        let map = map_cold.identity();
        assert!(map_cold.source_viewport(map.guard(), invalid, SourceViewportAction::MenuDecrease).is_err());
        assert_eq!(map_cold.identity(), map);
        assert_eq!(resolver.save_replay(&map_cold).unwrap(), map_bytes);
        for bad_size in [15, 41] {
            let mut bad: Mc2CampaignMapSave = serde_json::from_slice(&map_bytes).unwrap();
            bad.display_settings.viewport_size = Some(bad_size);
            bad.receipt_sha256 = bad.compute_receipt_sha256();
            let mut rejected = GameRuntime::<Mc2CampaignBackend>::title(9200 + u64::from(bad_size)).unwrap();
            let title = rejected.identity();
            assert!(resolver.load_replay(&mut rejected, title.guard(), title.runtime_id,
                &serde_json::to_vec(&bad).unwrap()).is_err());
            assert_eq!(rejected.identity(), title);
        }
        let loading = resolver.campaign_menu_command(&mut map_cold, map.guard(), CampaignMenuCommand::StartMission).unwrap();
        assert_eq!(loading.display_settings.viewport_size, 39);
        resolver.open_pending(&mut map_cold, loading.guard(), 8985).unwrap();
        assert_eq!(map_cold.identity().display_settings.viewport_size, 39, "real mission entry retains viewport");
    }

    #[test]
    fn source_speed_runs_real_passes_and_orders_process_restore_with_same_tick_actions() {
        use crate::game_runtime::{GameRuntime, RuntimeGuard, RuntimeMode, preferences::PreferencesCommand};
        let resolver = Mc2RuntimePackageResolver::load([
            Mc2CampaignInputs::new(level_one_descriptor_fixture_path()),
            Mc2CampaignInputs::new(descriptor_fixture_path()),
            Mc2CampaignInputs::new(level_three_descriptor_fixture_path()),
        ]).unwrap();
        let mut runtime = GameRuntime::<Mc2CampaignBackend>::title(8994).unwrap();
        let title = runtime.identity();
        let invalid = sim_session::SessionGuard { session_id: 8994, generation: 0, expected_tick: 0 };
        assert!(runtime.source_speed(title.guard(), invalid, false).is_err());
        let loading = resolver.new_game(&mut runtime, title.guard()).unwrap();
        assert!(runtime.source_speed(loading.guard(), invalid, false).is_err());
        resolver.open_pending(&mut runtime, loading.guard(), 8994).unwrap();
        // Detached refusal controls only: no dead/inactive actor is offered
        // as the positive production path below.
        for inactive in [false, true] {
            let mut rejected = runtime.session().unwrap().backend().campaign.clone();
            let slot = usize::from(rejected.simulation().state.entity_index);
            if inactive { rejected.simulation_mut().session.state.live.economy.entities[slot].active = false; }
            else { rejected.simulation_mut().session.state.live.economy.entities[slot].life = -1; }
            let hash = rejected.state_hash();
            assert!(!rejected.simulation_mut().source_speed_action(false).unwrap());
            assert_eq!(rejected.state_hash(), hash);
        }
        let turn = |runtime: &GameRuntime<Mc2CampaignBackend>| runtime.session().unwrap().backend().campaign.simulation().shared_spells().local_player().turn;
        let step = |runtime: &mut GameRuntime<Mc2CampaignBackend>, command: GameCommand, passes: u64| {
            let before = runtime.session().unwrap().backend().campaign.simulation().state;
            let before_turn = turn(runtime);
            let handle = runtime.session().unwrap().backend().campaign.simulation().source_arena().handle(before.entity_index).unwrap();
            let frame = runtime.session().unwrap().backend().campaign.simulation().session.state.live.source_frame_timing_index;
            let inner = runtime.session().unwrap().identity().guard();
            runtime.advance_player_with_preferences(inner, command).unwrap();
            let simulation = runtime.session().unwrap().backend().campaign.simulation();
            assert_eq!(simulation.source_arena().handle(before.entity_index), Some(handle), "same current source player generation");
            assert!(simulation.session.state.live.economy.entities[usize::from(before.entity_index)].life >= 0);
            assert_eq!(simulation.state.tick, before.tick + passes);
            assert_eq!(simulation.state.entity_phase, before.entity_phase.wrapping_add(passes as u8),
                "the actual local player callback visits every UpdateEntities pass");
            assert_eq!(turn(runtime), before_turn.wrapping_add(1), "PlayerEvents executes once");
            assert_eq!(simulation.session.state.live.source_frame_timing_index, frame.wrapping_add(1));
        };
        step(&mut runtime, GameCommand { roll_axis: 90, pitch_axis: 25, ..GameCommand::default() }, 1);
        assert_ne!(runtime.session().unwrap().backend().campaign.simulation().state.roll_accumulator, 0,
            "real input supplies the steering that case7 subsequently clears");
        let source = runtime.identity();
        let inner = runtime.session().unwrap().identity().guard();
        for (outer, nested) in [
            (RuntimeGuard { generation: source.generation + 1, ..source.guard() }, inner),
            (source.guard(), sim_session::SessionGuard { generation: inner.generation + 1, ..inner }),
            (source.guard(), sim_session::SessionGuard { expected_tick: inner.expected_tick + 1, ..inner }),
        ] {
            let bytes = resolver.save_replay(&runtime).unwrap();
            assert!(runtime.source_speed(outer, nested, false).is_err());
            assert_eq!(runtime.identity(), source);
            assert_eq!(resolver.save_replay(&runtime).unwrap(), bytes);
        }
        assert!(runtime.source_speed(source.guard(), inner, false).unwrap());
        assert_eq!(runtime.identity().source_speed_index, 1);
        assert_eq!(runtime.identity().session, source.session, "settings do not dispatch an entity pass");
        let state = runtime.session().unwrap().backend().campaign.simulation().state;
        assert_eq!((state.roll_accumulator, state.pitch_accumulator), (0, 0));
        assert_eq!(runtime.session().unwrap().backend().participant_notifications()[0].kind.as_str(), "participant.game_speed_fast");
        let saved = resolver.save_replay(&runtime).unwrap();
        for _ in 0..3 { let _ = runtime.session().unwrap().snapshot(); assert_eq!(resolver.save_replay(&runtime).unwrap(), saved); }
        step(&mut runtime, GameCommand::default(), 4);
        let id = runtime.identity(); let inner = runtime.session().unwrap().identity().guard();
        assert!(runtime.source_speed(id.guard(), inner, true).unwrap());
        assert_eq!(runtime.identity().source_speed_index, 0, "either button leaves a nonzero speed");
        assert!(runtime.source_speed(id.guard(), inner, true).unwrap());
        assert_eq!(runtime.identity().source_speed_index, 2);
        assert_eq!(runtime.session().unwrap().backend().participant_notifications()[0].kind.as_str(), "participant.game_speed_super_fast");
        step(&mut runtime, GameCommand::default(), 8);
        let paused = runtime.pause(runtime.identity().guard()).unwrap();
        let inner = runtime.session().unwrap().identity().guard();
        let before = runtime.session().unwrap().backend().campaign.simulation().state;
        let before_turn = turn(&runtime);
        runtime.paused_campaign_frame_timed(paused.guard(), inner, 0, false).unwrap();
        assert_eq!(runtime.session().unwrap().backend().campaign.simulation().state.tick, before.tick);
        assert_eq!(turn(&runtime), before_turn.wrapping_add(1));
        assert_eq!(runtime.identity().source_speed_index, 2);
        let original = resolver.save_replay(&runtime).unwrap();
        let packet: Mc2CampaignReplaySave = serde_json::from_slice(&original).unwrap();
        assert!(packet.verify());
        let mut cold = GameRuntime::<Mc2CampaignBackend>::title(8995).unwrap();
        let cold_title = cold.identity();
        resolver.load_replay(&mut cold, cold_title.guard(), 8995, &original).unwrap();
        assert_eq!(cold.identity().mode, RuntimeMode::Paused);
        assert_eq!(cold.identity().source_speed_index, 0, "cold process does not import auxiliary speed from SLEV");
        assert_eq!(cold.identity().session.as_ref().unwrap().tick, before.tick);
        assert_eq!(cold.session().unwrap().backend().campaign.simulation().state, runtime.session().unwrap().backend().campaign.simulation().state);
        let cold_bytes = resolver.save_replay(&cold).unwrap();
        let mut cold_again = GameRuntime::<Mc2CampaignBackend>::title(8996).unwrap();
        let id = cold_again.identity();
        resolver.load_replay(&mut cold_again, id.guard(), 8996, &cold_bytes).unwrap();
        assert_eq!(resolver.save_replay(&cold_again).unwrap(), cold_bytes);
        // Actual receiver control establishes1. Load verifies saved2 first,
        // retains receiver1, then a same-tick input must execute AFTER restore.
        let id = runtime.identity(); let inner = runtime.session().unwrap().identity().guard();
        runtime.source_speed(id.guard(), inner, false).unwrap();
        runtime.source_speed(id.guard(), inner, false).unwrap();
        let receiver = resolver.source_process_context(&runtime).unwrap();
        assert_eq!(receiver.source_speed_index, 1);
        // The public warm-load path captures a live receiver's globals and
        // restores into a distinct fresh Title owner.
        let mut warm = GameRuntime::<Mc2CampaignBackend>::title(8997).unwrap();
        let title = warm.identity();
        resolver.load_replay_with_source_context(&mut warm, title.guard(), 8997, &original, receiver).unwrap();
        assert_eq!(warm.identity().source_speed_index, 1);
        let id = warm.identity(); let inner = warm.session().unwrap().identity().guard();
        warm.source_speed(id.guard(), inner, true).unwrap();
        assert_eq!(warm.identity().source_speed_index, 0);
        let ordered = resolver.save_replay(&warm).unwrap();
        let mut ordered_cold = GameRuntime::<Mc2CampaignBackend>::title(8998).unwrap();
        let title = ordered_cold.identity();
        resolver.load_replay(&mut ordered_cold, title.guard(), 8998, &ordered).unwrap();
        assert_eq!(resolver.save_replay(&ordered_cold).unwrap(), ordered);
        assert_eq!(ordered_cold.identity().source_speed_index, 0);
        // Reset source state rather than persisting this auxiliary in CONFIG.
        let id = warm.identity(); warm.resume(id.guard()).unwrap();
        let id = warm.identity(); let inner = warm.session().unwrap().identity().guard();
        warm.source_speed(id.guard(), inner, true).unwrap();
        assert_eq!(warm.identity().source_speed_index, 2);
        warm.session_mut().unwrap().reset(inner).unwrap();
        assert_eq!(warm.identity().source_speed_index, 0);
        assert!(warm.preferences_command(warm.identity().guard(), PreferencesCommand::Cancel).is_err(), "source control did not relax generic Playing preferences");
    }

    #[test]
    fn source_brightness_guard_fade_config_and_immediate_cold_save_are_atomic() {
        use crate::game_runtime::{GameRuntime, RuntimeGuard, preferences::{PreferenceStore, PreferencesCommand, SourceBrightnessAction}};
        let resolver = Mc2RuntimePackageResolver::load([
            Mc2CampaignInputs::new(level_one_descriptor_fixture_path()),
            Mc2CampaignInputs::new(descriptor_fixture_path()),
            Mc2CampaignInputs::new(level_three_descriptor_fixture_path()),
        ]).unwrap();
        let tag = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos();
        let profile = std::env::temp_dir().join(format!("mc-source-brightness-{}-{tag}", std::process::id()));
        let path = profile.join("player-preferences.json");
        let mut runtime = GameRuntime::<Mc2CampaignBackend>::title(8990).unwrap();
        let outer = runtime.identity().guard();
        runtime.preferences_command(outer, PreferencesCommand::Install { profile_dir: profile.to_string_lossy().into_owned() }).unwrap();
        let mut preferences = runtime.identity().player_preferences.preferences;
        preferences.brightness = [2, 0, 3];
        // A real CONFIG choice isolates startup brightness from objective
        // speech flashes. The ordinary objective textbox may remain active.
        preferences.speech_enabled = false;
        preferences.show_help = false;
        runtime.preferences_command(outer, PreferencesCommand::Apply { preferences: preferences.clone() }).unwrap();
        let invalid = sim_session::SessionGuard { session_id: 8990, generation: 0, expected_tick: 0 };
        assert!(runtime.source_brightness_preferences(outer, invalid, SourceBrightnessAction::Cycle).is_err());
        let loading = resolver.new_game(&mut runtime, outer).unwrap();
        assert!(runtime.source_brightness_preferences(loading.guard(), invalid, SourceBrightnessAction::Cycle).is_err());
        resolver.open_pending(&mut runtime, loading.guard(), 8990).unwrap();
        runtime.pause(runtime.identity().guard()).unwrap();
        let draw = |runtime: &mut GameRuntime<Mc2CampaignBackend>| {
            let outer = runtime.identity().guard();
            let inner = runtime.session().unwrap().identity().guard();
            runtime.paused_campaign_frame_timed(outer, inner, 0, false).unwrap();
            assert_eq!(runtime.session().unwrap().identity().tick, 0);
        };
        let blocked = |runtime: &mut GameRuntime<Mc2CampaignBackend>| {
            let before = runtime.identity();
            let bytes = resolver.save_replay(runtime).unwrap();
            let file = fs::read(&path).unwrap();
            let inner = runtime.session().unwrap().identity().guard();
            let result = runtime.source_brightness_preferences(before.guard(), inner, SourceBrightnessAction::Cycle).unwrap();
            assert_eq!(result.source_brightness_admitted, Some(false));
            assert_eq!(runtime.identity(), before);
            assert_eq!(resolver.save_replay(runtime).unwrap(), bytes);
            assert_eq!(fs::read(&path).unwrap(), file);
        };
        blocked(&mut runtime);
        for _ in 0..3 { draw(&mut runtime); blocked(&mut runtime); }
        for step in 0..5 { draw(&mut runtime); if step < 4 { blocked(&mut runtime); } }
        assert!(runtime.session().unwrap().backend().source_brightness_admitted());
        assert_eq!(runtime.session().unwrap().backend().source_brightness_slot(), 1, "actual Night owner selects CONFIG byte12");
        let ready = runtime.identity();
        let inner = runtime.session().unwrap().identity().guard();
        let bytes = resolver.save_replay(&runtime).unwrap();
        for (outer, nested) in [
            (RuntimeGuard { generation: ready.generation + 1, ..ready.guard() }, inner),
            (ready.guard(), sim_session::SessionGuard { generation: inner.generation + 1, ..inner }),
            (ready.guard(), sim_session::SessionGuard { expected_tick: inner.expected_tick + 1, ..inner }),
        ] {
            assert!(runtime.source_brightness_preferences(outer, nested, SourceBrightnessAction::Cycle).is_err());
            assert_eq!(runtime.identity(), ready);
            assert_eq!(resolver.save_replay(&runtime).unwrap(), bytes);
        }
        let retained = profile.join("retained.json");
        fs::rename(&path, &retained).unwrap(); fs::create_dir(&path).unwrap();
        assert!(runtime.source_brightness_preferences(ready.guard(), inner, SourceBrightnessAction::Cycle).is_err());
        assert_eq!(runtime.identity(), ready);
        assert_eq!(resolver.save_replay(&runtime).unwrap(), bytes);
        fs::remove_dir(&path).unwrap(); fs::rename(retained, &path).unwrap();
        for action in [SourceBrightnessAction::Decrement, SourceBrightnessAction::Cycle,
            SourceBrightnessAction::Cycle, SourceBrightnessAction::Cycle, SourceBrightnessAction::Cycle,
            SourceBrightnessAction::Increment, SourceBrightnessAction::Cycle] {
            let identity = runtime.identity();
            let before = identity.player_preferences.preferences.clone();
            let inner = runtime.session().unwrap().identity().guard();
            let accepted = runtime.source_brightness_preferences(identity.guard(), inner, action).unwrap();
            assert_eq!(accepted.source_brightness_admitted, Some(true));
            let expected = match action { SourceBrightnessAction::Cycle => (before.brightness[1] + 1) % 5,
                SourceBrightnessAction::Increment => before.brightness[1].saturating_add(1).min(4),
                SourceBrightnessAction::Decrement => before.brightness[1].saturating_sub(1) };
            let mut unchanged = before; unchanged.brightness[1] = expected;
            assert_eq!(accepted.preferences, unchanged);
            assert_eq!(runtime.identity().session, identity.session);
            // Save at the SAME operation boundary, before even one fade draw.
            let saved = resolver.save_replay(&runtime).unwrap();
            let mut cold = GameRuntime::<Mc2CampaignBackend>::title(8991).unwrap();
            let title = cold.identity();
            resolver.load_replay(&mut cold, title.guard(), 8991, &saved).unwrap();
            assert_eq!(resolver.save_replay(&cold).unwrap(), saved);
            assert_eq!(cold.session().unwrap().snapshot().value, runtime.session().unwrap().snapshot().value);
            assert!(!cold.session().unwrap().backend().source_brightness_admitted());
            let mut reopened = PreferenceStore::default();
            assert_eq!(reopened.command(PreferencesCommand::Install { profile_dir: profile.to_string_lossy().into_owned() }).unwrap().preferences, unchanged);
            blocked(&mut runtime);
            for _ in 0..5 { draw(&mut runtime); }
            assert!(runtime.session().unwrap().backend().source_brightness_admitted());
        }
        // Ordinary Playing does not grant the generic Apply mutation path.
        let id = runtime.identity(); runtime.resume(id.guard()).unwrap();
        assert!(runtime.preferences_command(runtime.identity().guard(), PreferencesCommand::Apply { preferences }).is_err());
        fs::remove_dir_all(profile).unwrap();
    }

    #[test]
    fn runtime_panel_transparency_keeps_game_save_and_level_init_lifetimes() {
        use crate::game_runtime::{CampaignMenuCommand, CampaignMenuPhase, CampaignSaveState, GameRuntime, RuntimeMode};
        let generated = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../../generated");
        let ordinary = std::env::var_os("MC_ORDINARY_CAMPAIGN_PACKAGES")
            .map(PathBuf::from).unwrap_or_else(|| generated.join("mc-bhq6-ordinary-20261025-zclu5fjj"));
        let resolver = Mc2RuntimePackageResolver::load([
            Mc2CampaignInputs::new(level_one_descriptor_fixture_path()),
            Mc2CampaignInputs::new(descriptor_fixture_path()),
            Mc2CampaignInputs::new(level_three_descriptor_fixture_path()),
            Mc2CampaignInputs::new(ordinary.join("level4")),
        ]).unwrap();
        let start = |runtime: &mut GameRuntime<Mc2CampaignBackend>, index: usize| {
            let title = runtime.identity();
            let loading = if index == 0 {
                resolver.new_game(runtime, title.guard()).unwrap()
            } else {
                // Declared completed frontier only; no earned playthrough.
                // The real resolver/open/LevelInit uses the unchanged Cave owner.
                let map = runtime.restore_campaign_resolved(title.guard(), CampaignSaveState {
                    definition: resolver.package(resolver.flow.entry_level_id()).unwrap().definition.as_ref().clone(),
                    phase: CampaignMenuPhase::MissionSelect, completed_level_id: None,
                    selected_level_id: Some(resolver.flow.entries()[index].level_id().clone()),
                    completed_levels: resolver.flow.entries()[..index].iter().map(|entry| entry.level_id().clone()).collect(),
                    level_statistics: Vec::new(),
                }, Default::default(), |definition, selected| {
                    resolver.exact_package_for_definition(definition)?;
                    Ok(Arc::clone(&resolver.package(selected).unwrap().definition))
                }).unwrap();
                resolver.campaign_menu_command(runtime, map.guard(), CampaignMenuCommand::StartMission).unwrap()
            };
            let invalid = sim_session::SessionGuard { session_id: title.runtime_id, generation: 1, expected_tick: 0 };
            assert!(runtime.toggle_panel_transparency(loading.guard(), invalid).is_err());
            assert!(runtime.toggle_flat_shading(loading.guard(), invalid).is_err());
            assert_eq!(runtime.identity(), loading);
            resolver.open_pending(runtime, loading.guard(), title.runtime_id).unwrap()
        };
        for (index, map_default) in [(0, false), (3, true)] {
            let mut runtime = GameRuntime::<Mc2CampaignBackend>::title(8890 + index as u64).unwrap();
            let title = runtime.identity();
            let invalid = sim_session::SessionGuard { session_id: title.runtime_id, generation: 1, expected_tick: 0 };
            assert!(runtime.toggle_panel_transparency(title.guard(), invalid).is_err());
            assert!(runtime.toggle_flat_shading(title.guard(), invalid).is_err());
            assert_eq!(runtime.identity(), title);
            let playing = start(&mut runtime, index);
            assert_eq!(playing.display_settings.panels_opaque, map_default);
            assert!(!playing.display_settings.flat_shading);
            let initial_save = resolver.save_replay(&runtime).unwrap();
            // Format control for an old omitted panel field: retain all real
            // owner bytes/receipts except the new optional header field.
            let mut legacy: Mc2CampaignReplaySave = serde_json::from_slice(&initial_save).unwrap();
            legacy.initial_display_settings.panels_opaque = None;
            legacy.receipt_sha256 = legacy.compute_receipt_sha256();
            let mut old_cold = GameRuntime::<Mc2CampaignBackend>::title(8900 + index as u64).unwrap();
            let title = old_cold.identity();
            resolver.load_replay(&mut old_cold, title.guard(), title.runtime_id, &serde_json::to_vec(&legacy).unwrap()).unwrap();
            assert_eq!(old_cold.identity().display_settings.panels_opaque, map_default);
            assert!(!old_cold.identity().display_settings.flat_shading);
            let nested = runtime.session().unwrap().identity().guard();
            runtime.toggle_flat_shading(playing.guard(), nested).unwrap();
            assert!(runtime.identity().display_settings.flat_shading);
            assert_eq!(runtime.identity().session, playing.session);
            let flat_notice = runtime.session().unwrap().backend().participant_notifications();
            assert_eq!(flat_notice.len(), 1);
            assert_eq!(flat_notice[0].kind.as_str(), "participant.flat_shading_on");
            assert_eq!(flat_notice[0].remaining_frames, 50);
            runtime.toggle_icons_and_map(playing.guard(), nested).unwrap();
            let icons = runtime.identity().display_settings;
            runtime.toggle_panel_transparency(playing.guard(), nested).unwrap();
            assert_eq!(runtime.identity().session, playing.session);
            assert_eq!(runtime.identity().display_settings.panels_opaque, !map_default);
            assert_eq!((runtime.identity().display_settings.minimap, runtime.identity().display_settings.top_bar),
                (icons.minimap, icons.top_bar));
            let notice = runtime.session().unwrap().backend().participant_notifications();
            assert_eq!(notice.len(), 1);
            assert_eq!(notice[0].kind.as_str(), if map_default { "participant.panel_transparency_on" } else { "participant.panel_transparency_off" });
            assert_eq!(notice[0].remaining_frames, 50);
            let simulation = runtime.session().unwrap().backend().campaign.simulation();
            let color = usize::from(simulation.shared_spells().local_player().player_color_index());
            assert_eq!(simulation.player_lifecycle_notifications().entries()[color].state, 3);
            let paused = runtime.pause(playing.guard()).unwrap();
            let nested = runtime.session().unwrap().identity().guard();
            runtime.toggle_flat_shading(paused.guard(), nested).unwrap();
            assert_eq!(runtime.session().unwrap().backend().participant_notifications()[0].kind.as_str(), "participant.flat_shading_off");
            runtime.toggle_flat_shading(paused.guard(), nested).unwrap();
            runtime.toggle_panel_transparency(paused.guard(), nested).unwrap();
            runtime.toggle_panel_transparency(paused.guard(), nested).unwrap();
            let before = runtime.identity();
            let bytes = resolver.save_replay(&runtime).unwrap();
            let mut bad: Mc2CampaignReplaySave = serde_json::from_slice(&bytes).unwrap();
            bad.initial_display_settings.panels_opaque = Some(!map_default);
            bad.receipt_sha256 = bad.compute_receipt_sha256();
            let mut rejected = GameRuntime::<Mc2CampaignBackend>::title(8940 + index as u64).unwrap();
            let title = rejected.identity();
            let title_bytes = resolver.save_replay(&rejected).unwrap();
            assert!(resolver.load_replay(&mut rejected, title.guard(), title.runtime_id,
                &serde_json::to_vec(&bad).unwrap()).is_err(), "rehashed header cannot change LevelInit policy");
            assert_eq!(rejected.identity(), title);
            assert_eq!(resolver.save_replay(&rejected).unwrap(), title_bytes);
            for (outer, inner) in [
                (crate::game_runtime::RuntimeGuard { generation: before.generation + 1, ..before.guard() }, nested),
                (before.guard(), sim_session::SessionGuard { generation: nested.generation + 1, ..nested }),
                (before.guard(), sim_session::SessionGuard { expected_tick: nested.expected_tick + 1, ..nested }),
            ] {
                assert!(runtime.toggle_panel_transparency(outer, inner).is_err());
                assert!(runtime.toggle_flat_shading(outer, inner).is_err());
                assert_eq!(runtime.identity(), before);
                assert_eq!(resolver.save_replay(&runtime).unwrap(), bytes);
            }
            let mut cold = GameRuntime::<Mc2CampaignBackend>::title(8910 + index as u64).unwrap();
            let title = cold.identity();
            resolver.load_replay(&mut cold, title.guard(), title.runtime_id, &bytes).unwrap();
            assert_eq!(cold.identity().mode, RuntimeMode::Paused);
            assert_eq!(cold.identity().display_settings, before.display_settings);
            assert_eq!(cold.session().unwrap().backend().participant_notifications(), runtime.session().unwrap().backend().participant_notifications());
            assert_eq!(resolver.save_replay(&cold).unwrap(), bytes);
            let session_guard = cold.session().unwrap().identity().guard();
            cold.presentation_frame(cold.identity().guard(), session_guard, false).unwrap();
            assert_eq!(cold.session().unwrap().backend().participant_notifications()[0].remaining_frames, 50);
            for remaining in (0..50).rev() {
                cold.presentation_frame(cold.identity().guard(), session_guard, true).unwrap();
                assert_eq!(cold.session().unwrap().backend().participant_notifications()[0].remaining_frames, remaining);
            }
            cold.presentation_frame(cold.identity().guard(), session_guard, true).unwrap();
            assert!(cold.session().unwrap().backend().participant_notifications().is_empty());
            let identity = cold.identity();
            cold.resume(identity.guard()).unwrap();
            let session = cold.session_mut().unwrap();
            session.reset(session.identity().guard()).unwrap();
            cold.reset_panel_transparency_to_level_default();
            assert_eq!(cold.identity().display_settings.panels_opaque, map_default);
            assert!(cold.identity().display_settings.flat_shading, "LevelInit/retry preserves flat GAME byte");
            assert_eq!((cold.identity().display_settings.minimap, cold.identity().display_settings.top_bar),
                (icons.minimap, icons.top_bar));
            assert_eq!(cold.identity().session.as_ref().unwrap().tick, 0);
            let reset_save = resolver.save_replay(&cold).unwrap();
            let mut restored = GameRuntime::<Mc2CampaignBackend>::title(8920 + index as u64).unwrap();
            let title = restored.identity();
            resolver.load_replay(&mut restored, title.guard(), title.runtime_id, &reset_save).unwrap();
            assert_eq!(restored.identity().display_settings, cold.identity().display_settings);
            // A detached GAME map retains the accepted flag. Its next real
            // entry runs LevelInit and restores that destination's default.
            let id = cold.identity();
            let nested = cold.session().unwrap().identity().guard();
            cold.toggle_panel_transparency(id.guard(), nested).unwrap();
            cold.close(id.guard(), nested).unwrap();
            let map_bytes = resolver.save_replay(&cold).unwrap();
            let mut map_cold = GameRuntime::<Mc2CampaignBackend>::title(8930 + index as u64).unwrap();
            let title = map_cold.identity();
            resolver.load_replay(&mut map_cold, title.guard(), title.runtime_id, &map_bytes).unwrap();
            assert_eq!(map_cold.identity().display_settings.panels_opaque, !map_default);
            let map = map_cold.identity();
            assert!(map_cold.toggle_panel_transparency(map.guard(), invalid).is_err());
            assert!(map_cold.toggle_flat_shading(map.guard(), invalid).is_err());
            assert_eq!(map_cold.identity(), map);
            assert_eq!(resolver.save_replay(&map_cold).unwrap(), map_bytes);
            let loading = resolver.campaign_menu_command(&mut map_cold, map.guard(), CampaignMenuCommand::StartMission).unwrap();
            resolver.open_pending(&mut map_cold, loading.guard(), map.runtime_id).unwrap();
            assert_eq!(map_cold.identity().display_settings.panels_opaque, map_default);
            assert!(map_cold.identity().display_settings.flat_shading, "mission entry preserves flat GAME byte");
        }
    }

    #[test]
    fn runtime_display_toggle_replays_same_slot_notice_and_saved_global_flags() {
        use crate::game_runtime::{DisplaySettings, GameRuntime, RuntimeMode};
        let resolver = Mc2RuntimePackageResolver::load([
            Mc2CampaignInputs::new(level_one_descriptor_fixture_path()),
            Mc2CampaignInputs::new(descriptor_fixture_path()),
            Mc2CampaignInputs::new(level_three_descriptor_fixture_path()),
        ]).unwrap();
        let mut runtime = GameRuntime::<Mc2CampaignBackend>::title(8860).unwrap();
        assert_eq!(runtime.identity().display_settings, DisplaySettings::default());
        let title = runtime.identity();
        let invalid_session = sim_session::SessionGuard { session_id: 8860, generation: 1, expected_tick: 0 };
        let title_save = resolver.save_replay(&runtime).unwrap();
        assert!(runtime.toggle_icons_and_map(title.guard(), invalid_session).is_err());
        assert_eq!(runtime.identity(), title);
        assert_eq!(resolver.save_replay(&runtime).unwrap(), title_save);
        assert!(serde_json::from_slice::<serde_json::Value>(&title_save).unwrap().get("display_settings").is_none());
        let loading = resolver.new_game(&mut runtime, title.guard()).unwrap();
        assert!(runtime.toggle_icons_and_map(loading.guard(), invalid_session).is_err());
        assert_eq!(runtime.identity(), loading);
        resolver.open_pending(&mut runtime, loading.guard(), 8860).unwrap();
        let initial = runtime.identity();
        let initial_save = resolver.save_replay(&runtime).unwrap();
        assert_eq!(serde_json::from_slice::<serde_json::Value>(&initial_save).unwrap()["initial_display_settings"],
            serde_json::json!({"minimap": true, "top_bar": true, "panels_opaque": false}));
        let session_guard = runtime.session().unwrap().identity().guard();
        runtime.toggle_icons_and_map(initial.guard(), session_guard).unwrap();
        assert_eq!(runtime.identity().generation, initial.generation);
        assert_eq!(runtime.identity().session, initial.session);
        assert_eq!(runtime.identity().display_settings, DisplaySettings { minimap: false, top_bar: false, panels_opaque: false, flat_shading: false, viewport_size: 40,..DisplaySettings::default() });
        let notices = runtime.session().unwrap().backend().participant_notifications();
        assert_eq!(notices.len(), 1);
        assert!(notices[0].is_local);
        assert_eq!(notices[0].kind.as_str(), "participant.icons_map_hidden");
        assert_eq!(notices[0].remaining_frames, 50);
        let before = runtime.identity();
        let before_save = resolver.save_replay(&runtime).unwrap();
        for (outer, nested) in [
            (initial.guard(), sim_session::SessionGuard { generation: session_guard.generation + 1, ..session_guard }),
            (initial.guard(), sim_session::SessionGuard { expected_tick: session_guard.expected_tick + 1, ..session_guard }),
            (crate::game_runtime::RuntimeGuard { generation: initial.generation + 1, ..initial.guard() }, session_guard),
        ] {
            assert!(runtime.toggle_icons_and_map(outer, nested).is_err());
            assert_eq!(runtime.identity(), before);
            assert_eq!(resolver.save_replay(&runtime).unwrap(), before_save);
        }
        runtime.presentation_frame(before.guard(), session_guard, false).unwrap();
        assert_eq!(runtime.session().unwrap().backend().participant_notifications(), notices);
        let paused = runtime.pause(before.guard()).unwrap();
        let session_guard = runtime.session().unwrap().identity().guard();
        runtime.toggle_icons_and_map(paused.guard(), session_guard).unwrap();
        assert_eq!(runtime.session().unwrap().backend().participant_notifications()[0].kind.as_str(), "participant.icons_map_visible");
        runtime.toggle_icons_and_map(paused.guard(), session_guard).unwrap();
        assert_eq!(runtime.session().unwrap().backend().participant_notifications().len(), 1);
        for _ in 0..7 {
            runtime.presentation_frame(paused.guard(), session_guard, true).unwrap();
        }
        assert_eq!(runtime.session().unwrap().backend().participant_notifications()[0].remaining_frames, 43);
        let saved = resolver.save_replay(&runtime).unwrap();
        let saved_hash = runtime.session().unwrap().snapshot().value.state_hash;
        let mut cold = GameRuntime::<Mc2CampaignBackend>::title(8861).unwrap();
        let title = cold.identity();
        resolver.load_replay(&mut cold, title.guard(), 8861, &saved).unwrap();
        assert_eq!(cold.identity().mode, RuntimeMode::Paused);
        assert_eq!(cold.identity().display_settings, runtime.identity().display_settings);
        assert_eq!(cold.session().unwrap().snapshot().value.state_hash, saved_hash);
        assert_eq!(cold.session().unwrap().backend().participant_notifications(), runtime.session().unwrap().backend().participant_notifications());
        assert_eq!(resolver.save_replay(&cold).unwrap(), saved);
        let cold_identity = cold.identity();
        let cold_guard = cold.session().unwrap().identity().guard();
        for remaining in (0..43).rev() {
            cold.presentation_frame(cold_identity.guard(), cold_guard, true).unwrap();
            assert_eq!(cold.session().unwrap().backend().participant_notifications()[0].remaining_frames, remaining);
        }
        cold.presentation_frame(cold_identity.guard(), cold_guard, true).unwrap();
        assert!(cold.session().unwrap().backend().participant_notifications().is_empty());
        assert_eq!(cold.identity(), cold_identity, "presentation does not advance either guarded owner");
        cold.resume(cold_identity.guard()).unwrap();
        let session = cold.session_mut().unwrap();
        session.reset(session.identity().guard()).unwrap();
        assert!(!cold.identity().display_settings.minimap, "retry does not run source SetKeysDefault");
        let reset_save = resolver.save_replay(&cold).unwrap();
        let reset_json: serde_json::Value = serde_json::from_slice(&reset_save).unwrap();
        assert_eq!(reset_json["initial_display_settings"], serde_json::json!({"minimap": false, "top_bar": false, "panels_opaque": false}));
        let mut reset_cold = GameRuntime::<Mc2CampaignBackend>::title(8862).unwrap();
        let title = reset_cold.identity();
        resolver.load_replay(&mut reset_cold, title.guard(), 8862, &reset_save).unwrap();
        assert_eq!(reset_cold.identity().display_settings, cold.identity().display_settings);
        assert_eq!(resolver.save_replay(&reset_cold).unwrap(), reset_save);

        // Source GAME settings also survive detached map/Title saves. This
        // retained display carrier is not a profile/CONFIG setting.
        let outer = cold.identity().guard();
        let nested = cold.session().unwrap().identity().guard();
        cold.close(outer, nested).unwrap();
        let map_save = resolver.save_replay(&cold).unwrap();
        let mut map_cold = GameRuntime::<Mc2CampaignBackend>::title(8863).unwrap();
        let title = map_cold.identity();
        resolver.load_replay(&mut map_cold, title.guard(), 8863, &map_save).unwrap();
        assert_eq!(map_cold.identity().mode, RuntimeMode::Campaign);
        assert_eq!(map_cold.identity().display_settings, cold.identity().display_settings);
        let map_identity = map_cold.identity();
        assert!(map_cold.toggle_icons_and_map(map_identity.guard(), invalid_session).is_err());
        assert_eq!(map_cold.identity(), map_identity);
        assert_eq!(resolver.save_replay(&map_cold).unwrap(), map_save);
        let mut bad: serde_json::Value = serde_json::from_slice(&map_save).unwrap();
        bad["display_settings"]["minimap"] = serde_json::json!(true);
        let mut rejected = GameRuntime::<Mc2CampaignBackend>::title(8864).unwrap();
        let before = rejected.identity();
        let before_save = resolver.save_replay(&rejected).unwrap();
        assert!(resolver.load_replay(&mut rejected, before.guard(), 8864, &serde_json::to_vec(&bad).unwrap()).is_err());
        assert_eq!(rejected.identity(), before);
        assert_eq!(resolver.save_replay(&rejected).unwrap(), before_save);
    }

    #[test]
    fn fresh_help_preference_matches_reset_baseline_and_replays_at_operation_zero() {
        use crate::game_runtime::GameRuntime;
        let resolver = Mc2RuntimePackageResolver::load([
            Mc2CampaignInputs::new(level_one_descriptor_fixture_path()),
            Mc2CampaignInputs::new(descriptor_fixture_path()),
            Mc2CampaignInputs::new(level_three_descriptor_fixture_path()),
        ]).unwrap();
        let mut runtime = GameRuntime::<Mc2CampaignBackend>::title(8849).unwrap();
        let title = runtime.identity();
        let loading = resolver.new_game(&mut runtime, title.guard()).unwrap();
        resolver.open_pending(&mut runtime, loading.guard(), 8849).unwrap();
        let zero_save = resolver.save_replay(&runtime).unwrap();
        let mut zero_cold = GameRuntime::<Mc2CampaignBackend>::title(8851).unwrap();
        let title = zero_cold.identity();
        resolver.load_replay(&mut zero_cold, title.guard(), 8851, &zero_save).unwrap();
        zero_cold.session_mut().unwrap().backend_mut().hydrate_fresh_help_preference(false);
        assert!(zero_cold.session().unwrap().backend().help_enabled(), "cold v8 is never a fresh owner");
        assert_eq!(resolver.save_replay(&zero_cold).unwrap(), zero_save);
        let mut invalid: Mc2CampaignReplaySave = serde_json::from_slice(&zero_save).unwrap();
        invalid.help_preference_changes.extend([
            Mc2HelpPreferenceChange { before_operation: 0, enabled: false },
            Mc2HelpPreferenceChange { before_operation: 0, enabled: true },
        ]);
        invalid.receipt_sha256 = invalid.compute_receipt_sha256();
        let mut rejected = GameRuntime::<Mc2CampaignBackend>::title(8852).unwrap();
        let before = rejected.identity();
        let before_save = resolver.save_replay(&rejected).unwrap();
        assert!(resolver.load_replay(&mut rejected, before.guard(), 8852,
            &serde_json::to_vec(&invalid).unwrap()).is_err(), "third zero-operation help change exceeds source boundary");
        assert_eq!(rejected.identity(), before);
        assert_eq!(resolver.save_replay(&rejected).unwrap(), before_save);
        let session = runtime.session_mut().unwrap();
        assert!(session.backend().help_enabled());
        assert_eq!(session.backend().help_preference_changes,
            [Mc2HelpPreferenceChange { before_operation: 0, enabled: true }]);
        let baseline = session.snapshot().value;
        session.step(guard(session), GameCommand::default()).unwrap();
        session.reset(guard(session)).unwrap();
        assert_eq!(session.snapshot().value.state_hash, baseline.state_hash);
        assert_eq!(session.snapshot().value.terrain_hash, baseline.terrain_hash);
        assert!(session.backend().help_enabled());
        assert_eq!(session.backend().help_preference_changes,
            [Mc2HelpPreferenceChange { before_operation: 0, enabled: true }]);
        let saved = resolver.save_replay(&runtime).unwrap();
        let mut cold = GameRuntime::<Mc2CampaignBackend>::title(8850).unwrap();
        let title = cold.identity();
        resolver.load_replay(&mut cold, title.guard(), 8850, &saved).unwrap();
        assert_eq!(cold.session().unwrap().snapshot().value.state_hash, baseline.state_hash);
        assert!(cold.session().unwrap().backend().help_enabled());
    }

    #[test]
    fn runtime_loading_presentation_binds_installed_identity_and_cancel() {
        use crate::game_runtime::{GameRuntime, RuntimeMode, RuntimeTransitionError};
        let mut resolver = Mc2RuntimePackageResolver::load([
            Mc2CampaignInputs::new(
                PathBuf::from(env!("CARGO_MANIFEST_DIR"))
                    .join("../../../generated/mc-bhq8-level1-collision-v5-night"),
            ),
            Mc2CampaignInputs::new(descriptor_fixture_path()),
            Mc2CampaignInputs::new(level_three_descriptor_fixture_path()),
        ])
        .unwrap();
        let mut runtime = GameRuntime::<Mc2CampaignBackend>::title(195).unwrap();
        let title = runtime.identity();
        assert!(matches!(
            resolver.loading_presentation(&runtime, title.guard()),
            Err(RuntimeTransitionError::InvalidMode { .. })
        ));
        assert!(matches!(
            resolver.active_entry_presentation(&runtime, title.guard()),
            Err(RuntimeTransitionError::InvalidMode { .. })
        ));
        let loading = resolver.new_game(&mut runtime, title.guard()).unwrap();
        assert!(matches!(
            resolver.active_entry_presentation(&runtime, loading.guard()),
            Err(RuntimeTransitionError::InvalidMode { .. })
        ));
        let first = resolver
            .loading_presentation(&runtime, loading.guard())
            .unwrap();
        assert_eq!(first.environment, "night");
        assert_eq!(first.artwork_profile, "ordinary");
        assert_eq!(first.source_selection, CampaignSelection::LEVEL1);
        assert_eq!(
            serde_json::to_value(&first).unwrap()["source_selection"],
            serde_json::json!({"external_level":1,"internal_level":0,"map_type_id":1})
        );
        assert_eq!(first.cue_id, loading.presentation.cue_id);
        let manifest: serde_json::Value = serde_json::from_slice(
            &fs::read(
                PathBuf::from(env!("CARGO_MANIFEST_DIR"))
                    .join("../../../generated/mc-bhq8-level1-collision-v5-night/manifest.json"),
            )
            .unwrap(),
        )
        .unwrap();
        assert_eq!(
            first.source_package_sha256,
            manifest["package_sha256"].as_str().unwrap()
        );
        assert_eq!(
            first.runtime_capture_sha256,
            manifest["files"]["runtime.bin"]["sha256"].as_str().unwrap()
        );
        assert_eq!(
            serde_json::to_value(&first).unwrap()["definition_revision"],
            first.definition_revision.to_string()
        );
        assert_eq!(runtime.identity(), loading);
        assert!(runtime.session().is_none());
        assert!(matches!(
            resolver.loading_presentation(&runtime, title.guard()),
            Err(RuntimeTransitionError::Guard(_))
        ));
        assert!(matches!(
            resolver.cancel_loading(&mut runtime, title.guard()),
            Err(RuntimeTransitionError::Guard(_))
        ));
        assert_eq!(runtime.identity(), loading);

        let entry = resolver.flow.entry_level_id().clone();
        let original = Arc::clone(&resolver.by_level[&entry].definition);
        resolver.by_level.get_mut(&entry).unwrap().definition =
            Arc::new(reissue_at_revision(&original, original.revision() + 1).unwrap());
        assert!(matches!(
            resolver.loading_presentation(&runtime, loading.guard()),
            Err(RuntimeTransitionError::InvalidRuntimeFlow { .. })
        ));
        assert_eq!(runtime.identity(), loading);
        resolver.by_level.get_mut(&entry).unwrap().definition = original;
        assert_eq!(
            resolver
                .loading_presentation(&runtime, loading.guard())
                .unwrap(),
            first
        );

        let title = resolver
            .cancel_loading(&mut runtime, loading.guard())
            .unwrap();
        assert_eq!(title.mode, RuntimeMode::Title);
        assert!(runtime.session().is_none());
        let retry = resolver.new_game(&mut runtime, title.guard()).unwrap();
        assert_eq!(
            resolver
                .loading_presentation(&runtime, retry.guard())
                .unwrap(),
            first
        );
        let playing = resolver
            .open_pending(&mut runtime, retry.guard(), 195)
            .unwrap();
        assert_eq!(playing.mode, RuntimeMode::Playing);
        let active = resolver
            .active_entry_presentation(&runtime, playing.guard())
            .unwrap();
        assert_eq!(active.level_id, first.level_id);
        assert_eq!(active.source_selection, first.source_selection);
        assert_eq!(active.package_graph_hash, first.package_graph_hash);
        assert_eq!(active.definition_hash, first.definition_hash);
        assert_eq!(active.environment, first.environment);
        assert_eq!(active.artwork_profile, first.artwork_profile);
        assert_eq!(active.cue_id, playing.presentation.cue_id);
        assert!(matches!(
            resolver.active_entry_presentation(&runtime, retry.guard()),
            Err(RuntimeTransitionError::Guard(_))
        ));
        let original = Arc::clone(&resolver.by_level[&entry].definition);
        resolver.by_level.get_mut(&entry).unwrap().definition =
            Arc::new(reissue_at_revision(&original, original.revision() + 1).unwrap());
        assert!(matches!(
            resolver.active_entry_presentation(&runtime, playing.guard()),
            Err(RuntimeTransitionError::InvalidRuntimeFlow { .. })
        ));
        assert_eq!(runtime.identity(), playing);
        resolver.by_level.get_mut(&entry).unwrap().definition = original;
        {
            let session = runtime.session_mut().unwrap();
            session.step(guard(session), GameCommand::default()).unwrap();
        }
        let advanced = runtime.identity();
        assert!(advanced.session.as_ref().unwrap().tick > 0);
        let paused = runtime.pause(advanced.guard()).unwrap();
        let before = resolver.save_replay(&runtime).unwrap();
        let paused_binding = resolver.active_entry_presentation(&runtime, paused.guard()).unwrap();
        assert_eq!(paused_binding, active);
        assert_eq!(runtime.identity(), paused);
        assert_eq!(resolver.save_replay(&runtime).unwrap(), before,
            "observing the paused active binding changes no replay or state");
        assert!(matches!(
            resolver.active_entry_presentation(&runtime, advanced.guard()),
            Err(RuntimeTransitionError::Guard(_))
        ));
        let original = Arc::clone(&resolver.by_level[&entry].definition);
        resolver.by_level.get_mut(&entry).unwrap().definition =
            Arc::new(reissue_at_revision(&original, original.revision() + 1).unwrap());
        assert!(matches!(
            resolver.active_entry_presentation(&runtime, paused.guard()),
            Err(RuntimeTransitionError::InvalidRuntimeFlow { .. })
        ));
        assert_eq!(runtime.identity(), paused);
        resolver.by_level.get_mut(&entry).unwrap().definition = original;
        assert_eq!(resolver.save_replay(&runtime).unwrap(), before);
    }

    #[test]
    fn actual_source_thirty_package_opens_with_its_canonical_secret_selection() {
        let package = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../generated/mc-paj2-source30-campaign-package");
        let definition =
            Arc::new(load_mc2_campaign(&package, &default_catalog().unwrap()).unwrap());
        let flow = definition.runtime_flow().unwrap();
        assert_eq!(
            flow.bound_level_id().as_str(),
            "level.magic_carpet_2.karakir"
        );
        assert_eq!(flow.secret_entries().len(), 1);
        assert_eq!(
            flow.secret_entries()[0].origin_level_id().as_str(),
            "level.magic_carpet_2.t_klom"
        );
        assert_eq!(
            CampaignDescriptor::declared_selection(&package).unwrap(),
            CampaignSelection::secret_destination(30).unwrap()
        );
        let mut session = GameSession::open(
            &Mc2CampaignAdapter,
            Arc::clone(&definition),
            7190,
            Mc2CampaignInputs::new(&package),
        )
        .unwrap();
        assert_eq!(
            session.definition().definition_hash(),
            definition.definition_hash()
        );
        let before = session.identity();
        session
            .step(before.guard(), GameCommand::default())
            .unwrap();
        assert!(session.identity().tick > before.tick);
        // Preserve the real secret package, default actor, and ordinary
        // scheduling. These menu commands do not grant a parent frontier,
        // portal entry, objective completion, or outer return frame.
        use sim_session::AbandonAction;
        let player = session.backend().campaign.simulation().state.entity_index;
        let local = session
            .backend()
            .campaign
            .simulation()
            .runtime()
            .local_player_slot;
        let player_handle = session
            .backend()
            .campaign
            .simulation()
            .source_arena()
            .handle(player)
            .unwrap();
        assert_eq!(
            session
                .backend()
                .campaign
                .simulation()
                .session
                .state
                .live
                .source_player_result
                .raw_word(),
            0
        );
        let mut confirm_guard = None;
        for (action, admitted, result_word) in [
            (AbandonAction::ConfirmAbandon, false, 0_u16),
            (AbandonAction::OpenAbandonConfirmation, true, 0),
            (AbandonAction::ConfirmAbandon, true, 0x0018),
        ] {
            let command_guard = session.identity().guard();
            if result_word == 0x0018 {
                confirm_guard = Some(command_guard);
            }
            let before_header = session
                .backend()
                .campaign
                .simulation()
                .session
                .state
                .live
                .source_player_result
                .raw_headers()[usize::from(local)];
            let observed = session
                .step(
                    command_guard,
                    GameCommand {
                        abandon_action: Some(action),
                        ..Default::default()
                    },
                )
                .unwrap();
            let menu = observed.value.source_menu_admission.unwrap();
            assert_eq!(
                (menu.action, menu.admitted, menu.tick),
                (action, admitted, observed.identity.tick)
            );
            assert!(!observed.value.return_to_title_requested);
            let sim = session.backend().campaign.simulation();
            let result = sim.session.state.live.source_player_result;
            assert_eq!(result.source_player_slot(), u16::from(local));
            assert_eq!(result.raw_word(), result_word);
            assert_eq!(
                result.raw_headers()[usize::from(local)] & 0xffff,
                before_header & 0xffff
            );
            assert_eq!(sim.secret_banishment_result(), result_word == 0x0018);
            assert!(!sim.ordinary_banishment_result());
            assert!(!result.is_secret_banishment_for(u16::from(local) + 1));
            assert_eq!(sim.source_arena().handle(player), Some(player_handle));
            assert_eq!(sim.runtime().player_inputs[usize::from(local)].opcode, 0);
            assert!(!sim.level_exit_sequence().complete);
            // Source PlayerEvents1D produces18; it is neither the normal
            // action12 exit10 nor the action11 entry/continuation26. The
            // separate portal carrier must not acquire a fabricated result.
            assert_eq!(sim.level_exit_sequence().result_code, 0);
        }
        let before_duplicate = session.snapshot();
        assert!(
            session
                .step(
                    confirm_guard.unwrap(),
                    GameCommand {
                        abandon_action: Some(AbandonAction::ConfirmAbandon),
                        ..Default::default()
                    }
                )
                .is_err()
        );
        assert_eq!(session.snapshot(), before_duplicate);
        let confirmed_word = session
            .backend()
            .campaign
            .simulation()
            .session
            .state
            .live
            .source_player_result
            .raw_word();
        // Reading the result never consumes it. The guarded outer secret-frame
        // owner performs that transfer; a stale request cannot publish it twice.
        for _ in 0..2 {
            assert!(
                session
                    .backend()
                    .campaign
                    .simulation()
                    .secret_banishment_result()
            );
        }
        let old_identity = session.identity();
        session.reset(old_identity.guard()).unwrap();
        assert!(session.identity().generation > old_identity.generation);
        assert_eq!(
            session
                .backend()
                .campaign
                .simulation()
                .session
                .state
                .live
                .source_player_result
                .raw_word(),
            0
        );
        assert!(
            !session
                .backend()
                .campaign
                .simulation()
                .secret_banishment_result()
        );
        let reset = session.snapshot();
        assert!(
            session
                .step(old_identity.guard(), GameCommand::default())
                .is_err()
        );
        assert_eq!(session.snapshot(), reset);
        eprintln!(
            "source30publicbanish: player={player_handle:?} sourceplayer={local} confirmed_raw={confirmed_word:#06x} stale-request=refused reset_raw=0 resetgeneration={}",
            session.identity().generation
        );
    }

    // The installed catalog and arriving parent frontier are declared inputs.
    // The mission completer must earn its last mana increment and use its real
    // exit; this helper cannot manufacture a completion or a portal entry.
    pub(crate) fn assert_actual_secret_completed_return(
        source: u16,
        complete: fn(&mut GameSession<Mc2CampaignBackend>) -> u8,
    ) {
        use crate::game_runtime::{
            CampaignMenuCommand, CampaignMenuPhase, CampaignSaveState, GameRuntime,
            RuntimeMode, RuntimeTransitionError, SecretTransitionKind,
        };
        use crate::world::portals::OrdinaryExitRoute;

        let generated = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../../generated");
        let resources = std::env::var_os("MC_SECRET_RETURN_RESOURCES")
            .map(PathBuf::from).unwrap_or_else(|| generated.join(
                "campaign-original-environments/installed-campaign-resources.json"));
        // This ignored owner-local input is extracted from the normal
        // launcher's actual resource table, not a second campaign definition.
        let resources: Vec<BTreeMap<String, String>> = serde_json::from_slice(
            &std::fs::read(resources).expect("normal installed campaign resources"),
        ).unwrap();
        assert_eq!(resources.len(), 30);
        let resolver = Mc2RuntimePackageResolver::load(resources.iter().map(|row|
            Mc2CampaignInputs::with_owner_cache(&row["package"], &row["owner"]),
        )).unwrap();
        let destination = resolver.by_level.values().find(|package|
            package.selection == CampaignSelection::secret_destination(source).unwrap(),
        ).unwrap();
        let secret_level = destination.definition.runtime_flow().unwrap().bound_level_id().clone();
        let entry = resolver.flow().secret_entry(&secret_level).unwrap();
        let origin = entry.origin_level_id().clone();
        let origin_index = resolver.flow().entries().iter()
            .position(|entry| entry.level_id() == &origin).unwrap();
        let completed_levels = resolver.flow().entries().iter().take(origin_index)
            .map(|entry| entry.level_id().clone()).collect::<Vec<_>>();
        let parent = CampaignSaveState {
            definition: resolver.package(resolver.flow().entry_level_id()).unwrap()
                .definition.as_ref().clone(),
            phase: CampaignMenuPhase::MissionSelect,
            completed_level_id: None,
            selected_level_id: Some(origin.clone()),
            completed_levels,
            level_statistics: Vec::new(),
        };
        let mut runtime = GameRuntime::<Mc2CampaignBackend>::title(8200 + u64::from(source)).unwrap();
        let map = runtime.restore_campaign_resolved(
            runtime.identity().guard(), parent.clone(), Default::default(),
            |definition, selected| {
                resolver.exact_package_for_definition(definition)?;
                resolver.package(selected).map(|package| Arc::clone(&package.definition))
                    .ok_or_else(|| RuntimeTransitionError::InvalidRuntimeFlow {
                        message: "retained parent must be installed".to_owned(),
                    })
            },
        ).unwrap();
        let loading = resolver.campaign_menu_command(
            &mut runtime, map.guard(), CampaignMenuCommand::StartMission,
        ).unwrap();
        let playing = resolver.open_pending(
            &mut runtime, loading.guard(), 8200 + u64::from(source),
        ).unwrap();
        // Explicit arriving inventory fixture; no objective, HP, timer or
        // result is supplied. The exact resulting carry crosses the real seam.
        runtime.session_mut().unwrap().backend_mut().campaign.simulation_mut()
            .apply_carried_spell_families(&[1], Some(1)).unwrap();
        let inherited = runtime.session().unwrap().backend().transition_spell_carry().unwrap();
        let entered = runtime.enter_secret_resolved(
            playing.guard(), runtime.session().unwrap().identity().guard(), |parent_session| {
                let generation = parent_session.identity().generation.checked_add(1)
                    .and_then(std::num::NonZeroU64::new)
                    .ok_or(RuntimeTransitionError::GenerationExhausted)?;
                let mut secret = GameSession::open_with_generation(
                    &Mc2CampaignAdapter, Arc::clone(&destination.definition),
                    parent_session.identity().session_id, generation, destination.inputs.clone(),
                ).map_err(|error| RuntimeTransitionError::InvalidNextDefinition {
                    message: error.to_string(),
                })?;
                secret.backend_mut().apply_semantic_spell_carry(&inherited)?;
                secret.backend_mut().install_initial_source_context(
                    parent_session.backend().campaign.source_global_context(),
                )?;
                secret.backend_mut().install_initial_mission_rewards(
                    parent_session.backend().campaign.simulation().mission_rewards(),
                )?;
                secret.backend_mut().install_initial_exit_route(
                    OrdinaryExitRoute::SecretReturnFromParentContinuation,
                )?;
                Ok((secret_level.clone(), secret))
            },
        ).unwrap();
        assert!(entered.verify());
        assert_eq!(entered.kind, SecretTransitionKind::Entry);
        assert_eq!(runtime.session().unwrap().backend().initial_semantic_spell_carry().unwrap(), inherited);
        assert!(resolver.advance_secret_if_ready(
            &mut runtime, entered.after.guard(), entered.after.session.as_ref().unwrap().guard(),
        ).unwrap().is_none(), "source return bit alone must not complete the mission");

        assert_eq!(complete(runtime.session_mut().unwrap()), 0x1a);
        let session = runtime.session().unwrap();
        let GameCompletionStatus::Completed { completion } = session.backend().completion_status()
            else { panic!("the real secret exit must publish completion") };
        let statistics = completion.statistics.unwrap();
        let carry = session.backend().transition_spell_carry().unwrap();
        let session_guard = session.identity().guard();
        let outer_guard = runtime.identity().guard();
        let returned = resolver.advance_secret_if_ready(
            &mut runtime, outer_guard, session_guard,
        ).unwrap().expect("actual secret1A must reach its retained-parent consumer");
        assert!(returned.verify());
        assert_eq!(returned.kind, SecretTransitionKind::CompletedReturn);
        assert_eq!(returned.origin_level_id, origin);
        assert_eq!(returned.after.mode, RuntimeMode::Campaign);
        assert!(runtime.session().is_none());
        let mut expected_parent = parent;
        expected_parent.completed_levels.push(origin.clone());
        assert_eq!(runtime.campaign_save_state().unwrap(), expected_parent);
        assert_eq!(runtime.secret_flow_state().completed_secret_levels(), std::slice::from_ref(&secret_level));
        let results = runtime.secret_flow_state().completed_secret_statistics();
        assert_eq!(results.len(), 1);
        assert_eq!(results[0].level_id, secret_level);
        assert_eq!(results[0].statistics, statistics);
        assert!(runtime.secret_flow_state().return_frame().is_none());
        assert!(!runtime.campaign_return_active());

        // A cold map-save restore must retain the real mission's resulting
        // progression and pending parent carry, not the entry fixture's carry.
        let bytes = resolver.save_replay(&runtime).unwrap();
        let mut cold = GameRuntime::<Mc2CampaignBackend>::title(9200 + u64::from(source)).unwrap();
        let guard = cold.identity().guard();
        let restored = resolver.load_replay(&mut cold, guard, 9200 + u64::from(source), &bytes).unwrap();
        assert_eq!(resolver.save_replay(&cold).unwrap(), bytes);
        assert_eq!(cold.secret_flow_state().completed_secret_statistics(), results);
        let loading = resolver.campaign_menu_command(
            &mut cold, restored.guard(), CampaignMenuCommand::StartMission,
        ).unwrap();
        resolver.open_pending(&mut cold, loading.guard(), 9200 + u64::from(source)).unwrap();
        assert_eq!(cold.session().unwrap().definition().runtime_flow().unwrap().bound_level_id(), &origin);
        assert_eq!(cold.session().unwrap().backend().initial_semantic_spell_carry().unwrap(), carry);
        assert_eq!(cold.session().unwrap().backend().semantic_spell_carry().unwrap(), carry);
        assert_eq!(cold.session().unwrap().backend().campaign.simulation()
            .level_exit_sequence().ordinary_exit_route, OrdinaryExitRoute::CampaignMap);
        if source == 34 {
            // The real returned carry rematerializes Ammyridia before its
            // first frame. The ordinary renderer and feedback must still use
            // the exact installed parent catalog, including after replay/reset.
            let owner = resolver.package(&origin).unwrap().inputs.owner_cache.as_ref().unwrap();
            let assets = crate::day_indexed_frame::DayIndexedFrameAssets::load(owner).unwrap();
            let catalog = assets.source_animation_catalog().expect("qualified parent TMAP catalog");
            let session = cold.session().unwrap();
            let generation = session.identity().generation;
            let campaign = &session.backend().campaign;
            campaign.simulation().validate_source_animation_catalog(Some(catalog)).unwrap();
            assert!(campaign.simulation().validate_source_animation_catalog(None).is_err());
            let initial_animations = campaign.simulation().source_animations.clone();
            let frame = crate::day_indexed_frame::render_level2_day_indexed_frame(
                campaign.inspection(), campaign.simulation(), &assets, generation).unwrap();
            let before = resolver.save_replay(&cold).unwrap();
            assert!(cold.session_mut().unwrap().backend_mut()
                .acknowledge_primary_sprite_frame(&frame, generation.wrapping_add(1)).is_err());
            assert_eq!(resolver.save_replay(&cold).unwrap(), before, "stale frame is atomic");
            cold.acknowledge_primary_sprite_frame(&frame).unwrap();
            let observed = cold.session().unwrap().backend().snapshot();
            let animations = cold.session().unwrap().backend().campaign.simulation().source_animations.clone();
            let played = resolver.save_replay(&cold).unwrap();
            let mut replay = GameRuntime::<Mc2CampaignBackend>::title(10_234).unwrap();
            let guard = replay.identity().guard();
            resolver.load_replay(&mut replay, guard, 10_234, &played).unwrap();
            let restored = replay.session().unwrap().backend();
            assert_eq!(restored.snapshot(), observed);
            assert_eq!(restored.campaign.simulation().source_animations, animations);
            assert_eq!(restored.initial_semantic_spell_carry().unwrap(), carry);
            let restored = replay.session_mut().unwrap().backend_mut();
            restored.campaign.simulation_mut().reset();
            assert_eq!(restored.campaign.simulation().source_animations, initial_animations);
            restored.campaign.simulation().validate_source_animation_catalog(Some(catalog)).unwrap();
        }
        write_controlled_campaign_save("MC_COMPLETED_SECRET_SAVE_OUTPUT", &bytes);
    }

    #[test]
    fn actual_ymbul_completion_returns_to_its_parent_with_carry() {
        assert_actual_secret_completed_return(31, crate::native_world::tests::complete_ymbul_source31_for_test);
    }

    #[test]
    fn actual_pav_completion_returns_to_its_parent_with_carry() {
        assert_actual_secret_completed_return(32, crate::native_world::tests::complete_pav_source32_for_test);
    }

    #[test]
    fn actual_ommosyth_completion_returns_to_its_parent_with_carry() {
        assert_actual_secret_completed_return(34, crate::native_world::tests::complete_ommosyth_source34_for_test);
    }

    #[test]
    fn abandoned_secret_return_preserves_parent_and_entry_carry() {
        use crate::game_runtime::{
            CampaignMenuCommand, CampaignMenuPhase, CampaignSaveState, GameRuntime, RuntimeMode,
            RuntimeTransitionError, SecretTransitionKind,
        };
        use crate::game_session::GameCompletionStatistics;
        use crate::world::portals::OrdinaryExitRoute;

        // This boundary fixture supplies a retained Level-5 frontier and enters
        // its installed secret through the existing runtime boundary. Inventory
        // and XP use the genuine Level 1 package and award primitive; this does
        // not claim a played Level 1-4 frontier or source portal gameplay.
        let generated = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../../generated");
        let resolver = Mc2RuntimePackageResolver::load(
            [
                "mc-bhq8-level1-collision-v5-night",
                "level2-day-block32-campaign-v2",
                "level3-day-block32-campaign-recipe-v2",
                "mc-bhq6-ordinary-20261025-zclu5fjj/level4",
                "dragon-bee-20261105-integration/level5-owner-current/level5",
                "mc-paj2-source30-campaign-package",
            ]
            .map(|path| Mc2CampaignInputs::new(generated.join(path))),
        )
        .unwrap();
        let level1_root = generated.join("mc-bhq8-level1-collision-v5-night");
        let level1_package = resolver
            .package(resolver.flow().entry_level_id())
            .expect("resolver retains the genuine Level 1 package");
        let mut level1_session = GameSession::open(
            &Mc2CampaignAdapter,
            Arc::clone(&level1_package.definition),
            7434,
            Mc2CampaignInputs::new(level1_root),
        )
        .unwrap();
        let initial_inventory = level1_session.backend().semantic_spell_carry().unwrap();
        assert_eq!(
            initial_inventory.acquired,
            vec![SpellKind::Fireball, SpellKind::Possession]
        );
        let fireball_family = mc2_spell_family(SpellKind::Fireball).unwrap();
        let level1_player = level1_session
            .backend()
            .campaign
            .simulation()
            .shared_spells()
            .local_player()
            .entity_index;
        level1_session
            .backend_mut()
            .campaign
            .simulation_mut()
            .shared_spells_mut()
            .award_spell_experience(level1_player, fireball_family, 1);
        let inherited_carry = level1_session.backend().transition_spell_carry().unwrap();
        assert_eq!(inherited_carry.acquired, initial_inventory.acquired);
        assert_eq!(inherited_carry.selected, initial_inventory.selected);
        let inherited_fireball = inherited_carry
            .progression
            .iter()
            .find(|progress| progress.spell == SpellKind::Fireball)
            .expect("the source award adds Fireball to the genuine Level 1 carry");
        assert!(inherited_fireball.persistent_experience > 0);
        assert_eq!(inherited_fireball.runtime_experience, 0);
        let secret_entry = resolver.flow().secret_entries().first().unwrap();
        let origin = secret_entry.origin_level_id().clone();
        let secret_level = secret_entry.secret_level_id().clone();
        let origin_index = resolver
            .flow()
            .entries()
            .iter()
            .position(|entry| entry.level_id() == &origin)
            .unwrap();
        assert_eq!(origin_index, 4);
        let completed_levels = resolver
            .flow()
            .entries()
            .iter()
            .take(origin_index)
            .map(|entry| entry.level_id().clone())
            .collect::<Vec<_>>();
        let level_statistics = completed_levels
            .iter()
            .map(|level_id| crate::game_runtime::CompletedLevelStatistics {
                level_id: level_id.clone(),
                statistics: GameCompletionStatistics {
                    spells_found_percent: 15,
                    hit_accuracy_percent: 25,
                    creatures_killed_percent: 35,
                    mana_collected_percent: 45,
                    time_taken_seconds: 123,
                },
            })
            .collect::<Vec<_>>();
        let entry_definition = Arc::clone(
            &resolver
                .package(resolver.flow().entry_level_id())
                .unwrap()
                .definition,
        );
        let parent_save = CampaignSaveState {
            definition: entry_definition.as_ref().clone(),
            phase: CampaignMenuPhase::MissionSelect,
            completed_level_id: None,
            selected_level_id: Some(origin.clone()),
            completed_levels: completed_levels.clone(),
            level_statistics: level_statistics.clone(),
        };
        let mut runtime = GameRuntime::<Mc2CampaignBackend>::title(7433).unwrap();
        install_owner_return_media(&mut runtime);
        let title = runtime.identity();
        let map = runtime
            .restore_campaign_resolved(
                title.guard(),
                parent_save,
                Default::default(),
                |definition, selected| {
                    resolver.exact_package_for_definition(definition)?;
                    resolver
                        .package(selected)
                        .map(|package| Arc::clone(&package.definition))
                        .ok_or_else(|| RuntimeTransitionError::InvalidRuntimeFlow {
                            message: "saved campaign selection is not installed".to_owned(),
                        })
                },
            )
            .unwrap();
        let loading = resolver
            .campaign_menu_command(&mut runtime, map.guard(), CampaignMenuCommand::StartMission)
            .unwrap();
        let playing = resolver
            .open_pending(&mut runtime, loading.guard(), 7433)
            .unwrap();
        let ordinary_session_guard = playing.session.as_ref().unwrap().guard();
        let ordinary_before = runtime.identity();
        assert!(
            resolver
                .abandon_secret_if_active(&mut runtime, playing.guard(), ordinary_session_guard)
                .unwrap()
                .is_none()
        );
        assert_eq!(runtime.identity(), ordinary_before);

        let stale_outer = crate::game_runtime::RuntimeGuard {
            runtime_id: playing.runtime_id,
            generation: playing.generation - 1,
        };
        assert!(matches!(
            resolver.abandon_secret_if_active(&mut runtime, stale_outer, ordinary_session_guard),
            Err(RuntimeTransitionError::Guard(_))
        ));
        let mut stale_session = ordinary_session_guard;
        stale_session.expected_tick += 1;
        assert!(matches!(
            resolver.abandon_secret_if_active(&mut runtime, playing.guard(), stale_session),
            Err(RuntimeTransitionError::SessionGuard(_))
        ));
        assert_eq!(runtime.identity(), ordinary_before);
        assert!(runtime.secret_flow_state().return_frame().is_none());

        runtime
            .session_mut()
            .unwrap()
            .backend_mut()
            .apply_semantic_spell_carry(&inherited_carry)
            .unwrap();
        assert_eq!(
            runtime
                .session()
                .unwrap()
                .backend()
                .semantic_spell_carry()
                .unwrap(),
            inherited_carry
        );
        let retained_parent = runtime.retained_campaign().cloned().unwrap();
        assert_eq!(retained_parent.selected_level_id.as_ref(), Some(&origin));
        assert_eq!(retained_parent.completed_levels, completed_levels);
        assert_eq!(retained_parent.level_statistics, level_statistics);

        let prepare_fixture_secret =
            |parent_session: &GameSession<Mc2CampaignBackend>, exit_route| {
                resolver.exact_package_for_definition(parent_session.definition())?;
                let destination = resolver.package(&secret_level).ok_or_else(|| {
                    RuntimeTransitionError::InvalidRuntimeFlow {
                        message: "installed secret package is unavailable".to_owned(),
                    }
                })?;
                let generation = parent_session
                    .identity()
                    .generation
                    .checked_add(1)
                    .and_then(std::num::NonZeroU64::new)
                    .ok_or(RuntimeTransitionError::GenerationExhausted)?;
                let mut candidate = GameSession::open_with_generation(
                    &Mc2CampaignAdapter,
                    Arc::clone(&destination.definition),
                    parent_session.identity().session_id,
                    generation,
                    destination.inputs.clone(),
                )
                .map_err(|error| {
                    RuntimeTransitionError::InvalidNextDefinition {
                        message: error.to_string(),
                    }
                })?;
                let carry = parent_session.backend().transition_spell_carry()?;
                let context = parent_session.backend().campaign.source_global_context();
                candidate.backend_mut().apply_semantic_spell_carry(&carry)?;
                candidate
                    .backend_mut()
                    .install_initial_source_context(context)?;
                candidate.backend_mut().install_initial_mission_rewards(
                    parent_session.backend().campaign.simulation().mission_rewards(),
                )?;
                candidate
                    .backend_mut()
                    .install_initial_exit_route(exit_route)?;
                Ok((secret_level.clone(), candidate))
            };
        let parent_session_guard = runtime.session().unwrap().identity().guard();
        let secret_receipt = runtime
            .enter_secret_resolved(playing.guard(), parent_session_guard, |parent_session| {
                prepare_fixture_secret(parent_session, OrdinaryExitRoute::CampaignMap)
            })
            .unwrap();
        assert!(secret_receipt.verify());
        assert_eq!(secret_receipt.kind, SecretTransitionKind::Entry);

        let entry_carry = runtime
            .session()
            .unwrap()
            .backend()
            .initial_semantic_spell_carry()
            .unwrap();
        assert_eq!(entry_carry, inherited_carry);
        let source_context = runtime
            .session()
            .unwrap()
            .backend()
            .campaign
            .source_global_context();
        let entry_fireball = entry_carry
            .progression
            .iter()
            .find(|progress| progress.spell == SpellKind::Fireball)
            .expect("the genuine inherited carry retains its Fireball XP baseline");
        let secret_player = runtime
            .session()
            .unwrap()
            .backend()
            .campaign
            .simulation()
            .shared_spells()
            .local_player()
            .entity_index;
        runtime
            .session_mut()
            .unwrap()
            .backend_mut()
            .campaign
            .simulation_mut()
            .shared_spells_mut()
            .award_spell_experience(secret_player, fireball_family, 777);
        let mission_carry = runtime
            .session()
            .unwrap()
            .backend()
            .semantic_spell_carry()
            .unwrap();
        assert_eq!(mission_carry.acquired, entry_carry.acquired);
        let mission_fireball = mission_carry
            .progression
            .iter()
            .find(|progress| progress.spell == SpellKind::Fireball)
            .expect("the secret's source XP award updates the carried Fireball");
        assert_eq!(
            mission_fireball.persistent_experience,
            entry_fireball.persistent_experience
        );
        assert_eq!(
            mission_fireball.runtime_experience,
            entry_fireball.runtime_experience.checked_add(777).unwrap()
        );
        assert_ne!(mission_carry, entry_carry);

        let secret_playing = runtime.identity();
        let paused = runtime.pause(secret_playing.guard()).unwrap();
        assert_eq!(paused.mode, RuntimeMode::Paused);
        let paused_session_guard = paused.session.as_ref().unwrap().guard();
        let paused_hand_flash = runtime.session().unwrap().backend().campaign.simulation().hand_selection_flash_ticks();
        let paused_context = runtime
            .session()
            .unwrap()
            .backend()
            .campaign
            .source_global_context();
        let receipt = resolver
            .abandon_secret_if_active(&mut runtime, paused.guard(), paused_session_guard)
            .unwrap()
            .unwrap();
        assert!(receipt.verify());
        assert_eq!(receipt.kind, SecretTransitionKind::AbandonedReturn);
        assert_eq!(receipt.before.mode, RuntimeMode::Paused);
        assert_eq!(receipt.after.mode, RuntimeMode::Campaign);
        assert_eq!(receipt.origin_level_id, origin);
        assert_eq!(
            receipt
                .after
                .campaign_menu
                .as_ref()
                .unwrap()
                .selected_level_id
                .as_ref(),
            Some(&origin)
        );
        let mut activated_parent = retained_parent;
        if !activated_parent.completed_levels.contains(&origin) {
            activated_parent.completed_levels.push(origin.clone());
        }
        assert_eq!(runtime.campaign_save_state().unwrap(), activated_parent);
        let secret_progress = receipt.after.secret_campaign.as_ref().unwrap();
        assert!(secret_progress.discovered_levels.contains(&secret_level));
        assert!(!secret_progress.completed_levels.contains(&secret_level));

        let pending = resolver
            .pending_spell_carries
            .lock()
            .unwrap()
            .get(&paused.runtime_id)
            .cloned()
            .unwrap();
        assert_eq!(pending.destination_level, origin);
        assert_eq!(
            pending.session_generation,
            runtime.campaign_session_generation().unwrap()
        );
        assert_eq!(pending.carry, entry_carry);
        assert_eq!(
            resolver
                .detached_source_contexts
                .lock()
                .unwrap()
                .get(&paused.runtime_id),
            Some(&SourceProcessContext { shared: paused_context, hand_selection_flash_ticks: paused_hand_flash, source_speed_index: 0, source_player_names_visible: true })
        );
        assert_ne!(mission_carry, pending.carry);
        assert_eq!(source_context, paused_context);

        assert!(runtime.campaign_return_active(), "unseen parent queues CUT1");
        assert!(matches!(resolver.save_replay(&runtime), Err(Mc2CampaignReplaySaveError::InvalidMode)));
        play_owner_return_clip(&mut runtime, "cut1", 529, None);
        assert_eq!(runtime.played_cutscenes(), 1);
        let map_save = resolver.save_replay(&runtime).unwrap();

        let exit_route = |runtime: &GameRuntime<Mc2CampaignBackend>| {
            runtime
                .session()
                .unwrap()
                .backend()
                .campaign
                .simulation()
                .level_exit_sequence()
                .ordinary_exit_route
        };
        let selected_secret = resolver
            .campaign_menu_command(
                &mut runtime,
                receipt.after.guard(),
                CampaignMenuCommand::SelectMission {
                    level_id: secret_level.clone(),
                },
            )
            .unwrap();
        let loading = resolver
            .campaign_menu_command(
                &mut runtime,
                selected_secret.guard(),
                CampaignMenuCommand::StartMission,
            )
            .unwrap();
        let direct_revisit = resolver
            .open_pending(&mut runtime, loading.guard(), 7433)
            .unwrap();
        assert_eq!(exit_route(&runtime), OrdinaryExitRoute::CampaignMap);
        let direct_save: Mc2CampaignReplaySave =
            serde_json::from_slice(&resolver.save_replay(&runtime).unwrap()).unwrap();
        assert!(direct_save.initial_secret_continuation.is_none());
        let returned = resolver
            .abandon_secret_if_active(
                &mut runtime,
                direct_revisit.guard(),
                direct_revisit.session.as_ref().unwrap().guard(),
            )
            .unwrap()
            .unwrap();
        assert!(!runtime.campaign_return_active(), "revisit must not replay CUT1");
        assert_eq!(runtime.played_cutscenes(), 1);

        let mut cold_map = GameRuntime::<Mc2CampaignBackend>::title(7437).unwrap();
        install_owner_return_media(&mut cold_map);
        let guard = cold_map.identity().guard();
        let map = resolver.load_replay(&mut cold_map, guard, 7437, &map_save).unwrap();
        let selected = resolver.campaign_menu_command(&mut cold_map, map.guard(),
            CampaignMenuCommand::SelectMission { level_id: secret_level.clone() }).unwrap();
        let loading = resolver.campaign_menu_command(&mut cold_map, selected.guard(),
            CampaignMenuCommand::StartMission).unwrap();
        let playing = resolver.open_pending(&mut cold_map, loading.guard(), 7437).unwrap();
        assert_eq!(playing.session.as_ref().unwrap().tick, 0);
        let cold_return = complete_source_thirty_castle_and_exit(&resolver, &mut cold_map);
        assert_eq!(cold_return.kind, SecretTransitionKind::CompletedReturn);
        assert_eq!(cold_return.origin_level_id, origin);
        assert_eq!(cold_map.campaign_save_state().unwrap(), activated_parent);
        assert!(!cold_map.campaign_return_active(), "cold revisit must not replay CUT1");
        assert_eq!(cold_map.played_cutscenes(), 1);
        let secret_progress = cold_return.after.secret_campaign.as_ref().unwrap();
        assert_eq!(secret_progress.completed_levels, [secret_level.clone()]);

        let selected = resolver.campaign_menu_command(&mut cold_map, cold_return.after.guard(),
            CampaignMenuCommand::SelectMission { level_id: secret_level.clone() }).unwrap();
        let loading = resolver.campaign_menu_command(&mut cold_map, selected.guard(),
            CampaignMenuCommand::StartMission).unwrap();
        resolver.open_pending(&mut cold_map, loading.guard(), 7437).unwrap();
        let won = complete_source_thirty_castle_and_exit(&resolver, &mut cold_map);
        assert_eq!(won.kind, SecretTransitionKind::CompletedReturn);
        assert_eq!(won.origin_level_id, origin);
        assert_eq!(cold_map.campaign_save_state().unwrap(), activated_parent);
        assert_eq!(cold_map.secret_flow_state().completed_secret_levels(), std::slice::from_ref(&secret_level));
        assert_eq!(cold_map.secret_flow_state().completed_secret_statistics().len(), 1);
        assert!(!cold_map.campaign_return_active(), "successful revisit must not replay CUT1");
        assert_eq!(cold_map.played_cutscenes(), 1);

        let loading = resolver
            .campaign_menu_command(
                &mut runtime,
                returned.after.guard(),
                CampaignMenuCommand::StartMission,
            )
            .unwrap();
        let parent_replay = resolver
            .open_pending(&mut runtime, loading.guard(), 7433)
            .unwrap();
        assert_eq!(
            exit_route(&runtime),
            OrdinaryExitRoute::UnfinishedSecretContinuation
        );

        // Stage the immediate load at the existing retained-parent fixture
        // seam. This proves a genuine package's constructor/restore policy,
        // independently of earning either portal in the live world.
        runtime
            .enter_secret_resolved(
                parent_replay.guard(),
                parent_replay.session.as_ref().unwrap().guard(),
                |parent_session| {
                    prepare_fixture_secret(
                        parent_session,
                        OrdinaryExitRoute::SecretReturnFromParentContinuation,
                    )
                },
            )
            .unwrap();
        let bytes = resolver.save_replay(&runtime).unwrap();
        let mut saved: Mc2CampaignReplaySave = serde_json::from_slice(&bytes).unwrap();
        assert_eq!(saved.initial_secret_continuation.as_ref(), Some(secret_entry));
        assert_eq!(saved.played_cutscenes, Some(1));
        let mut restored = GameRuntime::<Mc2CampaignBackend>::title(7435).unwrap();
        let guard = restored.identity().guard();
        let resumed = resolver
            .load_replay(&mut restored, guard, 7435, &bytes)
            .unwrap();
        assert_eq!(
            exit_route(&restored),
            OrdinaryExitRoute::SecretReturnFromParentContinuation
        );
        assert_eq!(resolver.save_replay(&restored).unwrap(), bytes);
        assert_eq!(restored.played_cutscenes(), 1);
        assert!(
            resolver
                .advance_secret_if_ready(
                    &mut restored,
                    resumed.guard(),
                    resumed.session.as_ref().unwrap().guard(),
                )
                .unwrap()
                .is_none(),
            "inheriting the source bit does not complete the secret"
        );

        // The arriving parent/frontier remains the declared boundary fixture
        // above. Win this actual resumed Karakir through its earned final mana
        // increment and source exit, rather than changing any completion flag.
        let parent_before_win = restored.secret_flow_state().return_frame()
            .expect("resumed secret retains its parent").parent_campaign().clone();
        let actual_result = crate::native_world::tests::complete_karakir_earned_mana_and_exit(
            restored.session_mut().unwrap(),
        );
        assert_eq!(actual_result, 0x1a, "the retained source return bit reaches the real exit");
        let completed_carry = restored.session().unwrap().backend().transition_spell_carry().unwrap();
        let completed_guard = restored.session().unwrap().identity().guard();
        let outer_guard = restored.identity().guard();
        let won = resolver.advance_secret_if_ready(&mut restored, outer_guard, completed_guard)
            .unwrap().expect("actual source1A completion returns to its retained parent");
        assert!(won.verify());
        assert_eq!(won.kind, SecretTransitionKind::CompletedReturn);
        assert_eq!(won.origin_level_id, origin);
        assert_eq!(won.after.mode, RuntimeMode::Campaign);
        assert!(restored.session().is_none(), "the completed secret releases its live session");
        let returned_parent = restored.campaign_save_state().unwrap();
        assert_eq!(returned_parent.selected_level_id, parent_before_win.selected_level_id);
        assert_eq!(returned_parent.completed_levels, parent_before_win.completed_levels);
        assert_eq!(returned_parent.level_statistics, parent_before_win.level_statistics);
        assert_eq!(restored.secret_flow_state().completed_secret_levels(), std::slice::from_ref(&secret_level));
        assert_eq!(restored.secret_flow_state().completed_secret_statistics().len(), 1);
        assert!(restored.secret_flow_state().return_frame().is_none());
        assert_eq!(restored.played_cutscenes(), 1);
        assert!(!restored.campaign_return_active(), "source30 revisit does not replay CUT1");

        // Consume the successful secret's carry through the ordinary parent
        // loader, retaining the already-played cutscene and cleared source bit.
        let loading = resolver.campaign_menu_command(
            &mut restored, won.after.guard(), CampaignMenuCommand::StartMission,
        ).unwrap();
        resolver.open_pending(&mut restored, loading.guard(), 7435).unwrap();
        assert_eq!(exit_route(&restored), OrdinaryExitRoute::CampaignMap);
        assert_eq!(restored.session().unwrap().backend().initial_semantic_spell_carry().unwrap(), completed_carry);
        assert_eq!(restored.session().unwrap().backend().semantic_spell_carry().unwrap(), completed_carry);

        saved.initial_secret_continuation = None;
        saved.receipt_sha256 = saved.compute_receipt_sha256();
        let mut rejected = GameRuntime::<Mc2CampaignBackend>::title(7436).unwrap();
        let before = rejected.identity();
        assert!(matches!(
            resolver.load_replay(
                &mut rejected,
                before.guard(),
                7436,
                &serde_json::to_vec(&saved).unwrap(),
            ),
            Err(Mc2CampaignReplaySaveError::Restore(_))
        ));
        assert_eq!(rejected.identity(), before);
    }

    fn complete_source_thirty_castle_and_exit(
        resolver: &Mc2RuntimePackageResolver,
        runtime: &mut crate::game_runtime::GameRuntime<Mc2CampaignBackend>,
    ) -> crate::game_runtime::SecretTransitionReceipt {
        use crate::native_world::Mc2DispatchEvent;

        let session = runtime.session_mut().unwrap();
        assert!(matches!(session.backend().completion_status(), GameCompletionStatus::InProgress));
        let sim = session.backend_mut().campaign.simulation_mut();
        let player = sim.state.entity_index;
        assert_eq!(sim.runtime().stages[0].relation, crate::native_world::RuntimeRelation::Scalar(85));
        for (stage, footprint) in crate::native_world::campaign_castle_stage_footprints().unwrap() {
            sim.economy_mut().set_castle_stage_footprint(stage, footprint);
        }
        let site = (1_u16..32).flat_map(|y| (1_u16..32).map(move |x|
            crate::Position { x: x * 2048, y: y * 2048, z: 0 }))
            .find(|position| sim.castle_projectile_site_admitted_for_test(*position))
            .expect("valid Castle site in Karakir");
        let castle = sim.economy_mut().build_castle(site, player).unwrap();
        // Supply the Castle stock as a declared upstream prerequisite. The
        // unmodified objective, group publisher and exit own the win itself.
        let total = sim.economy().owner_mana_global();
        assert!(total > 0);
        // The next source mana scan includes the Castle stock in the global
        // denominator too. Solve 100 * (owned + stock) >= 85 * (total + stock).
        let owned = sim.economy().owner_mana_aggregate(player);
        let required = (85 * i64::from(total) - 100 * i64::from(owned)).max(0);
        let stock = i32::try_from((required + 14) / 15).unwrap();
        assert!(sim.economy_mut().set_castle_mana_prerequisite_for_test(castle, stock));

        let mut exit = None;
        for _ in 0..32 {
            session.step(guard(session), GameCommand::default()).unwrap();
            let sim = session.backend().campaign.simulation();
            assert!(!sim.dispatch_events().iter().any(|event| matches!(event, Mc2DispatchEvent::Error { .. })));
            exit = sim.economy().authored_switch_producers().iter()
                .find(|row| row.active && row.authored_index == 65 && row.model == 12)
                .map(|row| row.position);
            if exit.is_some() { break; }
        }
        let exit = exit.unwrap_or_else(|| {
            let sim = session.backend().campaign.simulation();
            panic!("Karakir exit row 65 absent: objective={:?}, total={}, owned={}, stock={:?}",
                sim.runtime().objectives[0], sim.economy().owner_mana_global(),
                sim.economy().owner_mana_aggregate(player), sim.economy().castle().map(|row| row.mana));
        });
        let sim = session.backend_mut().campaign.simulation_mut();
        assert_eq!(sim.runtime().objectives[0].stage_selectors[0], 2);
        assert!(sim.economy().authored_class14().iter()
            .any(|row| row.active && row.authored_index == 64 && row.model == 3));
        sim.set_level2_entity_position(player, exit).unwrap();
        for _ in 0..700 {
            if matches!(session.backend().completion_status(), GameCompletionStatus::Completed { .. }) {
                break;
            }
            session.step(guard(session), GameCommand::default()).unwrap();
            assert!(!session.backend().campaign.simulation().dispatch_events().iter()
                .any(|event| matches!(event, Mc2DispatchEvent::Error { .. })));
        }
        assert!(matches!(session.backend().completion_status(), GameCompletionStatus::Completed { .. }));
        assert_eq!(session.backend().campaign.simulation().source_exit_result_byte(), 0x0a);
        let session_guard = session.identity().guard();
        let runtime_guard = runtime.identity().guard();
        resolver.advance_secret_if_ready(runtime, runtime_guard, session_guard).unwrap().unwrap()
    }

    #[test]
    fn dynamic_light_constructor_option_and_live_changes_survive_replay_and_reset() {
        use crate::game_runtime::{GameRuntime, preferences::PreferencesCommand};

        let night=std::env::var_os("MC_FLIGHT_ASSISTANCE_PACKAGE").map(PathBuf::from).unwrap_or_else(||
            PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../../generated/mc-bhq8-level1-collision-v5-night"));
        let resolver = Mc2RuntimePackageResolver::load([
            Mc2CampaignInputs::new(&night),
            Mc2CampaignInputs::new(descriptor_fixture_path()),
            Mc2CampaignInputs::new(level_three_descriptor_fixture_path()),
        ])
        .unwrap();
        let profile = std::env::temp_dir().join(format!(
            "mc-dynamic-light-replay-{}-{}",
            std::process::id(),
            SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap()
                .as_nanos(),
        ));
        let mut runtime = GameRuntime::<Mc2CampaignBackend>::title(7130).unwrap();
        runtime
            .preferences_command(
                runtime.identity().guard(),
                PreferencesCommand::Install {
                    profile_dir: profile.to_string_lossy().into_owned(),
                },
            )
            .unwrap();
        runtime.preferences_command(runtime.identity().guard(),PreferencesCommand::Apply {
            preferences:runtime.identity().player_preferences.preferences }).unwrap();
        // Declared incoming GAME option, preserving this constructor-input
        // check. The connected graphics test exercises the real source action.
        runtime.restore_display_settings(crate::game_runtime::DisplaySettings {
            dynamic_lighting:false,..runtime.identity().display_settings });
        let title_guard = runtime.identity().guard();
        let loading = resolver.new_game(&mut runtime, title_guard).unwrap();
        resolver
            .open_pending(&mut runtime, loading.guard(), 7130)
            .unwrap();
        let definition = Arc::clone(runtime.session().unwrap().definition());
        let cast = GameCommand {
            cast_left: true,
            ..GameCommand::default()
        };
        {
            let session = runtime.session_mut().unwrap();
            assert!(!session.backend().dynamic_lighting_enabled());
            session
                .step(session.identity().guard(), cast.clone())
                .unwrap();
            assert!(
                player_spell_projectile_count(session) > 0,
                "disabled lighting must retain the real ordinary Fireball producer"
            );
            assert_eq!(
                session
                    .backend()
                    .campaign
                    .simulation()
                    .source_arena()
                    .dynamic_lighting
                    .active_count(),
                0
            );
            session.backend_mut().set_dynamic_lighting_enabled(true);
            session
                .step(session.identity().guard(), GameCommand::default())
                .unwrap();
            session.backend_mut().set_dynamic_lighting_enabled(false);
            session.backend_mut().set_dynamic_lighting_enabled(true);
            let checkpoint = session.backend().dynamic_lighting_change_count();
            session.backend_mut().set_dynamic_lighting_enabled(false);
            session
                .backend_mut()
                .restore_dynamic_lighting_after_rejection(true, checkpoint);
            assert_eq!(
                session.backend().dynamic_lighting_change_count(),
                checkpoint
            );
        }
        let mut enabled = GameSession::open(
            &Mc2CampaignAdapter,
            definition,
            7131,
            Mc2CampaignInputs::new(&night),
        )
        .unwrap();
        enabled.step(enabled.identity().guard(), cast).unwrap();
        assert!(player_spell_projectile_count(&enabled) > 0);
        assert!(
            enabled
                .backend()
                .campaign
                .simulation()
                .source_arena()
                .dynamic_lighting
                .active_count()
                > 0,
            "the same ordinary Fireball constructor must admit a real light when enabled"
        );

        let paused = runtime.pause(runtime.identity().guard()).unwrap();
        // The guarded GAME action now aligns the retained flag with the
        // actual native policy changes exercised above, without CONFIG.
        runtime.source_graphics(runtime.identity().guard(),runtime.session().unwrap().identity().guard(),
            crate::game_runtime::SourceGraphicsAction::DynamicLighting).unwrap();
        let session_guard = runtime.session().unwrap().identity().guard();
        runtime
            .paused_campaign_frame_timed(paused.guard(), session_guard, 13, false)
            .unwrap();
        let bytes = resolver.save_replay(&runtime).unwrap();
        let saved: Mc2CampaignReplaySave = serde_json::from_slice(&bytes).unwrap();
        assert!(!saved.initial_dynamic_lighting);
        assert_eq!(
            saved.dynamic_lighting_changes,
            vec![
                Mc2DynamicLightingChange {
                    before_operation: 1,
                    enabled: true
                },
                Mc2DynamicLightingChange {
                    before_operation: 2,
                    enabled: false
                },
                Mc2DynamicLightingChange {
                    before_operation: 2,
                    enabled: true
                },
            ]
        );
        let mut restored = GameRuntime::<Mc2CampaignBackend>::title(7132).unwrap();
        let restore_guard = restored.identity().guard();
        resolver
            .load_replay(&mut restored, restore_guard, 7132, &bytes)
            .unwrap();
        assert!(
            restored
                .session()
                .unwrap()
                .backend()
                .dynamic_lighting_enabled()
        );
        assert_eq!(
            resolver.save_replay(&restored).unwrap(),
            bytes,
            "ordinary cast, pause and policy boundaries must reproduce all saved receipts"
        );

        let mut corrupt = saved;
        corrupt.dynamic_lighting_changes[0].before_operation = corrupt.operations.len() + 1;
        corrupt.receipt_sha256 = corrupt.compute_receipt_sha256();
        let mut rejected = GameRuntime::<Mc2CampaignBackend>::title(7133).unwrap();
        let before = rejected.identity();
        assert!(matches!(
            resolver.load_replay(
                &mut rejected,
                before.guard(),
                7133,
                &serde_json::to_vec(&corrupt).unwrap()
            ),
            Err(Mc2CampaignReplaySaveError::InvalidSave { .. })
        ));
        assert_eq!(rejected.identity(), before);
        assert!(rejected.session().is_none());

        let resumed = restored.resume(restored.identity().guard()).unwrap();
        let session = restored.session_mut().unwrap();
        session.reset(session.identity().guard()).unwrap();
        assert!(session.backend().dynamic_lighting_enabled());
        assert_eq!(
            session.backend().dynamic_lighting_changes,
            vec![Mc2DynamicLightingChange {
                before_operation: 0,
                enabled: true
            },]
        );
        assert_eq!(restored.identity().generation, resumed.generation);
        let reset_bytes = resolver.save_replay(&restored).unwrap();
        let mut reset_replay = GameRuntime::<Mc2CampaignBackend>::title(7134).unwrap();
        let reset_guard = reset_replay.identity().guard();
        resolver
            .load_replay(&mut reset_replay, reset_guard, 7134, &reset_bytes)
            .unwrap();
        assert_eq!(resolver.save_replay(&reset_replay).unwrap(), reset_bytes);

        std::fs::remove_file(profile.join("player-preferences.json")).unwrap();
        std::fs::remove_dir(profile).unwrap();
    }

    #[test]
    fn campaign_elapsed_clock_repair_replays_step_and_pause_without_tick_guessing() {
        use crate::game_runtime::GameRuntime;
        let resolver = Mc2RuntimePackageResolver::load([
            Mc2CampaignInputs::new(
                PathBuf::from(env!("CARGO_MANIFEST_DIR"))
                    .join("../../../generated/mc-bhq8-level1-collision-v5-night"),
            ),
            Mc2CampaignInputs::new(descriptor_fixture_path()),
            Mc2CampaignInputs::new(level_three_descriptor_fixture_path()),
        ])
        .unwrap();
        let mut runtime = GameRuntime::<Mc2CampaignBackend>::title(7120).unwrap();
        let guard = runtime.identity().guard();
        let loading = resolver.new_game(&mut runtime, guard).unwrap();
        resolver
            .open_pending(&mut runtime, loading.guard(), 7120)
            .unwrap();
        let session = runtime.session_mut().unwrap();
        session
            .step(
                session.identity().guard(),
                GameCommand {
                    elapsed_centiseconds: 123,
                    ..Default::default()
                },
            )
            .unwrap();
        let tick = runtime.session().unwrap().identity().tick;
        let source_turn = runtime
            .session()
            .unwrap()
            .backend()
            .campaign
            .simulation()
            .shared_spells()
            .local_player()
            .turn;
        let source_camera_pose = runtime
            .session()
            .unwrap()
            .snapshot()
            .value
            .source_camera_pose;
        let guard = runtime.identity().guard();
        let paused = runtime.pause(guard).unwrap();
        let session_guard = runtime.session().unwrap().identity().guard();
        runtime
            .paused_campaign_frame_timed(paused.guard(), session_guard, 177, false)
            .unwrap();
        assert_eq!(runtime.session().unwrap().identity().tick, tick);
        assert_eq!(
            runtime
                .session()
                .unwrap()
                .backend()
                .campaign
                .simulation()
                .shared_spells()
                .local_player()
                .turn,
            source_turn.wrapping_add(1)
        );
        assert_eq!(
            runtime
                .session()
                .unwrap()
                .snapshot()
                .value
                .source_camera_pose,
            source_camera_pose,
            "paused PlayerEvents must preserve the captured source view"
        );
        assert_eq!(
            runtime
                .session()
                .unwrap()
                .backend()
                .campaign
                .simulation()
                .completion_statistics()
                .time_taken_seconds,
            3
        );
        let bytes = resolver.save_replay(&runtime).unwrap();
        let mut forged: Mc2CampaignReplaySave = serde_json::from_slice(&bytes).unwrap();
        assert!(forged.initial_mission_rewards.is_none());
        assert_eq!(
            runtime
                .session()
                .unwrap()
                .backend()
                .campaign
                .simulation()
                .mission_rewards(),
            crate::campaign::rewards::MissionRewards::Enabled
        );
        let mut forged_rewards = forged.clone();
        forged_rewards.initial_mission_rewards =
            Some(crate::campaign::rewards::MissionRewards::Suppressed);
        forged_rewards.receipt_sha256 = forged_rewards.compute_receipt_sha256();
        let mut rejected_rewards = GameRuntime::<Mc2CampaignBackend>::title(7126).unwrap();
        let before_rewards = rejected_rewards.identity();
        assert!(matches!(
            resolver.load_replay(
                &mut rejected_rewards,
                before_rewards.guard(),
                7126,
                &serde_json::to_vec(&forged_rewards).unwrap(),
            ),
            Err(Mc2CampaignReplaySaveError::InvalidSave { .. })
        ));
        assert_eq!(rejected_rewards.identity(), before_rewards);
        assert!(forged.initial_secret_continuation.is_none());
        assert!(
            serde_json::from_slice::<serde_json::Value>(&bytes)
                .unwrap()
                .get("initial_secret_continuation")
                .is_none()
        );
        let origin = forged
            .definition
            .runtime_flow()
            .unwrap()
            .bound_level_id()
            .clone();
        forged.initial_secret_continuation =
            Some(sim_definition::runtime_flow::RuntimeFlowSecretEntry::new(
                origin,
                SemanticLevelId::parse("level.magic_carpet_2.unavailable_secret").unwrap(),
            ));
        forged.receipt_sha256 = forged.compute_receipt_sha256();
        let forged_bytes = serde_json::to_vec(&forged).unwrap();
        let mut rejected = GameRuntime::<Mc2CampaignBackend>::title(7125).unwrap();
        let before = rejected.identity();
        assert!(matches!(
            resolver.load_replay(&mut rejected, before.guard(), 7125, &forged_bytes),
            Err(Mc2CampaignReplaySaveError::InvalidSave { .. })
        ));
        assert_eq!(rejected.identity(), before);
        assert!(rejected.session().is_none());
        let mut restored = GameRuntime::<Mc2CampaignBackend>::title(7121).unwrap();
        let guard = restored.identity().guard();
        resolver
            .load_replay(&mut restored, guard, 7121, &bytes)
            .unwrap();
        assert_eq!(
            restored.session().unwrap().snapshot().value,
            runtime.session().unwrap().snapshot().value
        );
        assert_eq!(
            restored
                .session()
                .unwrap()
                .backend()
                .campaign
                .simulation()
                .completion_statistics()
                .time_taken_seconds,
            3
        );
        assert_eq!(resolver.save_replay(&restored).unwrap(), bytes);
        let warm_context = GlobalSpecialState {
            protection_ticks: 23,
            visibility_mode: 2,
            damage_flash_ticks: 0,
            ..GlobalSpecialState::default()
        };
        // Keep the envelope valid while making the replay's final state
        // receipt false, so this exercises candidate verification itself.
        let mut corrupt: Mc2CampaignReplaySave = serde_json::from_slice(&bytes).unwrap();
        corrupt.expected_state_hash ^= 1;
        corrupt.receipt_sha256 = corrupt.compute_receipt_sha256();
        let corrupt_bytes = serde_json::to_vec(&corrupt).unwrap();
        let mut rejected = GameRuntime::<Mc2CampaignBackend>::title(7124).unwrap();
        let before = rejected.identity();
        assert!(matches!(
            resolver.load_replay_with_source_context(
                &mut rejected,
                before.guard(),
                7124,
                &corrupt_bytes,
                SourceProcessContext { shared: warm_context, hand_selection_flash_ticks: [0; 2], source_speed_index: 0, source_player_names_visible: true },
            ),
            Err(Mc2CampaignReplaySaveError::Restore(
                crate::game_runtime::RestorePlayingError::Transition(
                    crate::game_runtime::RuntimeTransitionError::InvalidReplay { .. }
                )
            ))
        ));
        assert_eq!(rejected.identity(), before);
        assert!(rejected.session().is_none());
        let mut warm = GameRuntime::<Mc2CampaignBackend>::title(7122).unwrap();
        let guard = warm.identity().guard();
        let loaded = resolver
            .load_replay_with_source_context(&mut warm, guard, 7122, &bytes, SourceProcessContext { shared: warm_context, hand_selection_flash_ticks: [0; 2], source_speed_index: 0, source_player_names_visible: true })
            .unwrap();
        assert_eq!(loaded.mode, crate::game_runtime::RuntimeMode::Paused);
        assert!(
            warm.session_mut().is_none(),
            "warm restore must preserve the paused gameplay mutation gate"
        );
        assert_eq!(warm.session().unwrap().identity().tick, tick);
        assert_eq!(
            warm.session()
                .unwrap()
                .backend()
                .campaign
                .source_global_context(),
            warm_context
        );
        let warm_bytes = resolver.save_replay(&warm).unwrap();
        let mut roundtrip = GameRuntime::<Mc2CampaignBackend>::title(7123).unwrap();
        let guard = roundtrip.identity().guard();
        resolver
            .load_replay(&mut roundtrip, guard, 7123, &warm_bytes)
            .unwrap();
        assert_eq!(
            roundtrip.identity().mode,
            crate::game_runtime::RuntimeMode::Paused
        );
        assert_eq!(
            roundtrip.session().unwrap().snapshot().value,
            warm.session().unwrap().snapshot().value
        );
        assert_eq!(resolver.save_replay(&roundtrip).unwrap(), warm_bytes);
    }

    #[test]
    fn campaign_map_save_repair_roundtrips_frontier_carry_and_rejects_tampering() {
        use crate::game_runtime::{
            CampaignMenuCommand, CampaignMenuPhase, CampaignSaveState, GameRuntime, RuntimeMode,
        };
        let resolver = Mc2RuntimePackageResolver::load([
            Mc2CampaignInputs::new(level_one_descriptor_fixture_path()),
            Mc2CampaignInputs::new(descriptor_fixture_path()),
            Mc2CampaignInputs::new(level_three_descriptor_fixture_path()),
        ])
        .unwrap();
        let mut runtime = GameRuntime::<Mc2CampaignBackend>::title(7110).unwrap();
        let guard = runtime.identity().guard();
        let loading = resolver.new_game(&mut runtime, guard).unwrap();
        runtime.show_new_game_map(loading.guard()).unwrap();
        let new_map = resolver.save_replay(&runtime).unwrap();
        let mut restored = GameRuntime::<Mc2CampaignBackend>::title(7111).unwrap();
        let guard = restored.identity().guard();
        resolver
            .load_replay(&mut restored, guard, 7111, &new_map)
            .unwrap();
        assert_eq!(restored.identity().mode, RuntimeMode::Campaign);
        assert!(restored.session().is_none());
        assert_eq!(resolver.save_replay(&restored).unwrap(), new_map);

        // Isolated persistence-boundary fixture, not an earned completion.
        // The real retained carry is obtained from the ordinary package.
        let entry = resolver.flow.entry_level_id().clone();
        let destination = resolver.flow.entries()[1].level_id().clone();
        let mut playing = GameRuntime::<Mc2CampaignBackend>::title(7112).unwrap();
        let guard = playing.identity().guard();
        let loading = resolver.new_game(&mut playing, guard).unwrap();
        resolver
            .open_pending(&mut playing, loading.guard(), 7112)
            .unwrap();
        let carry = playing
            .session()
            .unwrap()
            .backend()
            .semantic_spell_carry()
            .unwrap();
        let state = CampaignSaveState {
            definition: resolver
                .package(&entry)
                .unwrap()
                .definition
                .as_ref()
                .clone(),
            phase: CampaignMenuPhase::Results,
            completed_level_id: Some(entry.clone()),
            selected_level_id: Some(destination.clone()),
            completed_levels: vec![entry],
            level_statistics: vec![],
        };
        let mut save = Mc2CampaignMapSave {
            save_contract: MC2_CAMPAIGN_MAP_SAVE_CONTRACT.to_owned(),
            state,
            semantic_spell_carry: Some(carry.clone()),
            carry_destination_level: Some(destination),
            secret_flow: None,
            source_context: None,
            source_hand_selection_flash_ticks: [0; 2],
            played_cutscenes: None,
            display_settings: crate::game_runtime::DisplaySettings::default().into(),
            receipt_sha256: String::new(),
            source_secret_announcement_count: 0,
        };
        save.receipt_sha256 = save.compute_receipt_sha256();
        let bytes = serde_json::to_vec(&save).unwrap();
        let mut restored = GameRuntime::<Mc2CampaignBackend>::title(7113).unwrap();
        let guard = restored.identity().guard();
        let mut tampered = serde_json::to_value(&save).unwrap();
        tampered["state"]["completed_levels"] = serde_json::json!([]);
        assert!(
            resolver
                .load_replay(
                    &mut restored,
                    guard,
                    7113,
                    &serde_json::to_vec(&tampered).unwrap()
                )
                .is_err()
        );
        assert_eq!(restored.identity().mode, RuntimeMode::Title);
        // A valid envelope digest must not publish a carry that the next
        // destination is guaranteed to reject. Preserve the receiving owner
        // and its retained save across each malformed structural packet.
        let before_identity = restored.identity();
        let before_save = resolver.save_replay(&restored).unwrap();
        let first_spell = *carry.acquired.first().expect("actual entry has a learned spell");
        let mut duplicate_family: Mc2CampaignMapSave = serde_json::from_slice(&bytes).unwrap();
        duplicate_family.semantic_spell_carry.as_mut().unwrap().acquired.push(first_spell);
        let missing_spell = (0..26_u8).filter_map(mc2_spell_kind_for_family)
            .find(|spell| !carry.acquired.contains(spell))
            .expect("entry leaves at least one source family unlearned");
        let mut invalid_selection: Mc2CampaignMapSave = serde_json::from_slice(&bytes).unwrap();
        invalid_selection.semantic_spell_carry.as_mut().unwrap().selected = Some(missing_spell);
        let mut invalid_tier: Mc2CampaignMapSave = serde_json::from_slice(&bytes).unwrap();
        invalid_tier.semantic_spell_carry.as_mut().unwrap().progression = vec![Mc2SemanticSpellProgress {
            spell: first_spell,
            persistent_experience: 0,
            runtime_experience: 0,
            unlocked_tier: 0,
            selected_tier: 1,
        }];
        let mut duplicate_progress: Mc2CampaignMapSave = serde_json::from_slice(&bytes).unwrap();
        let progress = Mc2SemanticSpellProgress {
            spell: first_spell,
            persistent_experience: 0,
            runtime_experience: 0,
            unlocked_tier: 0,
            selected_tier: 0,
        };
        duplicate_progress.semantic_spell_carry.as_mut().unwrap().progression = vec![progress.clone(), progress];
        for mut malformed in [duplicate_family, invalid_selection, invalid_tier, duplicate_progress] {
            malformed.receipt_sha256 = malformed.compute_receipt_sha256();
            assert!(resolver.load_replay(&mut restored, guard, 7113, &serde_json::to_vec(&malformed).unwrap()).is_err(),
                "a re-digested but invalid carry must fail before campaign publication");
            assert_eq!(restored.identity(), before_identity);
            assert_eq!(resolver.save_replay(&restored).unwrap(), before_save);
            assert!(!resolver.pending_spell_carries.lock().unwrap().contains_key(&7113));
        }
        resolver
            .load_replay(&mut restored, guard, 7113, &bytes)
            .unwrap();
        assert!(restored.session().is_none());
        assert_eq!(resolver.save_replay(&restored).unwrap(), bytes);
        let guard = restored.identity().guard();
        resolver
            .campaign_menu_command(&mut restored, guard, CampaignMenuCommand::DismissResults)
            .unwrap();
        let mut retained_map = restored.campaign_menu_snapshot().unwrap();
        // Re-entering from Title has no active results sheet. Its completed
        // missions, frontier, spell carry and retained statistics remain.
        retained_map.completed_level_id = None;
        let guard = restored.identity().guard();
        resolver
            .campaign_menu_command(
                &mut restored,
                guard,
                CampaignMenuCommand::SelectMission {
                    level_id: resolver.flow.entry_level_id().clone(),
                },
            )
            .unwrap();
        let guard = restored.identity().guard();
        let title = resolver
            .campaign_menu_command(&mut restored, guard, CampaignMenuCommand::ReturnTitle)
            .unwrap();
        let title_save = resolver.save_replay(&restored).unwrap();
        assert_eq!(restored.identity(), title, "Title Save is observational");
        let mut title_restored = GameRuntime::<Mc2CampaignBackend>::title(7115).unwrap();
        let title_guard = title_restored.identity().guard();
        resolver
            .load_replay(&mut title_restored, title_guard, 7115, &title_save)
            .unwrap();
        assert_eq!(title_restored.identity().mode, RuntimeMode::Campaign);
        assert_eq!(
            title_restored.campaign_menu_snapshot().unwrap(),
            retained_map,
            "the original title Save loads its retained campaign at the unfinished map frontier"
        );
        let loading = resolver.new_game(&mut restored, title.guard()).unwrap();
        let map = resolver
            .show_new_game_map(&mut restored, loading.guard())
            .unwrap();
        assert_eq!(
            restored.campaign_menu_snapshot().unwrap(),
            retained_map,
            "Title New Game returns to the unfinished frontier without clearing retained progress"
        );
        assert_eq!(
            resolver
                .pending_spell_carries
                .lock()
                .unwrap()
                .get(&7113)
                .unwrap()
                .carry,
            carry
        );
        let reopened_map_save = resolver.save_replay(&restored).unwrap();
        let mut reopened_map = GameRuntime::<Mc2CampaignBackend>::title(7114).unwrap();
        let reopened_guard = reopened_map.identity().guard();
        resolver
            .load_replay(&mut reopened_map, reopened_guard, 7114, &reopened_map_save)
            .unwrap();
        assert_eq!(
            reopened_map.campaign_menu_snapshot().unwrap(),
            retained_map,
            "saving after Title preserves carry even though the map is no longer showing a completed results row"
        );
        assert!(
            resolver
                .campaign_menu_command(
                    &mut restored,
                    title.guard(),
                    CampaignMenuCommand::ResetCampaign
                )
                .is_err()
        );
        assert_eq!(
            restored.identity(),
            map,
            "stale reset leaves the campaign and carry intact"
        );
        let guard = restored.identity().guard();
        let loading = resolver
            .campaign_menu_command(&mut restored, guard, CampaignMenuCommand::StartMission)
            .unwrap();
        resolver
            .open_pending(&mut restored, loading.guard(), 7113)
            .unwrap();
        let installed = restored
            .session()
            .unwrap()
            .backend()
            .semantic_spell_carry()
            .unwrap();
        assert!(
            carry
                .acquired
                .iter()
                .all(|spell| installed.acquired.contains(spell))
        );
        assert!(
            !resolver
                .pending_spell_carries
                .lock()
                .unwrap()
                .contains_key(&7113)
        );
        let playing = restored.identity();
        let baseline = restored
            .session()
            .unwrap()
            .backend()
            .initial_semantic_spell_carry()
            .unwrap();
        let title = resolver
            .close_to_title(
                &mut restored,
                playing.guard(),
                playing.session.unwrap().guard(),
            )
            .unwrap();
        let loading = resolver.new_game(&mut restored, title.guard()).unwrap();
        let map = resolver
            .show_new_game_map(&mut restored, loading.guard())
            .unwrap();
        assert_eq!(restored.campaign_menu_snapshot().unwrap(), retained_map);
        assert_eq!(
            resolver
                .pending_spell_carries
                .lock()
                .unwrap()
                .get(&7113)
                .unwrap()
                .carry,
            baseline,
            "abandon retains entry progression rather than promoting in-level pickups or runtime XP"
        );
        let reset = resolver
            .campaign_menu_command(
                &mut restored,
                map.guard(),
                CampaignMenuCommand::ResetCampaign,
            )
            .unwrap();
        let cleared = reset.campaign_menu.unwrap();
        assert!(cleared.completed_levels.is_empty());
        assert!(cleared.level_statistics.is_empty());
        assert_eq!(
            cleared.selected_level_id.as_ref(),
            Some(resolver.flow.entry_level_id())
        );
        assert!(
            !resolver
                .pending_spell_carries
                .lock()
                .unwrap()
                .contains_key(&7113)
        );
    }

    #[test]
    fn campaign_map_save_retains_nonempty_cut_history_and_rejects_invalid_bits() {
        use crate::game_runtime::GameRuntime;

        let resolver = Mc2RuntimePackageResolver::load([
            Mc2CampaignInputs::new(level_one_descriptor_fixture_path()),
            Mc2CampaignInputs::new(descriptor_fixture_path()),
            Mc2CampaignInputs::new(level_three_descriptor_fixture_path()),
        ]).unwrap();
        let mut source = GameRuntime::<Mc2CampaignBackend>::title(7114).unwrap();
        // Controlled nonempty history exercises save validation; actual
        // playback/marking is checked by the media owner and remains separate.
        source.restore_played_cutscenes(0x21).unwrap();
        let saved = resolver.save_replay(&source).unwrap();
        let mut restored = GameRuntime::<Mc2CampaignBackend>::title(7115).unwrap();
        let guard = restored.identity().guard();
        resolver.load_replay(&mut restored, guard, 7115, &saved).unwrap();
        assert_eq!(restored.played_cutscenes(), 0x21);
        let mut invalid: Mc2CampaignMapSave = serde_json::from_slice(&saved).unwrap();
        invalid.played_cutscenes = Some(0x40);
        invalid.receipt_sha256 = invalid.compute_receipt_sha256();
        let mut target = GameRuntime::<Mc2CampaignBackend>::title(7116).unwrap();
        let before = target.identity();
        assert!(resolver.load_replay(&mut target, before.guard(), 7116, &serde_json::to_vec(&invalid).unwrap()).is_err());
        assert_eq!(target.identity(), before);
    }

    #[test]
    fn runtime_package_resolver_stale_guard_precedes_pending_spell_carry() {
        use crate::game_runtime::{
            GameRuntime, RuntimeGuardErrorCode, RuntimeMode, RuntimeTransitionError,
        };

        let resolver = Mc2RuntimePackageResolver::load([
            Mc2CampaignInputs::new(level_one_descriptor_fixture_path()),
            Mc2CampaignInputs::new(descriptor_fixture_path()),
            Mc2CampaignInputs::new(level_three_descriptor_fixture_path()),
        ])
        .unwrap();
        let mut runtime = GameRuntime::<Mc2CampaignBackend>::title(94).unwrap();
        let title = runtime.identity();
        let loading = resolver.new_game(&mut runtime, title.guard()).unwrap();
        let playing = resolver
            .open_pending(&mut runtime, loading.guard(), 94)
            .unwrap();
        let session_guard = playing.session.as_ref().unwrap().guard();
        let snapshot = runtime.session().unwrap().snapshot();
        let carry = runtime
            .session()
            .unwrap()
            .backend()
            .semantic_spell_carry()
            .unwrap();
        assert_eq!(
            resolver.accept_transition(&mut runtime, playing.guard(), session_guard),
            Err(RuntimeTransitionError::CompletionNotReady)
        );
        assert_eq!(runtime.identity(), playing);
        assert_eq!(runtime.session().unwrap().snapshot(), snapshot);

        let title = runtime.close(playing.guard(), session_guard).unwrap();
        let loading = resolver.new_game(&mut runtime, title.guard()).unwrap();
        let pending = Mc2PendingSpellCarry {
            session_generation: session_guard.generation + 1,
            destination_level: resolver.flow().entry_level_id().clone(),
            carry: carry.clone(),
            source_secret_announcement_count: 0,
        };
        // Reproduce only the resolver storage condition created by an accepted
        // edge. Opening/closing above uses the real package and public runtime
        // lifecycle; this fixture does not claim gameplay completion.
        resolver
            .pending_spell_carries
            .lock()
            .unwrap()
            .insert(loading.runtime_id, pending.clone());
        assert_eq!(loading.mode, RuntimeMode::Loading);
        assert!(runtime.session().is_none());

        assert!(matches!(
            resolver.cancel_loading(&mut runtime, playing.guard()),
            Err(RuntimeTransitionError::Guard(_))
        ));
        assert_eq!(runtime.identity(), loading);
        assert_eq!(
            resolver
                .pending_spell_carries
                .lock()
                .unwrap()
                .get(&loading.runtime_id),
            Some(&pending)
        );

        let rejected = resolver.accept_transition(&mut runtime, playing.guard(), session_guard);
        assert!(matches!(
            rejected,
            Err(RuntimeTransitionError::Guard(error))
                if error.code == RuntimeGuardErrorCode::GenerationMismatch
                    && error.expected == loading && error.actual == playing.guard()
        ));
        assert_eq!(runtime.identity(), loading);
        assert!(runtime.session().is_none());
        assert_eq!(
            resolver
                .pending_spell_carries
                .lock()
                .unwrap()
                .get(&loading.runtime_id),
            Some(&pending)
        );

        // A current outer guard retains the existing pending-carry rejection.
        let rejected = resolver.accept_transition(&mut runtime, loading.guard(), session_guard);
        assert!(matches!(
            rejected,
            Err(RuntimeTransitionError::InvalidRuntimeFlow { message })
                if message == "resolver already owns a pending spell carry for this runtime"
        ));
        assert_eq!(runtime.identity(), loading);
        assert_eq!(
            resolver
                .pending_spell_carries
                .lock()
                .unwrap()
                .get(&loading.runtime_id),
            Some(&pending)
        );
        let reopened = resolver
            .open_pending(&mut runtime, loading.guard(), 94)
            .unwrap();
        assert_eq!(reopened.mode, RuntimeMode::Playing);
        assert!(reopened.session.as_ref().unwrap().generation > session_guard.generation);
        assert_eq!(
            runtime
                .session()
                .unwrap()
                .backend()
                .semantic_spell_carry()
                .unwrap(),
            carry
        );
        assert!(
            !resolver
                .pending_spell_carries
                .lock()
                .unwrap()
                .contains_key(&loading.runtime_id)
        );
    }

    #[test]
    fn runtime_package_resolver_canonicalizes_order_and_rejects_open_flow_sets() {
        let level_one = level_one_descriptor_fixture_path();
        let level_two = descriptor_fixture_path();
        let level_three = level_three_descriptor_fixture_path();
        let forward = Mc2RuntimePackageResolver::load([
            Mc2CampaignInputs::new(&level_one),
            Mc2CampaignInputs::new(&level_two),
            Mc2CampaignInputs::new(&level_three),
        ])
        .unwrap();
        let reverse = Mc2RuntimePackageResolver::load([
            Mc2CampaignInputs::new(&level_three),
            Mc2CampaignInputs::new(&level_two),
            Mc2CampaignInputs::new(&level_one),
        ])
        .unwrap();
        assert_eq!(forward.flow(), reverse.flow());
        assert_eq!(
            forward.flow().bound_level_id(),
            forward.flow().entry_level_id()
        );

        let incomplete = Mc2RuntimePackageResolver::load([
            Mc2CampaignInputs::new(&level_one),
            Mc2CampaignInputs::new(&level_three),
        ])
        .unwrap_err();
        assert_eq!(incomplete.code, DefinitionErrorCode::DependencyFailed);

        let duplicate = Mc2RuntimePackageResolver::load([
            Mc2CampaignInputs::new(&level_one),
            Mc2CampaignInputs::new(&level_one),
            Mc2CampaignInputs::new(&level_two),
            Mc2CampaignInputs::new(&level_three),
        ])
        .unwrap_err();
        assert_eq!(duplicate.code, DefinitionErrorCode::DuplicateBinding);

        // No-Claim: this constructor gate proves only definition-derived,
        // order-independent closure for the three qualified resource roots.
        // It does not validate owner-cache bytes, install/discover packages,
        // open gameplay, or consume a completion edge.
    }

    fn publish_player_max_forward_speed(
        store: &WorkspaceStore,
        catalog: &SemanticCatalog,
        active: &GameDefinition,
        idempotency_key: &str,
        speed: i64,
    ) -> GameDefinition {
        let change_set = ChangeSetBuilder::new(
            "campaign-flight-authoring",
            active,
            idempotency_key,
            RequestedTiming::SessionReset,
        )
        .set_integer(IntegerParameter::PlayerMaxForwardSpeed, speed)
        .build()
        .expect("typed flight change set");
        let validation = store
            .validate(catalog, change_set.clone())
            .expect("flight change validates");
        assert!(validation.accepted, "{:#?}", validation.diagnostics);
        store
            .apply(
                catalog,
                change_set,
                &validation.receipt_hash,
                PublicationFault::None,
            )
            .expect("flight change publishes");
        store.active_definition().expect("published definition")
    }

