    #[test]
    fn campaign_backend_moves_real_level_three_area_trigger_and_runs_ordinary_group8() {
        const TRIGGER_SLOT: u16 = 224;
        const GROUP8_ROWS: &[u16] = &[208, 209, 210, 211, 212, 213, 214, 215];
        let root = level_three_descriptor_fixture_path();
        let catalog = default_catalog().unwrap();
        let base = load_mc2_campaign(&root, &catalog).unwrap();
        let trigger =
            sim_definition::adapter::stable_entity_id("switch.area_entry_trigger.at_218_93")
                .unwrap();
        let package_tile = TilePosition { x: 218, y: 93 };
        let authored_tile = TilePosition { x: 200, y: 80 };
        let package_entity = base.level_definition().unwrap().entity(&trigger).unwrap();
        assert_eq!(package_entity.position(), package_tile);
        assert_eq!(
            package_entity.position_access(),
            LevelEntityPositionAccess::SessionReset
        );

        let workspace_root = temporary_workspace_path("campaign-l3-area-trigger-placement");
        let store = WorkspaceStore::create(
            &workspace_root,
            "campaign-l3-area-trigger-placement",
            base.clone(),
        )
        .unwrap();
        let mut session = GameSession::open(
            &Mc2CampaignAdapter,
            Arc::new(base.clone()),
            75,
            Mc2CampaignInputs::new(&root),
        )
        .unwrap();
        let package_position =
            session.backend().campaign.simulation().entities()[usize::from(TRIGGER_SLOT)].position;

        let change_set = ChangeSetBuilder::new(
            "campaign-l3-area-trigger-placement",
            &base,
            "move-level-three-area-trigger",
            RequestedTiming::SessionReset,
        )
        .move_entity_from(trigger.clone(), package_tile, authored_tile)
        .build()
        .unwrap();
        let validation = store.validate(&catalog, change_set.clone()).unwrap();
        assert!(validation.accepted, "{:#?}", validation.diagnostics);
        store
            .apply(
                &catalog,
                change_set,
                &validation.receipt_hash,
                PublicationFault::None,
            )
            .unwrap();
        let published = store.active_definition().unwrap();
        assert_eq!(published.revision(), 2);
        assert_eq!(
            published
                .level_definition()
                .unwrap()
                .entity(&trigger)
                .unwrap()
                .position(),
            authored_tile
        );
        assert_eq!(session.identity().definition_hash, base.definition_hash());

        let authored_position = crate::Position {
            x: (authored_tile.x << 8) | (package_position.x & 0xff),
            y: (authored_tile.y << 8) | (package_position.y & 0xff),
            z: package_position.z,
        };
        let player = session
            .backend()
            .campaign
            .simulation()
            .session
            .state
            .live
            .core
            .state
            .entity_index;
        session
            .backend_mut()
            .campaign
            .simulation_mut()
            .set_level2_entity_position(player, authored_position)
            .unwrap();
        for _ in 0..8 {
            session
                .step(guard(&session), GameCommand::default())
                .unwrap();
        }
        assert!(session.backend().campaign.events().iter().all(|event| {
            !matches!(
                event,
                Mc2DispatchEvent::AuthoredGroupActivated { group: 8, .. }
            )
        }));
        assert_eq!(
            session.backend().campaign.simulation().entities()[usize::from(TRIGGER_SLOT)].position,
            package_position,
            "publication must not mutate the already-open package authority"
        );

        let reopened = session
            .reopen(guard(&session), Arc::new(published))
            .unwrap();
        assert_eq!(reopened.identity.generation, 2);
        assert_eq!(reopened.identity.definition_revision, 2);
        let authored_reset_hash = session.backend().campaign.state_hash();
        {
            let live = &session.backend().campaign.simulation.session.state.live;
            assert_eq!(
                live.economy.entities[usize::from(TRIGGER_SLOT)].position,
                authored_position
            );
            assert_eq!(
                live.level2_imported_switch_roots
                    .iter()
                    .find(|root| root.source_slot == TRIGGER_SLOT)
                    .unwrap()
                    .position,
                authored_position
            );
            assert_eq!(
                live.economy.map_chains().tile_of(TRIGGER_SLOT),
                u16::from_le_bytes([authored_tile.x as u8, authored_tile.y as u8])
            );
        }

        session
            .backend_mut()
            .campaign
            .simulation_mut()
            .set_level2_entity_position(player, package_position)
            .unwrap();
        for _ in 0..8 {
            session
                .step(guard(&session), GameCommand::default())
                .unwrap();
        }
        assert!(session.backend().campaign.events().iter().all(|event| {
            !matches!(
                event,
                Mc2DispatchEvent::AuthoredGroupActivated { group: 8, .. }
            )
        }));

        session
            .backend_mut()
            .campaign
            .simulation_mut()
            .set_level2_entity_position(player, authored_position)
            .unwrap();
        for _ in 0..8 {
            session
                .step(guard(&session), GameCommand::default())
                .unwrap();
            if session.backend().campaign.events().iter().any(|event| {
                matches!(
                    event,
                    Mc2DispatchEvent::AuthoredGroupActivated {
                        source_slot: TRIGGER_SLOT,
                        group: 8,
                        authored_indices,
                        ..
                    } if authored_indices.as_ref() == GROUP8_ROWS
                )
            }) {
                break;
            }
        }
        let compatibility = session.backend().campaign.simulation();
        assert!(compatibility.dispatch_events().iter().any(|event| {
            matches!(
                event,
                Mc2DispatchEvent::AuthoredGroupActivated {
                    source_slot: TRIGGER_SLOT,
                    group: 8,
                    authored_indices,
                    ..
                } if authored_indices.as_ref() == GROUP8_ROWS
            )
        }));
        assert!(
            compatibility
                .dispatch_events()
                .iter()
                .all(|event| !matches!(event, Mc2DispatchEvent::Error { .. }))
        );
        let live = &compatibility.session.state.live;
        assert_eq!(
            live.level2_model39_activated,
            BTreeSet::from([208, 209, 210, 211])
        );
        assert_eq!(
            live.level2_mana_attraction_activated,
            BTreeSet::from([212, 213, 214, 215])
        );
        assert_eq!(compatibility.economy().spheres().len(), 4);
        assert_eq!(
            compatibility
                .economy()
                .mana_attraction_fields()
                .iter()
                .map(|field| field.authored_index)
                .collect::<Vec<_>>(),
            vec![212, 213, 214, 215]
        );
        let fired = &live.economy.entities[usize::from(TRIGGER_SLOT)];
        assert!(fired.active && fired.drawing_disabled());

        session.reset(guard(&session)).unwrap();
        assert_eq!(session.backend().campaign.state_hash(), authored_reset_hash);
        let reset = &session.backend().campaign.simulation.session.state.live;
        assert_eq!(
            reset.economy.entities[usize::from(TRIGGER_SLOT)].position,
            authored_position
        );
        assert!(!reset.economy.entities[usize::from(TRIGGER_SLOT)].drawing_disabled());
        assert!(reset.level2_model39_activated.is_empty());
        assert!(reset.level2_mana_attraction_activated.is_empty());

        std::fs::remove_dir_all(&workspace_root).unwrap();
        // No-Claim: this proves one reset-imported Level 3 area trigger,
        // explicit reopen/reset, ordinary overlap cadence, and exact group-8
        // model-39/model-54 construction. It does not make the other area
        // triggers movable or prove groups 9/10, dynamic switches, save/replay,
        // or Unity presentation.
    }

    #[test]
    fn campaign_backend_binds_area_entry_overlap_extent_before_level_three_group8_after_reopen_and_reset()
     {
        const TRIGGER_RECORD: u16 = 207;
        const TRIGGER_SLOT: u16 = 224;
        const GROUP8_ROWS: &[u16] = &[208, 209, 210, 211, 212, 213, 214, 215];

        fn place_player_at_package_boundary(session: &mut GameSession<Mc2CampaignBackend>) {
            let compatibility = session.backend().campaign.simulation();
            let player = compatibility.state.entity_index;
            let trigger_position = compatibility.entities()[usize::from(TRIGGER_SLOT)].position;
            let player_half_width = i16::from_le_bytes(
                compatibility.entities()[usize::from(player)].record_bytes()[88..90]
                    .try_into()
                    .unwrap(),
            );
            let package_boundary =
                u16::try_from((2_i32 << 8) + i32::from(player_half_width)).unwrap();
            session
                .backend_mut()
                .campaign
                .simulation_mut()
                .set_level2_entity_position(
                    player,
                    crate::Position {
                        x: trigger_position.x.wrapping_add(package_boundary),
                        ..trigger_position
                    },
                )
                .unwrap();
        }

        fn step_until_group8(session: &mut GameSession<Mc2CampaignBackend>) -> bool {
            for _ in 0..8 {
                place_player_at_package_boundary(session);
                session
                    .step(guard(session), GameCommand::default())
                    .unwrap();
                if session.backend().campaign.events().iter().any(|event| {
                    matches!(
                        event,
                        Mc2DispatchEvent::AuthoredGroupActivated {
                            source_slot: TRIGGER_SLOT,
                            group: 8,
                            authored_indices,
                            ..
                        } if authored_indices.as_ref() == GROUP8_ROWS
                    )
                }) {
                    return true;
                }
            }
            false
        }

        let catalog = default_catalog().unwrap();
        let level_one = load_mc2_campaign(&level_one_descriptor_fixture_path(), &catalog).unwrap();
        let level_two = load_mc2_campaign(&descriptor_fixture_path(), &catalog).unwrap();
        let root = level_three_descriptor_fixture_path();
        let level_three = load_mc2_campaign(&root, &catalog).unwrap();
        for (definition, expected_count) in [(&level_one, 24), (&level_two, 16), (&level_three, 4)]
        {
            let configured = definition
                .level_definition()
                .unwrap()
                .entities()
                .iter()
                .filter(|entity| {
                    entity.kind() == LevelEntityKind::Switch(SwitchKind::AreaEntryTrigger)
                })
                .filter_map(|entity| entity.switch_overlap())
                .collect::<Vec<_>>();
            assert_eq!(configured.len(), expected_count);
            assert!(configured.iter().all(|config| {
                config.overlap_extent_tiles_access() == LevelEntityParameterAccess::SessionReset
                    && config.default_overlap_extent_tiles() == config.overlap_extent_tiles()
            }));
        }
        let trigger =
            sim_definition::adapter::stable_entity_id("switch.area_entry_trigger.at_218_93")
                .unwrap();
        let package_config = level_three
            .level_definition()
            .unwrap()
            .entity(&trigger)
            .unwrap()
            .switch_overlap()
            .unwrap();
        assert_eq!(package_config.default_overlap_extent_tiles(), 2);
        assert_eq!(package_config.overlap_extent_tiles(), 2);

        let workspace_root = temporary_workspace_path("campaign-l3-area-entry-overlap");
        let store = WorkspaceStore::create(
            &workspace_root,
            "campaign-l3-area-entry-overlap",
            level_three.clone(),
        )
        .unwrap();
        let wrong_family =
            sim_definition::adapter::stable_entity_id("switch.level_exit_gate.at_226_173").unwrap();
        let fake = ChangeSetBuilder::new(
            "campaign-l3-area-entry-overlap",
            &level_three,
            "reject-level-exit-gate-overlap",
            RequestedTiming::SessionReset,
        )
        .set_switch_overlap_extent(wrong_family, 4)
        .build()
        .unwrap();
        assert!(!store.validate(&catalog, fake).unwrap().accepted);

        let mut session = GameSession::open(
            &Mc2CampaignAdapter,
            Arc::new(level_three.clone()),
            97,
            Mc2CampaignInputs::new(&root),
        )
        .unwrap();
        let change_set = ChangeSetBuilder::new(
            "campaign-l3-area-entry-overlap",
            &level_three,
            "set-level-three-area-entry-overlap",
            RequestedTiming::SessionReset,
        )
        .set_switch_overlap_extent_from(trigger.clone(), 2, 4)
        .build()
        .unwrap();
        let validation = store.validate(&catalog, change_set.clone()).unwrap();
        assert!(validation.accepted, "{:#?}", validation.diagnostics);
        store
            .apply(
                &catalog,
                change_set,
                &validation.receipt_hash,
                PublicationFault::None,
            )
            .unwrap();
        let published = store.active_definition().unwrap();
        assert_eq!(
            published.semantic_target_value(
                &SemanticId::parse("switch.area_entry_trigger.at_218_93.overlap_extent_tiles",)
                    .unwrap(),
            ),
            Some(sim_definition::SemanticValue::Integer(4))
        );

        let package_root = session
            .backend()
            .campaign
            .simulation()
            .session
            .state
            .live
            .level2_imported_switch_roots
            .iter()
            .find(|root| root.authored_index == TRIGGER_RECORD)
            .copied()
            .unwrap();
        assert_eq!(package_root.word_10, 2);
        place_player_at_package_boundary(&mut session);
        assert!(!step_until_group8(&mut session));

        session
            .reopen(guard(&session), Arc::new(published))
            .unwrap();
        let authored_reset_hash = session.backend().campaign.state_hash();
        let compatibility = session.backend().campaign.simulation();
        let authored_root = compatibility
            .session
            .state
            .live
            .level2_imported_switch_roots
            .iter()
            .find(|root| root.authored_index == TRIGGER_RECORD)
            .copied()
            .unwrap();
        assert_eq!(authored_root.word_10, 4);
        place_player_at_package_boundary(&mut session);
        assert!(step_until_group8(&mut session));
        let fired = &session.backend().campaign.simulation().entities()[usize::from(TRIGGER_SLOT)];
        assert!(fired.active && fired.drawing_disabled());

        session.reset(guard(&session)).unwrap();
        assert_eq!(session.backend().campaign.state_hash(), authored_reset_hash);
        let reset = session.backend().campaign.simulation();
        assert_eq!(
            reset
                .session
                .state
                .live
                .level2_imported_switch_roots
                .iter()
                .find(|root| root.authored_index == TRIGGER_RECORD)
                .map(|root| root.word_10),
            Some(4)
        );
        place_player_at_package_boundary(&mut session);
        assert!(step_until_group8(&mut session));

        std::fs::remove_dir_all(&workspace_root).unwrap();
        // No-Claim: proves all package-present Area Entry triggers expose their
        // source word-10 overlap extent, and one real Level 3 reset-imported
        // trigger binds 2-to-4 across guarded publication, old-session
        // isolation, strict overlap, exact group-8 activation, consumption,
        // and reset. It does not author Area Exit/Level Exit/Objective triggers,
        // target groups, cadence, placement, player bounds, save/replay, or UI.
    }

    #[test]
    fn retained_portal_workspace_binds_only_its_authored_content_and_preserves_reset_guards() {
        use crate::game_definition::WorkspaceStore;
        use crate::level_definition::{LevelDefinition, LevelEntityKind, SceneryKind, SwitchKind};
        let package = std::env::var_os("MC_SOURCE4_CAMPAIGN_PACKAGE").map_or_else(
            || PathBuf::from(env!("CARGO_MANIFEST_DIR"))
                .join("../../../generated/dragon-bee-20261105-integration/level5-owner-current/level5"),
            PathBuf::from,
        );
        let catalog = default_catalog().unwrap();
        let original = load_mc2_campaign(&package, &catalog).unwrap();
        let original_level = original.level_definition().unwrap();
        let mut encoded = serde_json::to_value(original_level).unwrap();
        let mut pair = Vec::new();
        for (index, entity) in original_level.entities().iter().enumerate() {
            if matches!(
                entity.kind(),
                LevelEntityKind::Scenery(SceneryKind::SecretPortal)
                    | LevelEntityKind::Switch(SwitchKind::SecretEntryTrigger)
            ) {
                assert_eq!(entity.activation_group().unwrap().get(), 6);
                encoded["entities"][index]["activation_group"] = serde_json::json!(4);
                pair.push(index);
            }
        }
        assert_eq!(pair.len(), 2);
        let level: LevelDefinition = serde_json::from_value(encoded.clone()).unwrap();
        // Ordinary reopen/reset admission stays strict; only a new authored
        // baseline may adopt this content, with its own immutable hash.
        assert!(
            level
                .verify_session_reset_variant_of(original_level)
                .is_err()
        );
        let variant = sim_definition::adapter::with_level_definition(original.clone(), level);
        assert_ne!(variant.definition_hash(), original.definition_hash());
        assert_eq!(variant.package_graph_hash(), original.package_graph_hash());
        assert_eq!(
            variant.artifact_graph_hash(),
            original.artifact_graph_hash()
        );
        assert_eq!(variant.provenance(), original.provenance());
        assert!(
            variant
                .verify_semantic_variant_of(&original, &catalog)
                .is_err()
        );
        let workspace = std::env::var_os("MC_RETAINED_SECRET_WORKSPACE").map_or_else(
            || PathBuf::from(env!("CARGO_MANIFEST_DIR"))
                .join("../../../generated/secret-entry-20261110-integration/retained-source4-workspace"),
            PathBuf::from,
        );
        if !workspace.join("workspace-state.json").exists() {
            // WorkspaceStore owns its canonical filename and exclusive create.
            // Repeated checks may reopen the identical retained authored input.
            match WorkspaceStore::create(&workspace, "source4-secret-portal", variant.clone()) {
                Ok(_) => {}
                Err(error)
                    if error.code
                        == crate::game_definition::TransactionErrorCode::WorkspaceExists => {}
                Err(error) => panic!("cannot retain portal workspace: {error}"),
            }
        }
        let retained = WorkspaceStore::open(&workspace)
            .active_definition()
            .unwrap();
        assert_eq!(retained, variant);
        let mut game = GameSession::open(
            &Mc2CampaignAdapter,
            Arc::new(retained.clone()),
            624_004,
            Mc2CampaignInputs::new(&package),
        )
        .unwrap();
        let features = game
            .backend()
            .campaign
            .simulation()
            .session
            .state
            .live
            .mission
            .authored_features()
            .to_vec();
        assert_eq!(features[75].activation_group, 4);
        assert_eq!(features[76].activation_group, 4);
        let original_features = crate::level1_mission::parse_authored_features(
            &std::fs::read(package.join("authored-level.bin")).unwrap(),
        )
        .unwrap();
        for (before, after) in original_features.iter().zip(&features) {
            let mut expected = *before;
            if matches!(before.index, 75 | 76) {
                expected.activation_group = 4;
            }
            assert_eq!(*after, expected);
        }
        game.advance(game.identity().guard(), GameCommand::default())
            .unwrap();
        let old_guard = game.identity().guard();
        game.reset(old_guard).unwrap();
        assert!(game.snapshot().identity.generation > old_guard.generation);
        assert_eq!(
            game.definition().definition_hash(),
            retained.definition_hash()
        );
        assert_eq!(
            game.backend()
                .campaign
                .simulation()
                .session
                .state
                .live
                .mission
                .authored_features(),
            features
        );
        assert!(game.advance(old_guard, GameCommand::default()).is_err());
        // The installed resolver must read the retained workspace itself,
        // rather than relying on the definition supplied to the direct open.
        // These real packages close the existing catalog; no campaign frontier
        // or completed predecessor is constructed to open this local session.
        let generated = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../../generated");
        let mut installed_inputs = [
            "mc-bhq8-level1-collision-v5-night",
            "level2-day-block32-campaign-v2",
            "level3-day-block32-campaign-recipe-v2",
            "mc-bhq6-ordinary-20261025-zclu5fjj/level4",
            "mc-paj2-source30-campaign-package",
        ]
        .map(|path| Mc2CampaignInputs::new(generated.join(path)))
        .to_vec();
        installed_inputs.push(Mc2CampaignInputs::new(&package).with_authored_workspace(&workspace));
        let resolver = Mc2RuntimePackageResolver::load(installed_inputs).unwrap();
        let source4_id = original.runtime_flow().unwrap().bound_level_id();
        let installed = resolver.package(source4_id).unwrap();
        assert_eq!(installed.selection, CampaignSelection::ordinary(5).unwrap());
        assert_eq!(installed.inputs.package_root, package);
        assert_eq!(
            installed.inputs.authored_workspace.as_ref(),
            Some(&workspace)
        );
        assert_eq!(
            installed.definition.level_definition(),
            retained.level_definition()
        );
        assert_eq!(
            installed.definition.package_graph_hash(),
            retained.package_graph_hash()
        );
        assert_eq!(
            installed.definition.artifact_graph_hash(),
            retained.artifact_graph_hash()
        );
        assert_eq!(installed.definition.provenance(), retained.provenance());
        let installed_flow =
            runtime_catalog::compose(CampaignSelection::ordinary(5).unwrap(), 5, &[30]).unwrap();
        assert_eq!(installed.definition.runtime_flow(), Some(&installed_flow));
        assert_eq!(
            *installed.definition,
            with_level_and_runtime_flow(
                retained.clone(),
                retained.level_definition().unwrap().clone(),
                installed_flow
            )
        );
        let mut installed_game = GameSession::open(
            &Mc2CampaignAdapter,
            Arc::clone(&installed.definition),
            624_005,
            installed.inputs.clone(),
        )
        .unwrap();
        assert_eq!(installed_game.definition(), &installed.definition);
        assert_eq!(
            installed_game
                .backend()
                .campaign
                .simulation()
                .session
                .state
                .live
                .mission
                .authored_features(),
            features
        );
        let installed_before = installed_game.identity();
        installed_game
            .step(installed_before.guard(), GameCommand::default())
            .unwrap();
        assert!(installed_game.identity().tick > installed_before.tick);
        assert!(
            installed_game
                .backend()
                .campaign
                .simulation()
                .dispatch_events()
                .iter()
                .all(|event| !matches!(event, Mc2DispatchEvent::Error { .. }))
        );
        eprintln!(
            "retainedresolver: level={} workspace={} installeddefinition={} tick={}",
            source4_id.as_str(),
            workspace.display(),
            installed_game.definition().definition_hash(),
            installed_game.identity().tick
        );
        for case in 0..4 {
            let mut invalid = encoded.clone();
            match case {
                0 => invalid["entities"][pair[0]]["activation_group"] = serde_json::json!(0),
                1 => invalid["entities"][pair[1]]["activation_group"] = serde_json::json!(3),
                2 => {
                    let other = (0..original_level.entities().len())
                        .find(|index| !pair.contains(index))
                        .unwrap();
                    let x = invalid["entities"][other]["position"]["x"]
                        .as_u64()
                        .unwrap();
                    invalid["entities"][other]["position"]["x"] = serde_json::json!((x + 1) & 255);
                    // Ensure the independent original row actually changed.
                    assert_ne!(invalid, encoded);
                }
                _ => invalid["objectives"] = serde_json::json!([]),
            }
            if let Ok(level) = serde_json::from_value::<LevelDefinition>(invalid) {
                let invalid =
                    sim_definition::adapter::with_level_definition(original.clone(), level);
                assert!(
                    GameSession::open(
                        &Mc2CampaignAdapter,
                        Arc::new(invalid),
                        624_010 + case,
                        Mc2CampaignInputs::new(&package)
                    )
                    .is_err(),
                    "case {case}"
                );
            }
        }
        let mut corrupt = serde_json::to_value(&retained).unwrap();
        corrupt["provenance"]["source_sha256"] = serde_json::json!("00".repeat(32));
        let corrupt = serde_json::from_value::<GameDefinition>(corrupt).unwrap();
        assert_ne!(corrupt.provenance(), retained.provenance());
        assert!(
            GameSession::open(
                &Mc2CampaignAdapter,
                Arc::new(corrupt),
                624_020,
                Mc2CampaignInputs::new(&package)
            )
            .is_err()
        );
        eprintln!(
            "retainedportalworkspace={} definition={} basepackage={}",
            workspace.display(),
            retained.definition_hash(),
            retained.package_graph_hash()
        );
    }

    #[test]
    fn actual_tklom_dragon_absence_secret_entry_and_karakir_parent_return() {
        use crate::native_world::player_lifecycle_tests::{
            complete_tklom_rival_objectives_for_test, rival_test_contact as contact,
            rival_test_sim as sim, rival_test_sim_mut as sim_mut, rival_test_step as step,
        };
        use crate::game_runtime::{
            CampaignMenuCommand, CampaignMenuPhase, CampaignSaveState, GameRuntime,
            RuntimeMode, RuntimeTransitionError, SecretTransitionKind,
        };
        use crate::native_world::Mc2DispatchEvent;
        use crate::world::portals::OrdinaryExitRoute;

        let generated = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../../generated");
        let resources = std::env::var_os("MC_SECRET_RETURN_RESOURCES").map(PathBuf::from)
            .unwrap_or_else(|| generated.join("campaign-original-environments/installed-campaign-resources.json"));
        let resources: Vec<BTreeMap<String, String>> = serde_json::from_slice(
            &std::fs::read(resources).expect("normal installed campaign resources"),
        ).unwrap();
        assert_eq!(resources.len(), 30);
        let resolver = Mc2RuntimePackageResolver::load(resources.iter().map(|row|
            Mc2CampaignInputs::with_owner_cache(&row["package"], &row["owner"]),
        )).unwrap();
        let source = resolver.by_level.values().find(|package|
            package.selection == CampaignSelection::ordinary(5).unwrap()).unwrap();
        let secret = resolver.by_level.values().find(|package|
            package.selection == CampaignSelection::secret_destination(30).unwrap()).unwrap();
        let origin = source.definition.runtime_flow().unwrap().bound_level_id().clone();
        let secret_id = secret.definition.runtime_flow().unwrap().bound_level_id().clone();
        let origin_index = resolver.flow().entries().iter().position(|row| row.level_id() == &origin).unwrap();
        let completed_levels = resolver.flow().entries().iter().take(origin_index)
            .map(|row| row.level_id().clone()).collect::<Vec<_>>();
        let parent = CampaignSaveState {
            definition: resolver.package(resolver.flow().entry_level_id()).unwrap().definition.as_ref().clone(),
            phase: CampaignMenuPhase::MissionSelect,
            completed_level_id: None,
            selected_level_id: Some(origin.clone()),
            completed_levels,
            level_statistics: Vec::new(),
        };
        // Declared arrival frontier and Possession inventory. All T'Klom
        // objectives, source producers, contacts and portal outcomes are live.
        let mut runtime = GameRuntime::<Mc2CampaignBackend>::title(8450).unwrap();
        install_owner_return_media(&mut runtime);
        let map = runtime.restore_campaign_resolved(runtime.identity().guard(), parent.clone(), Default::default(),
            |definition, selected| {
                resolver.exact_package_for_definition(definition)?;
                resolver.package(selected).map(|package| Arc::clone(&package.definition))
                    .ok_or_else(|| RuntimeTransitionError::InvalidRuntimeFlow {
                        message: "T'Klom parent must be installed".to_owned(),
                    })
            }).unwrap();
        let loading = resolver.campaign_menu_command(&mut runtime, map.guard(), CampaignMenuCommand::StartMission).unwrap();
        resolver.open_pending(&mut runtime, loading.guard(), 8450).unwrap();
        runtime.session_mut().unwrap().backend_mut().campaign.simulation_mut()
            .apply_carried_spell_families(&[1], Some(1)).unwrap();
        let game = runtime.session_mut().unwrap();
        let features = sim(game).mission().authored_features();
        assert_eq!((features[73].kind, features[73].subtype, features[73].activation_group, features[73].stage_tag), (11, 13, 1, 6));
        assert_eq!((features[75].kind, features[75].subtype, features[75].activation_group), (14, 4, 6));
        assert_eq!((features[76].kind, features[76].subtype, features[76].activation_group), (11, 31, 6));
        let expected_group = features.iter().filter(|row| row.kind != 0 && row.activation_group == 6)
            .map(|row| row.index).collect::<Vec<_>>();
        let initial_dragons = sim(game).source_arena().rebuilt_class5_model_slots()[0].iter()
            .map(|slot| sim(game).source_arena().handle(*slot).unwrap()).collect::<Vec<_>>();
        assert_eq!(initial_dragons.len(), 5, "five real reset Dragons block the group6 absence producer");
        assert!(sim(game).economy().authored_switch_producers().iter().all(|row| row.authored_index != 73));
        assert!(sim(game).economy().authored_class14().iter().all(|row| row.authored_index != 75));
        complete_tklom_rival_objectives_for_test(game);
        let player = sim(game).state.entity_index;
        let gate = *sim(game).economy().authored_switch_producers().iter()
            .find(|row| row.active && row.authored_index == 73 && row.model == 13 && row.stage_tag == 6)
            .expect("actual objective-produced Dragon absence controller73");
        let gate_handle = sim(game).source_arena().handle(gate.source_entity_index).unwrap();
        let dragons = sim(game).source_arena().rebuilt_class5_model_slots()[0].iter()
            .filter_map(|slot| sim(game).source_arena().handle(*slot)).collect::<Vec<_>>();
        assert!(!dragons.is_empty() && dragons.iter().all(|handle| initial_dragons.contains(handle)),
            "actual source Dragons must still block controller73: initial={initial_dragons:?}, current={dragons:?}");
        let survivor = *dragons.last().unwrap();
        for handle in &dragons[..dragons.len()-1] {
            let life = sim(game).entities()[usize::from(handle.source_slot)].life;
            contact(game, handle.source_slot, player, life);
        }
        for _ in 0..256 {
            step(game);
            assert!(sim(game).economy().authored_class14().iter().all(|row| row.authored_index != 75),
                "a living Dragon must prevent the actual group6 portal producer");
            let remaining = &sim(game).source_arena().rebuilt_class5_model_slots()[0];
            if remaining.as_slice() == [survivor.source_slot] { break; }
        }
        assert_eq!(sim(game).source_arena().handle(survivor.source_slot), Some(survivor));
        assert_eq!(sim(game).source_arena().rebuilt_class5_model_slots()[0], [survivor.source_slot]);
        assert_eq!(sim(game).source_arena().handle(gate.source_entity_index), Some(gate_handle));
        for _ in 0..4 {
            step(game);
            assert!(sim(game).economy().authored_class14().iter().all(|row| row.authored_index != 75));
            assert_eq!(sim(game).source_arena().handle(survivor.source_slot), Some(survivor));
        }
        let life = sim(game).entities()[usize::from(survivor.source_slot)].life;
        contact(game, survivor.source_slot, player, life);
        let mut produced = false;
        for _ in 0..256 {
            step(game);
            if let Some(actual) = sim(game).dispatch_events().iter().find_map(|event| match event {
                Mc2DispatchEvent::AuthoredGroupActivated { source_slot, group: 6, authored_indices, .. }
                    if *source_slot == gate.source_entity_index => Some(authored_indices),
                _ => None,
            }) {
                assert_eq!(actual.as_ref(), expected_group.as_slice());
                produced = true;
                break;
            }
        }
        assert!(produced, "actual Dragon absence and source countdown must publish the entire original group6");
        let group_dragons = sim(game).economy().authored_class5().iter()
            .filter(|row| row.active && row.model == 0 && [146, 147, 150, 151, 152, 153].contains(&row.authored_index))
            .map(|row| (row.authored_index, sim(game).source_arena().handle(row.source_entity_index)))
            .collect::<Vec<_>>();
        assert_eq!(group_dragons.len(), 6, "the same real group6 scan constructs its six authored Dragons");
        assert!(group_dragons.iter().all(|(_, handle)| handle.is_some()));
        let portal = *sim(game).economy().authored_class14().iter()
            .find(|row| row.active && row.authored_index == 75 && row.model == 4)
            .expect("actual authored secret portal75");
        let trigger = *sim(game).economy().authored_switch_producers().iter()
            .find(|row| row.active && row.authored_index == 76 && row.model == 31)
            .expect("actual authored secret entry76");
        let portal_handle = sim(game).source_arena().handle(portal.source_entity_index).unwrap();
        let trigger_handle = sim(game).source_arena().handle(trigger.source_entity_index).unwrap();
        assert_ne!(portal_handle, trigger_handle);
        assert_eq!((portal.position.x >> 8, portal.position.y >> 8), (186, 213));
        assert_eq!((trigger.position.x >> 8, trigger.position.y >> 8), (161, 222));
        assert_eq!(portal.control_flags & 1, 1, "actual portal is hidden until the source overlap");
        assert!(!sim(game).secret_entry_ready());
        assert!(sim(game).canonical_player_life_for_test() >= 0);
        let mut arrival = trigger.position;
        arrival.z = sim(game).canonical_terrain().ground_height(arrival)
            .checked_add(sim(game).profile().ground_clearance).unwrap();
        assert_eq!(crate::resolve_legacy_movement(&mut crate::FlightState::default(), arrival, arrival,
            sim(game).profile(), sim(game).canonical_terrain()), crate::MovementResolution::Accept(arrival));
        sim_mut(game).set_level2_entity_position(player, arrival).unwrap();
        for _ in 0..700 {
            if sim(game).secret_entry_ready() { break; }
            step(game);
        }
        let entry = sim(game).level_exit_sequence();
        assert!(entry.complete && sim(game).secret_entry_ready());
        assert_eq!((entry.trigger_entity_index, entry.portal_entity_index, entry.result_code),
            (trigger_handle.source_slot, portal_handle.source_slot, 0x1a));
        assert!(sim(game).source_arena().resolve(trigger_handle).is_none(), "the actual entry trigger reclaims");
        assert_eq!(sim(game).source_arena().handle(portal_handle.source_slot), Some(portal_handle));
        let inherited = game.backend().transition_spell_carry().unwrap();
        let outer = runtime.identity().guard();
        let session_guard = runtime.session().unwrap().identity().guard();
        let entered = resolver.advance_secret_if_ready(&mut runtime, outer, session_guard).unwrap()
            .expect("the actual source entry result must open Karakir through the resolver");
        assert!(entered.verify());
        assert_eq!(entered.kind, SecretTransitionKind::Entry);
        assert_eq!(runtime.session().unwrap().definition().runtime_flow().unwrap().bound_level_id(), &secret_id);
        assert_eq!(runtime.session().unwrap().backend().initial_semantic_spell_carry().unwrap(), inherited);
        assert_eq!(runtime.session().unwrap().backend().campaign.simulation().level_exit_sequence().ordinary_exit_route,
            OrdinaryExitRoute::CampaignMap);
        assert_eq!(crate::native_world::tests::complete_karakir_earned_mana_and_exit(runtime.session_mut().unwrap()), 0x0a);
        let won = runtime.session().unwrap();
        let GameCompletionStatus::Completed { completion } = won.backend().completion_status()
            else { panic!("Karakir's actual exit must publish completion") };
        let statistics = completion.statistics.unwrap();
        let carry = won.backend().transition_spell_carry().unwrap();
        let session_guard = won.identity().guard();
        let outer = runtime.identity().guard();
        let returned = resolver.advance_secret_if_ready(&mut runtime, outer, session_guard)
            .unwrap().expect("the actual secret completion must return to the retained parent");
        assert!(returned.verify());
        assert_eq!(returned.kind, SecretTransitionKind::CompletedReturn);
        assert_eq!(returned.origin_level_id, origin);
        assert_eq!(returned.after.mode, RuntimeMode::Campaign);
        assert!(runtime.session().is_none());
        let mut expected_parent = parent;
        expected_parent.completed_levels.push(origin.clone());
        assert_eq!(runtime.campaign_save_state().unwrap(), expected_parent);
        assert_eq!(runtime.secret_flow_state().completed_secret_levels(), std::slice::from_ref(&secret_id));
        let results = runtime.secret_flow_state().completed_secret_statistics();
        assert_eq!(results.len(), 1);
        assert_eq!(results[0].level_id, secret_id);
        assert_eq!(results[0].statistics, statistics);
        assert!(runtime.campaign_return_active(), "first T'Klom return queues source CUT1");
        play_owner_return_clip(&mut runtime, "cut1", 529, None);
        assert_eq!(runtime.played_cutscenes(), 1);
        let bytes = resolver.save_replay(&runtime).unwrap();
        let mut cold = GameRuntime::<Mc2CampaignBackend>::title(8451).unwrap();
        let cold_guard = cold.identity().guard();
        let restored = resolver.load_replay(&mut cold, cold_guard, 8451, &bytes).unwrap();
        assert_eq!(resolver.save_replay(&cold).unwrap(), bytes);
        let loading = resolver.campaign_menu_command(&mut cold, restored.guard(), CampaignMenuCommand::StartMission).unwrap();
        resolver.open_pending(&mut cold, loading.guard(), 8451).unwrap();
        assert_eq!(cold.session().unwrap().definition().runtime_flow().unwrap().bound_level_id(), &origin);
        assert_eq!(cold.session().unwrap().backend().initial_semantic_spell_carry().unwrap(), carry);
        assert_eq!(cold.session().unwrap().backend().semantic_spell_carry().unwrap(), carry);
        assert_eq!(cold.session().unwrap().backend().campaign.simulation().level_exit_sequence().ordinary_exit_route,
            OrdinaryExitRoute::CampaignMap);
    }

